item.description:
柚子茶室 https://yoziming.github.io/post/230115-spring-security-login-captcha/ -<h1 id="spring-security登入加上圖形驗證碼">Spring Security登入加上圖形驗證碼</h1>
<ul>
<li>效果</li>
</ul>
<p><img src="image-20221208144125814.png" alt="image-20221208144125814"></p>
<h3 id="前端">前端</h3>
<ul>
<li>
<p>帳號密碼+驗證碼很單純不多說</p>
</li>
<li>
<p>點圖片刷新:</p>
</li>
<li>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js">	<span style="color:#8b008b;font-weight:bold">function</span> reloadCaptcha() {
		$(<span style="color:#cd5555">&#34;#captcha&#34;</span>).attr(<span style="color:#cd5555">&#34;src&#34;</span>, <span style="color:#cd5555">&#34;{登入的url}/getCaptcha?t=&#34;</span> + <span style="color:#8b008b;font-weight:bold">new</span> <span style="color:#658b00">Date</span>().getTime());
	}
</code></pre></div></li>
</ul>
<h3 id="獲取驗證碼圖片">獲取驗證碼圖片</h3>
<ul>
<li>將密碼存到Session，也可以存到Redis，這邊用最簡單的方法</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java">	<span style="color:#228b22">/**
</span><span style="color:#228b22">	 * 獲取驗證碼圖片
</span><span style="color:#228b22">	 */</span>
	<span style="color:#707a7c">@GetMapping</span>(<span style="color:#cd5555">&#34;/getCaptcha&#34;</span>)
	<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">getCaptcha</span>(HttpServletRequest request,HttpServletResponse response) <span style="color:#8b008b;font-weight:bold">throws</span> IOException {
		<span style="color:#228b22">// 生成驗證碼圖片，寬 高
</span><span style="color:#228b22"></span>		ShearCaptcha captcha = CaptchaUtil.<span style="color:#658b00">createShearCaptcha</span>(160, 45, 4, 3);
		<span style="color:#228b22">// 4位純數字，去除0跟7
</span><span style="color:#228b22"></span>		RandomGenerator randomGenerator = <span style="color:#8b008b;font-weight:bold">new</span> RandomGenerator(<span style="color:#cd5555">&#34;12345689&#34;</span>, 4);
		captcha.<span style="color:#658b00">setGenerator</span>(randomGenerator);
		<span style="color:#228b22">// Console.log(&#34;驗證碼code: &#34;+ captcha.getCode());
</span><span style="color:#228b22"></span>		<span style="color:#228b22">// 指定響應頭給瀏覽器
</span><span style="color:#228b22"></span>		response.<span style="color:#658b00">setContentType</span>(<span style="color:#cd5555">&#34;image/png&#34;</span>); <span style="color:#228b22">// 告訴瀏覽器輸出內容為圖片
</span><span style="color:#228b22"></span>		response.<span style="color:#658b00">setHeader</span>(<span style="color:#cd5555">&#34;Pragma&#34;</span>, <span style="color:#cd5555">&#34;No-cache&#34;</span>); <span style="color:#228b22">// 禁止瀏覽器緩存
</span><span style="color:#228b22"></span>		response.<span style="color:#658b00">setHeader</span>(<span style="color:#cd5555">&#34;Cache-Control&#34;</span>, <span style="color:#cd5555">&#34;no-cache&#34;</span>);
		request.<span style="color:#658b00">getSession</span>().<span style="color:#658b00">setAttribute</span>(<span style="color:#cd5555">&#34;captchaCode&#34;</span>, captcha.<span style="color:#658b00">getCode</span>());
		<span style="color:#228b22">// 输出流给前端
</span><span style="color:#228b22"></span>		captcha.<span style="color:#658b00">write</span>(response.<span style="color:#658b00">getOutputStream</span>());
	}
</code></pre></div><h3 id="exception">Exception</h3>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">VerificationCodeException</span> <span style="color:#8b008b;font-weight:bold">extends</span> AuthenticationException {
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#008b45">VerificationCodeException</span>(){
        <span style="color:#8b008b;font-weight:bold">super</span>(<span style="color:#cd5555">&#34;驗證碼校驗失敗&#34;</span>);
    }
}
</code></pre></div><h3 id="filter">Filter</h3>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 登入時的圖形驗證碼過濾器
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@Component</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">VerificationCodeFilter</span> <span style="color:#8b008b;font-weight:bold">extends</span> OncePerRequestFilter {

    <span style="color:#707a7c">@Override</span>
    <span style="color:#8b008b;font-weight:bold">protected</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">doFilterInternal</span>(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain)
            <span style="color:#8b008b;font-weight:bold">throws</span> ServletException, IOException {
        <span style="color:#8b008b;font-weight:bold">if</span> (!<span style="color:#cd5555">&#34;/login&#34;</span>.<span style="color:#658b00">equals</span>(request.<span style="color:#658b00">getRequestURI</span>())) {
            filterChain.<span style="color:#658b00">doFilter</span>(request, response);
        } <span style="color:#8b008b;font-weight:bold">else</span> {
            <span style="color:#8b008b;font-weight:bold">try</span> {
                verificationCode(request);
                filterChain.<span style="color:#658b00">doFilter</span>(request, response);
            } <span style="color:#8b008b;font-weight:bold">catch</span> (VerificationCodeException e) {
                <span style="color:#8b008b;font-weight:bold">new</span> FormLoginFailureHandler().<span style="color:#658b00">onAuthenticationFailure</span>(request, response, e);
            }
        }
    }

    <span style="color:#8b008b;font-weight:bold">private</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">verificationCode</span>(HttpServletRequest request){
        String captcha = request.<span style="color:#658b00">getParameter</span>(<span style="color:#cd5555">&#34;captchaCode&#34;</span>);
        HttpSession session = request.<span style="color:#658b00">getSession</span>();
        String saveCaptcha = (String) session.<span style="color:#658b00">getAttribute</span>(<span style="color:#cd5555">&#34;captchaCode&#34;</span>);
        session.<span style="color:#658b00">removeAttribute</span>(<span style="color:#cd5555">&#34;captchaCode&#34;</span>);
        <span style="color:#8b008b;font-weight:bold">if</span> (ObjectUtils.<span style="color:#658b00">isEmpty</span>(captcha) || ObjectUtils.<span style="color:#658b00">isEmpty</span>(saveCaptcha) || !captcha.<span style="color:#658b00">equals</span>(saveCaptcha)) {
            <span style="color:#8b008b;font-weight:bold">throw</span> <span style="color:#8b008b;font-weight:bold">new</span> VerificationCodeException();
        }
    }
}
</code></pre></div><h3 id="handler">Handler</h3>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Component</span>
<span style="color:#707a7c">@Slf4j</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">VerificationCodeFailureHandler</span> <span style="color:#8b008b;font-weight:bold">implements</span> AuthenticationFailureHandler {

    <span style="color:#707a7c">@Override</span>
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">onAuthenticationFailure</span>(HttpServletRequest request, HttpServletResponse response,
            AuthenticationException exception) <span style="color:#8b008b;font-weight:bold">throws</span> IOException, ServletException {
        log.<span style="color:#658b00">info</span>(<span style="color:#cd5555">&#34;login fail, msg: {}&#34;</span>, exception.<span style="color:#658b00">getMessage</span>());
        response.<span style="color:#658b00">setContentType</span>(<span style="color:#cd5555">&#34;application/json;charset=UTF-8&#34;</span>);
        response.<span style="color:#658b00">getWriter</span>().<span style="color:#658b00">write</span>(JSON.<span style="color:#658b00">toJSONString</span>(ResultVO.<span style="color:#658b00">error</span>(10000, exception.<span style="color:#658b00">getMessage</span>())));
    }
}
</code></pre></div><h3 id="securityconfig">SecurityConfig</h3>
<ul>
<li>注意至少要先設定登入頁與getCaptcha是可以無條件通過的</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java">        <span style="color:#707a7c">@Override</span>
        <span style="color:#8b008b;font-weight:bold">protected</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">configure</span>(HttpSecurity http) <span style="color:#8b008b;font-weight:bold">throws</span> Exception {
            http.<span style="color:#658b00">authorizeRequests</span>() <span style="color:#228b22">//
</span><span style="color:#228b22"></span>                    .<span style="color:#658b00">antMatchers</span>( <span style="color:#228b22">//
</span><span style="color:#228b22"></span>                    ).<span style="color:#658b00">permitAll</span>().<span style="color:#658b00">anyRequest</span>().<span style="color:#658b00">authenticated</span>();

            http.<span style="color:#658b00">csrf</span>() <span style="color:#228b22">//
</span><span style="color:#228b22"></span>                    .<span style="color:#658b00">ignoringAntMatchers</span>( <span style="color:#228b22">//
</span><span style="color:#228b22"></span>                    ).<span style="color:#658b00">csrfTokenRepository</span>(csrfTokenRepository());

            http.<span style="color:#658b00">sessionManagement</span>() <span style="color:#228b22">//
</span><span style="color:#228b22"></span>                    .<span style="color:#658b00">sessionCreationPolicy</span>(SessionCreationPolicy.<span style="color:#658b00">ALWAYS</span>);

            http.<span style="color:#658b00">rememberMe</span>();

            <span style="color:#228b22">// 檢查圖形驗證碼
</span><span style="color:#228b22"></span>            <span style="color:#8b008b;font-weight:bold">if</span> (LOGIN_CAPTCHA){
                http.<span style="color:#658b00">addFilterBefore</span>(<span style="color:#8b008b;font-weight:bold">new</span> VerificationCodeFilter(), UsernamePasswordAuthenticationFilter.<span style="color:#658b00">class</span>);
            }
</code></pre></div>- https://yoziming.github.io/post/230115-spring-security-login-captcha/ - Yoziming

柚子茶室 https://yoziming.github.io/post/221215-java-code-build-excel/ -<h1 id="知識點">知識點</h1>
<ul>
<li>用Java code 生成Excel檔案</li>
<li>簡單快入的更改字形、排版</li>
<li>Excel欄位有下拉選單(資料驗證)</li>
</ul>
<h1 id="應用情景">應用情景</h1>
<ul>
<li>有一個報修功能讓使用者可以上傳Excel的清單，系統可以讀取然後產生批量的報修單。於是有一個範例檔案</li>
<li>然而範例檔案還要達成傻瓜式操作，防止使用者填入錯誤的代碼，需要做成下拉清單，像這樣:</li>
</ul>
<p><img src="img_2022-12-08_14-21-46.png" alt="img_2022-12-08_14-21-46"></p>
<h1 id="引用包">引用包</h1>
<ul>
<li>Hutool、poi</li>
</ul>
<h1 id="code">Code</h1>
<ul>
<li>下拉選單的核心就在<code>writer.addSelect</code>方法，只要把<code>Enum</code>轉為<code>String[]</code>就可以了</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java">   <span style="color:#707a7c">@GetMapping</span>(<span style="color:#cd5555">&#34;/getExample&#34;</span>)
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">getExample</span>(HttpServletResponse response) <span style="color:#8b008b;font-weight:bold">throws</span> IOException {
        <span style="color:#228b22">// 造下拉選單的array
</span><span style="color:#228b22"></span>        Map&lt;String, String&gt; stateMap = <span style="color:#8b008b;font-weight:bold">new</span> HashMap&lt;&gt;();
        List&lt;String&gt; stateList = <span style="color:#8b008b;font-weight:bold">new</span> ArrayList&lt;&gt;();
        stateMap.<span style="color:#658b00">put</span>(LightCtrlDetailState.<span style="color:#658b00">PM_ACCEPT</span>.<span style="color:#658b00">getCode</span>(), LightCtrlDetailState.<span style="color:#658b00">PM_ACCEPT</span>.<span style="color:#658b00">getDesc</span>());
        stateMap.<span style="color:#658b00">put</span>(LightCtrlDetailState.<span style="color:#658b00">PM_DISCARD</span>.<span style="color:#658b00">getCode</span>(), LightCtrlDetailState.<span style="color:#658b00">PM_DISCARD</span>.<span style="color:#658b00">getDesc</span>());
        stateMap.<span style="color:#658b00">forEach</span>((k, v) -&gt; stateList.<span style="color:#658b00">add</span>(<span style="color:#cd5555">&#34;#&#34;</span> + k + <span style="color:#cd5555">&#34;(&#34;</span> + v + <span style="color:#cd5555">&#34;)&#34;</span>));
        String[] stateArray = stateList.<span style="color:#658b00">toArray</span>(<span style="color:#8b008b;font-weight:bold">new</span> String[0]);

        List&lt;String&gt; faultList = <span style="color:#8b008b;font-weight:bold">new</span> ArrayList&lt;&gt;();
        Map&lt;String, String&gt; faultMap = LightCtrlFault.<span style="color:#658b00">toMap</span>();
        faultMap.<span style="color:#658b00">forEach</span>((k, v) -&gt; faultList.<span style="color:#658b00">add</span>(<span style="color:#cd5555">&#34;#&#34;</span> + k + <span style="color:#cd5555">&#34;(&#34;</span> + v + <span style="color:#cd5555">&#34;)&#34;</span>));
        String[] faultArray = faultList.<span style="color:#658b00">toArray</span>(<span style="color:#8b008b;font-weight:bold">new</span> String[0]);

        List&lt;String&gt; deviceTypeList = <span style="color:#8b008b;font-weight:bold">new</span> ArrayList&lt;&gt;();
        Map&lt;String, String&gt; deviceTypeMap = LightCtrlDeviceType.<span style="color:#658b00">toMap</span>();
        deviceTypeMap.<span style="color:#658b00">remove</span>(LightCtrlDeviceType.<span style="color:#658b00">L1</span>.<span style="color:#658b00">getCode</span>()); <span style="color:#228b22">// 排除通用的
</span><span style="color:#228b22"></span>        deviceTypeMap.<span style="color:#658b00">forEach</span>((k, v) -&gt; deviceTypeList.<span style="color:#658b00">add</span>(<span style="color:#cd5555">&#34;#&#34;</span> + k + <span style="color:#cd5555">&#34;(&#34;</span> + v + <span style="color:#cd5555">&#34;)&#34;</span>));
        String[] deviceTypeArray = deviceTypeList.<span style="color:#658b00">toArray</span>(<span style="color:#8b008b;font-weight:bold">new</span> String[0]);

        ExcelWriter writer = ExcelUtil.<span style="color:#658b00">getWriter</span>(<span style="color:#8b008b;font-weight:bold">true</span>);
        Map&lt;String, Object&gt; row1 = <span style="color:#8b008b;font-weight:bold">new</span> LinkedHashMap&lt;&gt;();
        row1.<span style="color:#658b00">put</span>(<span style="color:#cd5555">&#34;*IMEI或MAC&#34;</span>, <span style="color:#cd5555">&#34;例如:356211691894888&#34;</span>);
        row1.<span style="color:#658b00">put</span>(<span style="color:#cd5555">&#34;*分類&#34;</span>, <span style="color:#cd5555">&#34;請選擇...&#34;</span>);
        row1.<span style="color:#658b00">put</span>(<span style="color:#cd5555">&#34;*故障原因&#34;</span>, <span style="color:#cd5555">&#34;請選擇...&#34;</span>);
        row1.<span style="color:#658b00">put</span>(<span style="color:#cd5555">&#34;*裝置類型代碼&#34;</span>, <span style="color:#cd5555">&#34;請選擇...&#34;</span>);
        row1.<span style="color:#658b00">put</span>(<span style="color:#cd5555">&#34;IMSI&#34;</span>, <span style="color:#cd5555">&#34;例如:466978000369264，最長15位&#34;</span>);
        row1.<span style="color:#658b00">put</span>(<span style="color:#cd5555">&#34;故障描述&#34;</span>, <span style="color:#cd5555">&#34;描述訊息，最多100字(此行為範例，上傳時請刪除)&#34;</span>);

        ArrayList&lt;Map&lt;String, Object&gt;&gt; rows = CollUtil.<span style="color:#658b00">newArrayList</span>(row1);
        <span style="color:#228b22">// 設定欄寬
</span><span style="color:#228b22"></span>        writer.<span style="color:#658b00">setColumnWidth</span>(0, 30);
        writer.<span style="color:#658b00">setColumnWidth</span>(1, 20);
        writer.<span style="color:#658b00">setColumnWidth</span>(2, 20);
        writer.<span style="color:#658b00">setColumnWidth</span>(3, 25);
        writer.<span style="color:#658b00">setColumnWidth</span>(4, 30);
        writer.<span style="color:#658b00">setColumnWidth</span>(5, 30);
        <span style="color:#228b22">// 設定字型
</span><span style="color:#228b22"></span>        StyleSet styleSet =
                writer.<span style="color:#658b00">getStyleSet</span>().<span style="color:#658b00">setFont</span>(HSSFColor.<span style="color:#658b00">HSSFColorPredefined</span>.<span style="color:#658b00">BLACK</span>.<span style="color:#658b00">getIndex</span>(), (<span style="color:#00688b;font-weight:bold">short</span>) 12, <span style="color:#cd5555">&#34;新細明體&#34;</span>, <span style="color:#8b008b;font-weight:bold">false</span>);
        CellStyle cellStyle = writer.<span style="color:#658b00">getCellStyle</span>();
        cellStyle.<span style="color:#658b00">setAlignment</span>(HorizontalAlignment.<span style="color:#658b00">LEFT</span>); <span style="color:#228b22">// 靠左
</span><span style="color:#228b22"></span>        cellStyle.<span style="color:#658b00">setDataFormat</span>(Short.<span style="color:#658b00">decode</span>(<span style="color:#cd5555">&#34;0x31&#34;</span>)); <span style="color:#228b22">// 文字
</span><span style="color:#228b22"></span>
        writer.<span style="color:#658b00">setStyleSet</span>(styleSet); <span style="color:#228b22">// 套用樣式
</span><span style="color:#228b22"></span>        writer.<span style="color:#658b00">addSelect</span>(1, 1, stateArray);
        writer.<span style="color:#658b00">addSelect</span>(2, 1, faultArray);
        writer.<span style="color:#658b00">addSelect</span>(3, 1, deviceTypeArray);
        writer.<span style="color:#658b00">write</span>(rows, <span style="color:#8b008b;font-weight:bold">true</span>); <span style="color:#228b22">// 一次性寫出內容，使用默認樣式，強制輸出標題
</span><span style="color:#228b22"></span>        response.<span style="color:#658b00">setContentType</span>(<span style="color:#cd5555">&#34;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet;charset=utf-8&#34;</span>);
        response.<span style="color:#658b00">setHeader</span>(<span style="color:#cd5555">&#34;Content-Disposition&#34;</span>, <span style="color:#cd5555">&#34;attachment;filename=test.xlsx&#34;</span>);
        ServletOutputStream out = response.<span style="color:#658b00">getOutputStream</span>();

        writer.<span style="color:#658b00">flush</span>(out, <span style="color:#8b008b;font-weight:bold">true</span>);
        writer.<span style="color:#658b00">close</span>();
        IoUtil.<span style="color:#658b00">close</span>(out);
    }
</code></pre></div><h2 id="前端下載">前端下載</h2>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js"><span style="color:#228b22">/** 獲取範例 */</span>
<span style="color:#8b008b;font-weight:bold">function</span> getExample() {
	fetch(ems.parseUrl(<span style="color:#cd5555">&#34;file&#34;</span>) + <span style="color:#cd5555">&#34;/getExample&#34;</span>)
	  .then(resp =&gt; resp.blob())
	  .then(blob =&gt; {
	    <span style="color:#8b008b;font-weight:bold">const</span> url = <span style="color:#658b00">window</span>.URL.createObjectURL(blob);
	    <span style="color:#8b008b;font-weight:bold">const</span> a = <span style="color:#658b00">document</span>.createElement(<span style="color:#cd5555">&#39;a&#39;</span>);
	    a.style.display = <span style="color:#cd5555">&#39;none&#39;</span>;
	    a.href = url;
	    <span style="color:#228b22">// the filename you want
</span><span style="color:#228b22"></span>	    a.download = <span style="color:#cd5555">&#39;(範例).xlsx&#39;</span>;
	    <span style="color:#658b00">document</span>.body.appendChild(a);
	    a.click();
	    <span style="color:#658b00">window</span>.URL.revokeObjectURL(url);
	    toastr.success(<span style="color:#cd5555">&#34;成功，請查看下載檔案&#34;</span>);
	  })
	  .<span style="color:#8b008b;font-weight:bold">catch</span>(() =&gt; toastr.error(<span style="color:#cd5555">&#34;發生錯誤&#34;</span>));
}
</code></pre></div>- https://yoziming.github.io/post/221215-java-code-build-excel/ - Yoziming

柚子茶室 https://yoziming.github.io/post/221115-datatables-frnotend-search/ -<h3 id="前端搜尋">前端搜尋</h3>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js"><span style="color:#228b22">/** 前端搜尋時間 */</span>
$.fn.dataTable.ext.search.push(
    <span style="color:#8b008b;font-weight:bold">function</span>(settings, data, dataIndex) {
        <span style="color:#8b008b;font-weight:bold">let</span> index = MAIN_TABLE.column(<span style="color:#cd5555">&#34;reportTime:name&#34;</span>).index();
        <span style="color:#8b008b;font-weight:bold">let</span> from = $(<span style="color:#cd5555">&#34;#sf-reportTime-min&#34;</span>).val();
        <span style="color:#8b008b;font-weight:bold">let</span> to = $(<span style="color:#cd5555">&#34;#sf-reportTime-max&#34;</span>).val()
        <span style="color:#8b008b;font-weight:bold">if</span> (from == <span style="color:#cd5555">&#34;&#34;</span> &amp;&amp; to == <span style="color:#cd5555">&#34;&#34;</span>) <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">true</span>;
        <span style="color:#8b008b;font-weight:bold">var</span> min = dayjs(from).unix();
        <span style="color:#8b008b;font-weight:bold">var</span> max = dayjs(to).unix();
        <span style="color:#8b008b;font-weight:bold">var</span> date = dayjs(data[index]).unix();
        <span style="color:#8b008b;font-weight:bold">if</span> (!(<span style="color:#658b00">Number</span>.<span style="color:#658b00">isNaN</span>(min) &amp;&amp; <span style="color:#658b00">Number</span>.<span style="color:#658b00">isNaN</span>(max)) &amp;&amp; min &lt;= date &amp;&amp; max &gt;= date) {
            <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">true</span>;
        }
        <span style="color:#8b008b;font-weight:bold">if</span> (min &lt;= date &amp;&amp; <span style="color:#658b00">Number</span>.<span style="color:#658b00">isNaN</span>(max)) <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">true</span>;
        <span style="color:#8b008b;font-weight:bold">if</span> (max &gt;= date &amp;&amp; <span style="color:#658b00">Number</span>.<span style="color:#658b00">isNaN</span>(min)) <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">true</span>;
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">false</span>;
    }
);
<span style="color:#228b22">/** 前端搜尋 */</span>
<span style="color:#8b008b;font-weight:bold">function</span> frontEndSearch() {
    <span style="color:#8b008b;font-weight:bold">let</span> imei = $(<span style="color:#cd5555">&#34;#sf-imei&#34;</span>).val();
    <span style="color:#8b008b;font-weight:bold">if</span> (imei) {
        <span style="color:#228b22">//console.log(&#34;imei=&#34;+imei)
</span><span style="color:#228b22"></span>        MAIN_TABLE.column(<span style="color:#cd5555">&#34;imei:name&#34;</span>).search(imei);
    }
    <span style="color:#8b008b;font-weight:bold">let</span> projectName = $(<span style="color:#cd5555">&#34;#sf-hostId&gt;option:selected&#34;</span>).text();
    <span style="color:#8b008b;font-weight:bold">if</span> (projectName &amp;&amp; $(<span style="color:#cd5555">&#34;#sf-hostId&#34;</span>).val()) {
        <span style="color:#228b22">//console.log(&#34;projectName=&#34;+projectName)
</span><span style="color:#228b22"></span>        MAIN_TABLE.column(<span style="color:#cd5555">&#34;projectCode:name&#34;</span>).search(projectName);
    }
    <span style="color:#8b008b;font-weight:bold">let</span> groupName = $(<span style="color:#cd5555">&#34;#sf-groupName&#34;</span>).val();
    <span style="color:#8b008b;font-weight:bold">if</span> (groupName) {
        <span style="color:#228b22">//console.log(&#34;groupName=&#34;+groupName)
</span><span style="color:#228b22"></span>        MAIN_TABLE.column(<span style="color:#cd5555">&#34;groupPath:name&#34;</span>).search(groupName);
    }
    MAIN_TABLE.draw()
}


</code></pre></div><h3 id="前端搜尋還原">前端搜尋還原</h3>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js"><span style="color:#228b22">/** 前端搜尋還原 */</span>
<span style="color:#8b008b;font-weight:bold">function</span> frontEndClear() {
    $(<span style="color:#cd5555">&#34;[id^=sf-]&#34;</span>).each(<span style="color:#8b008b;font-weight:bold">function</span>() {
        <span style="color:#8b008b;font-weight:bold">this</span>.value = <span style="color:#cd5555">&#39;&#39;</span>;
        <span style="color:#8b008b;font-weight:bold">this</span>.checked = <span style="color:#8b008b;font-weight:bold">false</span>;
    });
    MAIN_TABLE.search(<span style="color:#cd5555">&#39;&#39;</span>).columns().search(<span style="color:#cd5555">&#39;&#39;</span>).draw();
}
</code></pre></div><h3 id="使前端排序null與空白-last">使前端排序null與空白 last</h3>
<ul>
<li>預設前端排序的邏輯是用js排序的邏輯，null會在最前，可以透過<code>pre-format</code>的方式改掉</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js"><span style="color:#228b22">/** 使前端排序null與空白 last */</span>
$.extend( $.fn.dataTable.ext.type.order, { 
	<span style="color:#cd5555">&#39;date-pre&#39;</span> : <span style="color:#8b008b;font-weight:bold">function</span> ( d ) {
	    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#658b00">Date</span>.parse( d ) || <span style="color:#8b008b;font-weight:bold">Infinity</span>;
	},
	<span style="color:#cd5555">&#39;string-pre&#39;</span> : <span style="color:#8b008b;font-weight:bold">function</span> ( d ) {
	    <span style="color:#8b008b;font-weight:bold">return</span> (!d||d==<span style="color:#cd5555">&#34;&#34;</span>)?<span style="color:#cd5555">&#34;ZZZ&#34;</span>:d;
	},
	<span style="color:#cd5555">&#34;num&#34;</span> : <span style="color:#8b008b;font-weight:bold">function</span> ( d ) {
	    <span style="color:#8b008b;font-weight:bold">return</span> (!d||<span style="color:#658b00">isNaN</span>(d))?<span style="color:#8b008b;font-weight:bold">Infinity</span>:d;
	},

});
</code></pre></div><h3 id="操作rows-data">操作rows data</h3>
<ul>
<li>前端操作表格內資料透過API，最重要的就是這個<code>toArray()</code>方法</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js"><span style="color:#8b008b;font-weight:bold">let</span> list = MAIN_TABLE.rows().data().toArray();
</code></pre></div>- https://yoziming.github.io/post/221115-datatables-frnotend-search/ - Yoziming

柚子茶室 https://yoziming.github.io/post/221015-last-time-upload/ -<h1 id="情境">情境</h1>
<blockquote>
<p>一個有點奇葩的需求實現</p>
</blockquote>
<ul>
<li>使用者會上傳一個Excel檔案，要在瀏覽器記住這個上傳的檔案(類似一個即時分析的功能)</li>
<li>這個東西只會在前端現用而不存到DB</li>
<li>而且下次打開時要能自動還原上次的紀錄</li>
</ul>
<h1 id="作法">作法</h1>
<ul>
<li>
<p>需要把2進位檔先轉為dataURL (base64)，並且存到<code>localStorage</code>中。</p>
</li>
<li>
<p>在上傳成功時，調用此方法</p>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js"><span style="color:#8b008b;font-weight:bold">function</span> getBase64AndSave(file) {
    <span style="color:#8b008b;font-weight:bold">var</span> reader = <span style="color:#8b008b;font-weight:bold">new</span> FileReader();
    reader.readAsDataURL(file);
    reader.onload = <span style="color:#8b008b;font-weight:bold">function</span>() {
        localStorage.setItem(<span style="color:#cd5555">&#34;myUploadFileStr&#34;</span>, reader.result);
    };
    reader.onerror = <span style="color:#8b008b;font-weight:bold">function</span>(error) {
        console.log(<span style="color:#cd5555">&#39;Error: &#39;</span>, error);
    };
}
</code></pre></div><ul>
<li>還原檔案</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js"><span style="color:#8b008b;font-weight:bold">function</span> urltoFile(url, filename, mimeType) {
    <span style="color:#8b008b;font-weight:bold">return</span> (fetch(url)
        .then(<span style="color:#8b008b;font-weight:bold">function</span>(res) {
            <span style="color:#8b008b;font-weight:bold">return</span> res.arrayBuffer();
        })
        .then(<span style="color:#8b008b;font-weight:bold">function</span>(buf) {
            <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">new</span> File([buf], filename, {
                type: mimeType
            });
        })
    );
}
<span style="color:#228b22">/** 還原上次查詢的資料 */</span>
<span style="color:#8b008b;font-weight:bold">function</span> recoveryLastTimeData() {
    <span style="color:#8b008b;font-weight:bold">let</span> uploadFileStr = localStorage.getItem(<span style="color:#cd5555">&#34;myUploadFileStr&#34;</span>); <span style="color:#228b22">// 上次記住的data
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (uploadFileStr) {
        urltoFile(uploadFileStr, <span style="color:#cd5555">&#34;lastTime.xlsx&#34;</span>, <span style="color:#cd5555">&#34;application/vnd.openxmlformats-officedocument.spreadsheetml.sheet&#34;</span>)
            .then(<span style="color:#8b008b;font-weight:bold">function</span>(file) {
                 <span style="color:#228b22">// do something...
</span><span style="color:#228b22"></span>            });
    } <span style="color:#8b008b;font-weight:bold">else</span> {
        <span style="color:#228b22">// 如果是空的，顯示上傳窗口
</span><span style="color:#228b22"></span>    }
}
</code></pre></div><ul>
<li>清空</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js"><span style="color:#228b22">/** 清空上次查詢的資料 */</span>
<span style="color:#8b008b;font-weight:bold">function</span> clearLastTimeData() {
    localStorage.removeItem(<span style="color:#cd5555">&#34;myUploadFileStr&#34;</span>); <span style="color:#228b22">// 上次記住的data
</span><span style="color:#228b22">// do something...
</span><span style="color:#228b22"></span>}
</code></pre></div>- https://yoziming.github.io/post/221015-last-time-upload/ - Yoziming

柚子茶室 https://yoziming.github.io/post/220915-mjpeg-to-canvas/ -<h2 id="背景">背景</h2>
<ul>
<li>IPCAM的影像要能在web上播放，但又是用無線網路訊號非常不穩，就有很多問題</li>
</ul>
<h2 id="問題">問題</h2>
<ul>
<li>來自攝影機經過NVR的stream輸出是MJPEG格式，本來直接一個<code>&lt;img src=&quot;url&quot;</code>就可以播放</li>
<li>但是用無線網路不穩定會掉包，就會導致<code>net::ERR_INCOMPLETE_CHUNKED_ENCODING 200 (OK)</code></li>
<li>影像畫面會直接變一片白，需要重新request才可以</li>
<li>這種錯誤我試過onerror等方法都catch不到</li>
</ul>
<h2 id="解決">解決</h2>
<ul>
<li>最後找到一個好一點的方法，就是用canvas轉一層。這樣做畫面會維持在最後一張，發生問題就重新request</li>
<li>效果變成影像源頭掛掉時，畫面停住(本來是直接一片白)，重新連上後再繼續更新</li>
<li>看畫面上時間可能是到了10:02卡住不動，之後跳成10:08又繼續播放</li>
</ul>
<h2 id="code">CODE</h2>
<ul>
<li>url是影像來源，例如axxon的NVR系統是host&hellip;/DeviceIpint.158/SourceEndpoint.video:0:1</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js">
<span style="color:#8b008b;font-weight:bold">var</span> optstr = <span style="color:#cd5555">&#34;&lt;canvas id=&#39;movie_canvas&#39; width=&#39;640px&#39; height=&#39;360px&#39;&gt;&lt;/canvas&gt;&#34;</span>;
$(<span style="color:#cd5555">&#34;#movie&#34;</span>).html(optstr);
<span style="color:#8b008b;font-weight:bold">var</span> ctx = <span style="color:#658b00">document</span>.getElementById(<span style="color:#cd5555">&#39;movie_canvas&#39;</span>).getContext(<span style="color:#cd5555">&#39;2d&#39;</span>);
ctx.scale(<span style="color:#b452cd">0.33</span>, <span style="color:#b452cd">0.33</span>)
<span style="color:#8b008b;font-weight:bold">var</span> img = <span style="color:#8b008b;font-weight:bold">new</span> Image();
img.onload = <span style="color:#8b008b;font-weight:bold">function</span>() {
	ctx.drawImage(img, <span style="color:#b452cd">0</span>, <span style="color:#b452cd">0</span>);
};
<span style="color:#8b008b;font-weight:bold">var</span> imgRefresher = setInterval(<span style="color:#8b008b;font-weight:bold">function</span>() {
	img.src = url;
}, <span style="color:#b452cd">100</span>)
<span style="color:#8b008b;font-weight:bold">var</span> movieDg = $(<span style="color:#cd5555">&#34;#movie&#34;</span>).dialog({
	modal: <span style="color:#8b008b;font-weight:bold">true</span>,
	width: <span style="color:#b452cd">690</span>,
	height: <span style="color:#b452cd">430</span>,
	title: <span style="color:#cd5555">&#34;即時影像&#34;</span>,
	close: <span style="color:#8b008b;font-weight:bold">function</span>() {
		clearInterval(imgRefresher);
		$(<span style="color:#cd5555">&#34;#movie_canvas&#34;</span>).remove();
		<span style="color:#658b00">window</span>.stop();
	}
});
</code></pre></div>- https://yoziming.github.io/post/220915-mjpeg-to-canvas/ - Yoziming

柚子茶室 https://yoziming.github.io/post/220825-datatables/ -<h1 id="datatables小技巧">DataTables小技巧</h1>
<blockquote>
<p>DataTables是前端非常好用的表格套件</p>
</blockquote>
<p><a href="https://datatables.net/manual/">https://datatables.net/manual/</a></p>
<h2 id="自動序號">自動序號</h2>
<p><img src="image-20220902150627664.png" alt="image-20220902150627664"></p>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js">		{
            width: <span style="color:#cd5555">&#34;2%&#34;</span>,
            data: <span style="color:#8b008b;font-weight:bold">null</span>,
            defaultContent: <span style="color:#cd5555">&#39;&#39;</span>,
            orderable: <span style="color:#8b008b;font-weight:bold">false</span>,
            title: <span style="color:#cd5555">&#34;序號&#34;</span>,
            render: <span style="color:#8b008b;font-weight:bold">function</span>(data, type, full, meta) {
                <span style="color:#8b008b;font-weight:bold">return</span> meta.row + <span style="color:#b452cd">1</span> + meta.settings._iDisplayStart;
            }
        }
</code></pre></div><h2 id="i18n中文化">i18n中文化</h2>
<p>搭配官方的 : <a href="http://cdn.datatables.net/plug-ins/1.12.1/i18n/">http://cdn.datatables.net/plug-ins/1.12.1/i18n/</a></p>
<pre tabindex="0"><code>        language: {
            url: &quot;/scripts/DataTables-1.12.1/zh-HANT.json&quot;,
            infoFiltered: &quot;&quot;,
        },
</code></pre><h2 id="防止預設的排序">防止預設的排序</h2>
<p><img src="image-20220902150702931.png" alt="image-20220902150702931"></p>
<p><code>order : []</code></p>
<h2 id="格式化時間">格式化時間</h2>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js">		{
            data: <span style="color:#cd5555">&#34;time&#34;</span>,
            title: <span style="color:#cd5555">&#34;時間&#34;</span>,
            render: <span style="color:#8b008b;font-weight:bold">function</span>(data) {
                <span style="color:#8b008b;font-weight:bold">return</span> data ? dayjs(data).format(<span style="color:#cd5555">&#39;YYYY-MM-DD&#39;</span>) : <span style="color:#cd5555">&#34;&#34;</span>;
            },
        }
</code></pre></div><h3 id="綁定特殊動作">綁定特殊動作</h3>
<ul>
<li>比如說要設定某個onclick事件並傳入參數，如果參數很單純(例如純數字的id)那可以簡單的用render，例如:
<ul>
<li>這樣是把參數一起寫死到html的元素中了，按F12就可以直接看到</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js">render: <span style="color:#8b008b;font-weight:bold">function</span>(data) {
	<span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#39;&lt;i class=&#34;fa-solid fa-trash-can fa-2xl&#34; onclick=&#34;deleteById(&#39;</span> + data + <span style="color:#cd5555">&#39;)&#34;&gt;&lt;/i&gt;&#39;</span>;
},
</code></pre></div><ul>
<li>但如果要傳入的東西比較複雜(例如是一個多層的json object)，那用createdCell再用JQuery的.click之類的去做綁定</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js">		{
            width: <span style="color:#cd5555">&#34;3%&#34;</span>,
            data: <span style="color:#cd5555">&#34;id&#34;</span>,
            orderable: <span style="color:#8b008b;font-weight:bold">false</span>,
            title: <span style="color:#cd5555">&#34;刪除&#34;</span>,
            createdCell: <span style="color:#8b008b;font-weight:bold">function</span>(td, cellData, rowData, row, col) {
                <span style="color:#8b008b;font-weight:bold">let</span> icon;
                <span style="color:#8b008b;font-weight:bold">if</span> (rowData.departureTime) {
                    icon = <span style="color:#cd5555">&#39;&lt;i class=&#34;fa-solid fa-trash-can fa-2xl ban-icon&#34; title=&#34;已送出的維修單&#34;&gt;&lt;/i&gt;&#39;</span>;
                } <span style="color:#8b008b;font-weight:bold">else</span> {
                    icon = $(<span style="color:#cd5555">&#39;&lt;i class=&#34;fa-solid fa-trash-can fa-2xl&#34;&gt;&lt;/i&gt;&#39;</span>).click(<span style="color:#8b008b;font-weight:bold">function</span>() {
                        toggleDeleteDialog(rowData);
                    });
                }
                $(td).html(icon);
            }
        }
</code></pre></div><h2 id="跳轉到">跳轉到</h2>
<p><img src="image-20220902150444996.png" alt="image-20220902150444996"></p>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js">        drawCallback: <span style="color:#8b008b;font-weight:bold">function</span>(setting) {
            <span style="color:#8b008b;font-weight:bold">var</span> _this = $(<span style="color:#8b008b;font-weight:bold">this</span>);
            <span style="color:#8b008b;font-weight:bold">var</span> tableId = _this.attr(<span style="color:#cd5555">&#39;id&#39;</span>);
            <span style="color:#8b008b;font-weight:bold">var</span> pageDiv = $(<span style="color:#cd5555">&#39;#&#39;</span> + tableId + <span style="color:#cd5555">&#39;_paginate&#39;</span>);
            pageDiv.append(<span style="color:#cd5555">&#39;跳轉到&lt;input id=&#34;&#39;</span> + tableId +
                <span style="color:#cd5555">&#39;_gotoPage&#34; type=&#34;text&#34; style=&#34;height:28px;line-height:28px;width:40px;&#34;/&gt;&#39;</span> +
                <span style="color:#cd5555">&#39;&lt;a class=&#34;paginate_button&#34; aria-controls=&#34;&#39;</span> + tableId + <span style="color:#cd5555">&#39;&#34; tabindex=&#34;0&#34; id=&#34;&#39;</span> +
                tableId + <span style="color:#cd5555">&#39;_goto&#34;&gt;Go&lt;/a&gt;&#39;</span>)
