              <span style="color:#228b22">//var i=1 比較當前的tr和上一個tr的值
</span><span style="color:#228b22"></span>              <span style="color:#8b008b;font-weight:bold">for</span> (<span style="color:#8b008b;font-weight:bold">var</span> i = <span style="color:#b452cd">0</span>; i &lt; tr; i++) {
                  <span style="color:#8b008b;font-weight:bold">var</span> ford = $(<span style="color:#cd5555">&#34;#checkTable tr:gt(0):eq(&#34;</span> + i + <span style="color:#cd5555">&#34;) td:eq(&#34;</span> + <span style="color:#658b00">parseInt</span>(v) + <span style="color:#cd5555">&#34;)&#34;</span>).text();
                  <span style="color:#228b22">//根據下標獲取單元格的值
</span><span style="color:#228b22"></span>                  <span style="color:#228b22">// tr:gt(0) 從下標0 開始獲取
</span><span style="color:#228b22"></span>                  <span style="color:#228b22">// tr:gt(0):eq( i ) :i 標識 當前行的下標 ，0 開始
</span><span style="color:#228b22"></span>                  <span style="color:#228b22">// td:eq(0) 當前行的第一個單元格，下標從0開始
</span><span style="color:#228b22"></span>                  <span style="color:#8b008b;font-weight:bold">var</span> behind = $(<span style="color:#cd5555">&#34;#checkTable tr:gt(0):eq(&#34;</span> + (<span style="color:#658b00">parseInt</span>(i) + <span style="color:#b452cd">1</span>) + <span style="color:#cd5555">&#34;) td:eq(&#34;</span> + <span style="color:#658b00">parseInt</span>(v) + <span style="color:#cd5555">&#34;)&#34;</span>).text();

                  <span style="color:#8b008b;font-weight:bold">if</span> (ford != <span style="color:#cd5555">&#34;&#34;</span> &amp;&amp; ford == behind) {
                      $(<span style="color:#cd5555">&#34;#checkTable tr:gt(0):eq(&#34;</span> + (<span style="color:#658b00">parseInt</span>(i) + <span style="color:#b452cd">1</span>) + <span style="color:#cd5555">&#34;) td:eq(&#34;</span> + <span style="color:#658b00">parseInt</span>(v) + <span style="color:#cd5555">&#34;)&#34;</span>).attr(<span style="color:#cd5555">&#34;class&#34;</span>, <span style="color:#cd5555">&#34;remove&#34;</span>);
                      mark = mark + <span style="color:#b452cd">1</span>;
                  } <span style="color:#8b008b;font-weight:bold">else</span> <span style="color:#8b008b;font-weight:bold">if</span> (ford != behind) {
                      index = i - mark;
                      $(<span style="color:#cd5555">&#34;#checkTable tr:gt(0):eq(&#34;</span> + index + <span style="color:#cd5555">&#34;) td:eq(&#34;</span> + <span style="color:#658b00">parseInt</span>(v) + <span style="color:#cd5555">&#34;)&#34;</span>).attr(<span style="color:#cd5555">&#34;rowspan&#34;</span>, mark + <span style="color:#b452cd">1</span>);<span style="color:#228b22">//將當前的行加入屬性rowspan，合併 mark+1行
</span><span style="color:#228b22"></span>                      $(<span style="color:#cd5555">&#34;#checkTable tr:gt(0):eq(&#34;</span> + index + <span style="color:#cd5555">&#34;) td:eq(&#34;</span> + <span style="color:#658b00">parseInt</span>(v) + <span style="color:#cd5555">&#34;)&#34;</span>).attr(<span style="color:#cd5555">&#34;class&#34;</span>, <span style="color:#cd5555">&#34;marge&#34;</span>);
                      <span style="color:#228b22">//rowspan 列上橫跨， colspan 行上橫跨
</span><span style="color:#228b22"></span>                      <span style="color:#228b22">//後面的參數，表示橫跨的單元格個數，
</span><span style="color:#228b22"></span>                      <span style="color:#228b22">//合併單元格就是將其他的單元格隱藏（hide）,或刪除（remove）。
</span><span style="color:#228b22"></span>                      <span style="color:#228b22">//將一個單元格的rowspan 或colsspan 加大
</span><span style="color:#228b22"></span>
                      mark = <span style="color:#b452cd">0</span>;
                  }
              }
          }
      }
