            jqXHR.abort(); <span style="color:#228b22">// 放棄晚觸發的重複提交
</span><span style="color:#228b22"></span>            <span style="color:#228b22">//pendingRequests[key].abort(); // 放棄先觸發的提交
</span><span style="color:#228b22"></span>        }

        <span style="color:#8b008b;font-weight:bold">var</span> complete = options.complete;
        options.complete = <span style="color:#8b008b;font-weight:bold">function</span>(jqXHR, textStatus) {
            pendingRequests[key] = <span style="color:#8b008b;font-weight:bold">null</span>;
            <span style="color:#8b008b;font-weight:bold">if</span> ($.isFunction(complete)) {
                complete.apply(<span style="color:#8b008b;font-weight:bold">this</span>, arguments);
            }
        };
    });
