</span><span style="color:#228b22"></span>            formatter: <span style="color:#cd5555">&#34;{b}: {c}輛&lt;br/&gt;({d}%)&#34;</span> <span style="color:#228b22">// 提示的格式
</span><span style="color:#228b22"></span>        },
        legend: { <span style="color:#228b22">// 圖例
</span><span style="color:#228b22"></span>            bottom: <span style="color:#b452cd">10</span>,
            left: <span style="color:#cd5555">&#39;center&#39;</span>,
        },
        backgroundColor: <span style="color:#cd5555">&#39;#fbfbfb&#39;</span>,
        series: [{
            name: <span style="color:#cd5555">&#34;車種佔比&#34;</span>,
            type: <span style="color:#cd5555">&#34;pie&#34;</span>, <span style="color:#228b22">// 圖標的類型
</span><span style="color:#228b22"></span>            radius: <span style="color:#cd5555">&#34;60%&#34;</span>, <span style="color:#228b22">// 餅圖的範圍
</span><span style="color:#228b22"></span>            avoidLabelOverlap: <span style="color:#8b008b;font-weight:bold">false</span>,
            label: {
                normal: {
                    formatter: <span style="color:#cd5555">&#39;{b}\n{d}%&#39;</span>,
                    textStyle: {
                        fontWeight: <span style="color:#cd5555">&#39;normal&#39;</span>,
                        fontSize: <span style="color:#b452cd">15</span>
                    }
