</code></pre><h2 id="fizzbuzz">FizzBuzz</h2>
<pre tabindex="0"><code>/**
 * FizzBuzz
 * 給一個整數 n 請列印出 1~n 的每一個整數， 但是
 * 當整數可以被 3 整除的時候印出 Fizz 來代替原本要印出的數，
 * 當整數可以被 5 整除的時候印出 Buzz 來代替原本要印出的數，
 * 當整數可以被 3 跟 5 整除的時候印出 FizzBuzz 來代替原本原本要印出的數。
 */
private static void printFizzBuzz(int n) {
    for (int i = 1; i &lt;= n; i++) {
        if (i % 3 == 0 &amp;&amp; i % 5 == 0) {
            System.out.println(&quot;FizzBuzz&quot;);
        }
        if (i % 3 == 0) {
            System.out.println(&quot;Fizz&quot;);
        }
        if (i % 5 == 0) {
            System.out.println(&quot;Buzz&quot;);
        }
        System.out.println(i);
    }
}
</code></pre><h2 id="首字大寫">首字大寫</h2>
<pre tabindex="0"><code>/**
 * 把一串小寫英文，每個英文單字第一個字母大寫
 */
private static String toUpperCase(String str) {
    String res = &quot;&quot;;
    // 第一個總要變大
    res += Character.toString(str.charAt(0)).toUpperCase();
    // 遍歷
    for (int i = 1; i &lt; str.length(); i++) {
        // 遇到空格下個字就變大
        if (Character.toString(str.charAt(i - 1)).equals(&quot; &quot;)) {
            res += Character.toString(str.charAt(i)).toUpperCase();
        } else {
            // 沒事的維持小寫
            res += Character.toString(str.charAt(i));
        }
    }
    return res;
}
</code></pre><h2 id="費氏數列">費氏數列</h2>
<pre tabindex="0"><code>/**
 * 費波納數列
 */
private static int fibona(int n) {
    if (n &lt;= 1) {
        return n;
    }
    return fibona(n - 1) + fibona(n - 2);
}
</code></pre>- https://yoziming.github.io/post/220217-java-interview-02/ - Yoziming

柚子茶室 https://yoziming.github.io/post/220208-leetcode-easy-66/ -<h3 id="66-plus-one">\66. Plus One</h3>
<ul>
<li>沒頭緒時，可以先列出多種結果，拆解歸納相似之處</li>
<li>像這題+1其實就只有兩種情況，9或其他</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">Solution</span> {
    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * Input: digits = [4,3,2,1]
</span><span style="color:#228b22">     * Output: [4,3,2,2]
</span><span style="color:#228b22">     * Explanation: The array represents the integer 4321.
</span><span style="color:#228b22">     * Incrementing by one gives 4321 + 1 = 4322.
</span><span style="color:#228b22">     * Thus, the result should be [4,3,2,2].
</span><span style="color:#228b22">     */</span>
    <span style="color:#228b22">// 從最後一位數開始遍歷(向前)，不為9時直接加一，為9時讓當前元素重置為0(進位了)
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">int</span>[] <span style="color:#008b45">plusOne</span>(<span style="color:#00688b;font-weight:bold">int</span>[] digits) {
        <span style="color:#8b008b;font-weight:bold">for</span> (<span style="color:#00688b;font-weight:bold">int</span> i = digits.<span style="color:#658b00">length</span> - 1; i &gt;= 0; i--) {
            <span style="color:#228b22">// 如果等於 9 ，重置為0
</span><span style="color:#228b22"></span>            <span style="color:#8b008b;font-weight:bold">if</span> (digits[i] == 9){
                digits[i] = 0;
            } <span style="color:#8b008b;font-weight:bold">else</span> {
                <span style="color:#228b22">// 不為9，直接加一返回
</span><span style="color:#228b22"></span>                digits[i] ++;
                <span style="color:#8b008b;font-weight:bold">return</span> digits;
            }
        }
        <span style="color:#228b22">// 循環出來如果沒返回(原數字剛好是999之類的情況)，
</span><span style="color:#228b22"></span>        <span style="color:#228b22">// 所有的位都已經重置為0了 ，只需要數組擴容，在第一位數加一即可
</span><span style="color:#228b22"></span>        digits = <span style="color:#8b008b;font-weight:bold">new</span> <span style="color:#00688b;font-weight:bold">int</span>[digits.<span style="color:#658b00">length</span> + 1];
        digits[0] = 1;
        <span style="color:#8b008b;font-weight:bold">return</span> digits;
    }
}
</code></pre></div><h3 id="67-add-binary">\67. Add Binary</h3>
<ul>
<li>StringBuilder的reverse()方法結合逆序遍歷，是處理字符串問題的利器</li>
<li>「加法」系列題目優先考慮 「列豎式」模擬法</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">Solution</span> {
    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * Input: a = &#34;1010&#34;, b = &#34;1011&#34;
</span><span style="color:#228b22">     * Output: &#34;10101&#34;
</span><span style="color:#228b22">     */</span>
    <span style="color:#8b008b;font-weight:bold">public</span> String <span style="color:#008b45">addBinary</span>(String a, String b) {
        StringBuilder res = <span style="color:#8b008b;font-weight:bold">new</span> StringBuilder(); <span style="color:#228b22">// 預計返回的結果
</span><span style="color:#228b22"></span>        <span style="color:#00688b;font-weight:bold">int</span> i = a.<span style="color:#658b00">length</span>() - 1; <span style="color:#228b22">// 標記遍歷到 a 的位置，準備從最後一位向前遍歷
</span><span style="color:#228b22"></span>        <span style="color:#00688b;font-weight:bold">int</span> j = b.<span style="color:#658b00">length</span>() - 1; <span style="color:#228b22">// 標記遍歷到 b 的位置
</span><span style="color:#228b22"></span>        <span style="color:#00688b;font-weight:bold">int</span> carry = 0; <span style="color:#228b22">// 進位
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">while</span> (i &gt;= 0 || j &gt;= 0 || carry != 0) { <span style="color:#228b22">// a 沒遍歷完，或 b 沒遍歷完，或進位不為 0
</span><span style="color:#228b22"></span>            <span style="color:#00688b;font-weight:bold">int</span> digitA = (i &gt;= 0 ? a.<span style="color:#658b00">charAt</span>(i) - <span style="color:#cd5555">&#39;0&#39;</span> : 0); <span style="color:#228b22">// 當前 a 的取值(如果是&#39;1&#39; - &#39;0&#39; 剛好就是1)
</span><span style="color:#228b22"></span>            <span style="color:#00688b;font-weight:bold">int</span> digitB = (j &gt;= 0 ? b.<span style="color:#658b00">charAt</span>(j) - <span style="color:#cd5555">&#39;0&#39;</span> : 0); <span style="color:#228b22">// 當前 b 的取值
</span><span style="color:#228b22"></span>            <span style="color:#00688b;font-weight:bold">int</span> sum = digitA + digitB + carry; <span style="color:#228b22">// 當前位置相加的結果
</span><span style="color:#228b22"></span>            carry = (sum &gt;= 2 ? 1 : 0); <span style="color:#228b22">// 是否有進位(相加=2就是要進位)
</span><span style="color:#228b22"></span>            sum = (sum &gt;= 2 ? sum - 2 : sum); <span style="color:#228b22">// 去除進位后留下的数字
</span><span style="color:#228b22"></span>            res.<span style="color:#658b00">append</span>(sum); <span style="color:#228b22">// 把去除進位后留下的数字拼接到結果中
</span><span style="color:#228b22"></span>            <span style="color:#228b22">// 若最後一次有進位也是while的第三個條件，不會遺漏
</span><span style="color:#228b22"></span>            i--;  <span style="color:#228b22">// 遍歷到 a 的位置向左移動
</span><span style="color:#228b22"></span>            j--;  <span style="color:#228b22">// 遍歷到 b 的位置向左移動
</span><span style="color:#228b22"></span>        }
        <span style="color:#8b008b;font-weight:bold">return</span> res.<span style="color:#658b00">reverse</span>().<span style="color:#658b00">toString</span>(); <span style="color:#228b22">// 把結果反轉並返回
</span><span style="color:#228b22"></span>    }
}

</code></pre></div><h3 id="69-sqrtx">\69. Sqrt(x)</h3>
<blockquote>
<p>開方</p>
</blockquote>
<ul>
<li>二分法重點在於區間的選擇</li>
<li>每次疊代必須確保能縮小範圍</li>
<li>考慮極端值是否會死循環</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * Input: x = 8
</span><span style="color:#228b22"> * Output: 2
</span><span style="color:#228b22"> * Explanation: The square root of 8 is 2.82842...,
</span><span style="color:#228b22"> * and since the decimal part is truncated, 2 is returned.
</span><span style="color:#228b22"> */</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">Solution</span> {
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">int</span> <span style="color:#008b45">mySqrt</span>(<span style="color:#00688b;font-weight:bold">int</span> x) {
        <span style="color:#228b22">// 特殊值判斷
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">if</span> (x == 0) {
            <span style="color:#8b008b;font-weight:bold">return</span> 0;
        }
        <span style="color:#8b008b;font-weight:bold">if</span> (x == 1) {
            <span style="color:#8b008b;font-weight:bold">return</span> 1;
        }

        <span style="color:#00688b;font-weight:bold">int</span> left = 1;
        <span style="color:#00688b;font-weight:bold">int</span> right = x / 2;
        <span style="color:#228b22">// 在區間 [left..right] 查找目標元素
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">while</span> (left &lt; right) {
            <span style="color:#228b22">// mid需要進位，否則最後區間剩2數時會卡死
</span><span style="color:#228b22"></span>            <span style="color:#00688b;font-weight:bold">int</span> mid = left + (right - left + 1) / 2;

            <span style="color:#8b008b;font-weight:bold">if</span> (mid &gt; x / mid) {
                <span style="color:#228b22">// 下一輪搜索區間是 [left..mid - 1]
</span><span style="color:#228b22"></span>                right = mid - 1;
            } <span style="color:#8b008b;font-weight:bold">else</span> {
                <span style="color:#228b22">// 下一輪搜索區間是 [mid..right]
</span><span style="color:#228b22"></span>                left = mid;
            }
        }
        <span style="color:#8b008b;font-weight:bold">return</span> left;
    }
}

</code></pre></div>- https://yoziming.github.io/post/220208-leetcode-easy-66/ - Yoziming

柚子茶室 https://yoziming.github.io/post/220205-leetcode-easy-35/ -<h3 id="35-search-insert-position">\35. Search Insert Position</h3>
<ul>
<li>二分查找
<ul>
<li>核心思路是&quot;下一輪的搜索區間&quot;</li>
<li>然後逐步縮小區間</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">int</span> <span style="color:#008b45">searchInsert</span>(<span style="color:#00688b;font-weight:bold">int</span>[] nums, <span style="color:#00688b;font-weight:bold">int</span> target) {
    <span style="color:#228b22">// 右邊界最大的數有可能就是答案(最衰的情況下)，他的index就是長度
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">int</span> len = nums.<span style="color:#658b00">length</span>, left = 0, right = len;
    <span style="color:#228b22">// 開始迫近
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">while</span> (left &lt; right) {
        <span style="color:#228b22">// 每輪都重新定義中間數，注意小數點會被捨去
</span><span style="color:#228b22"></span>        <span style="color:#00688b;font-weight:bold">int</span> mid = left + (right - left) / 2;
        <span style="color:#228b22">// 如果目標更大
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">if</span> (nums[mid] &lt; target) {
            <span style="color:#228b22">// 成為新的左標，下一輪搜尋[mid + 1...right]
</span><span style="color:#228b22"></span>            left = mid + 1; <span style="color:#228b22">// 因為小數點會被捨去，所以這邊+1
</span><span style="color:#228b22"></span>        } <span style="color:#8b008b;font-weight:bold">else</span> {
            <span style="color:#228b22">// 成為新的右標，下一輪搜尋[left...mid]
</span><span style="color:#228b22"></span>            right = mid;
        }
        <span style="color:#228b22">// 直到nums[mid] = target
</span><span style="color:#228b22"></span>    }
    <span style="color:#8b008b;font-weight:bold">return</span> left;
}
</code></pre></div><h3 id="53-maximum-subarray">\53. Maximum Subarray</h3>
<ul>
<li>動態規劃 Dynamic programming，核心思想是&quot;大事化小，小事化了&quot;</li>
<li>拆分出局部的問題，從小的部分算出解並且儲存起來(記憶化)</li>
<li>一個儲存的結果就是一個狀態，而狀態可能是很多種所以稱為動態，要做的事就是找出最佳解(規劃)，所以叫做動態規劃</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">int</span> <span style="color:#008b45">maxSubArray</span>(<span style="color:#00688b;font-weight:bold">int</span>[] nums) {
    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * Input: nums = [-2,1,-3,4,-1,2,1,-5,4]
</span><span style="color:#228b22">     * Output: 6
</span><span style="color:#228b22">     * Explanation: [4,-1,2,1] has the largest sum = 6.
</span><span style="color:#228b22">     * 找出子數組(連續的)最大和
</span><span style="color:#228b22">     */</span>
    <span style="color:#00688b;font-weight:bold">int</span> n = nums.<span style="color:#658b00">length</span>;
    <span style="color:#228b22">// 動態用來儲存最大值的數組，長度等於原數組，因為到時候要一個一個比過去
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">int</span>[] dp = <span style="color:#8b008b;font-weight:bold">new</span> <span style="color:#00688b;font-weight:bold">int</span>[n];
    dp[0] = nums[0];
    <span style="color:#228b22">// 先假設第一個數自己就是最大值
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">int</span> max = nums[0];
    <span style="color:#228b22">// 從第二個數開始比對
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">for</span> (<span style="color:#00688b;font-weight:bold">int</span> i = 1; i &lt; n; i++) {
        <span style="color:#228b22">// 判斷&#34;動態數組的前一個數&#34;加&#34;原數組當前數&#34;，哪個更大，原數組更大就成為動態數組的新成員
</span><span style="color:#228b22"></span>        dp[i] = Math.<span style="color:#658b00">max</span>(dp[i - 1] + nums[i], nums[i]);
        <span style="color:#228b22">// 動態數組每輪更新的結果是累加的和，直到下一個數是負的才停
</span><span style="color:#228b22"></span>        <span style="color:#228b22">// 更新最終要返回的max
</span><span style="color:#228b22"></span>        max = Math.<span style="color:#658b00">max</span>(max, dp[i]);
    }
    <span style="color:#8b008b;font-weight:bold">return</span> max;
}
</code></pre></div><h3 id="58-length-of-last-word">\58. Length of Last Word</h3>
<ul>
<li>沒甚麼特別的，就是遍歷字串</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">int</span> <span style="color:#008b45">lengthOfLastWord</span>(String s) {
    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * Input: s = &#34;Hello World&#34;
</span><span style="color:#228b22">     * Output: 5
</span><span style="color:#228b22">     * Explanation: The last word is &#34;World&#34; with length 5.
</span><span style="color:#228b22">     * 輸入sting可能包含空格，找出最後一個單字的長度
</span><span style="color:#228b22">     */</span>
    <span style="color:#228b22">// 從尾遍歷
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">int</span> len = s.<span style="color:#658b00">length</span>();
    <span style="color:#00688b;font-weight:bold">int</span> end = len - 1;
    <span style="color:#228b22">// 如果找到空格就停
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">for</span> (; end &gt;= 0 &amp;&amp; s.<span style="color:#658b00">charAt</span>(end) == <span style="color:#cd5555">&#39; &#39;</span>; end--) {
    }
    <span style="color:#228b22">// 單字的長度，直到空格又停
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">int</span> wordLength = 0;
    <span style="color:#8b008b;font-weight:bold">for</span> (; end &gt;= 0 &amp;&amp; s.<span style="color:#658b00">charAt</span>(end) != <span style="color:#cd5555">&#39; &#39;</span>; end--) {
        wordLength++;
    }
    <span style="color:#8b008b;font-weight:bold">return</span> wordLength;

}
</code></pre></div>- https://yoziming.github.io/post/220205-leetcode-easy-35/ - Yoziming

柚子茶室 https://yoziming.github.io/post/220203-gulimall-17-offline-cart/ -<h1 id="購物車需求分析">購物車需求分析</h1>
<h2 id="訪客購物車">訪客購物車</h2>
<blockquote>
<p>沒登入也能放地購物車，是我才不搞那麼多，沒登入就讓用戶登一下不就好了，唉當練習吧</p>
<p>意外的是這個項目是仿京東，結果京東現在也不提供這種功能了，一律先登入再說</p>
</blockquote>
<ul>
<li>
<p>可以把資料暫存在客戶端，例如:</p>
<ul>
<li>localstorage</li>
<li>cookie</li>
<li>WebSQL</li>
</ul>
</li>
<li>
<p>但何種商品被放到購物車本身是一個有價值的資訊，所以選擇放到伺服端的redis</p>
</li>
</ul>
<h2 id="用户購物車">用户購物車</h2>
<ul>
<li>一樣採用redis，優勢在於
<ul>
<li>極高的讀寫併發性能</li>
<li>好組織數據結構</li>
<li>redis也有持久化策略，AOF</li>
</ul>
</li>
<li>登入後會將離線購物車合併</li>
</ul>
<h2 id="操作分析">操作分析</h2>
<ul>
<li>增（添加商品到購物車）</li>
<li>刪（刪除某個商品）</li>
<li>改（修改商品數量）</li>
<li>查（查詢購物車中的商品）
<ul>
<li>商品是否被選中，下次進來還是選中狀態</li>
<li>用户可以使用購物車多件商品一起結算下單</li>
<li>在購物車中展示商品優惠信息</li>
<li>提示購物車商品價格變化</li>
</ul>
</li>
</ul>
<h2 id="資料庫設計">資料庫設計</h2>
<ul>
<li>Redis數據結構用Hash，造一個雙層Map來存</li>
</ul>
<pre tabindex="0"><code>Map&lt;String, Map&lt;String, String&gt;&gt; 
</code></pre><ul>
<li>第一個key是用户id，value是購物車信息</li>
<li>第二個key是skuId，value是購物項數據</li>
</ul>
<h2 id="vo設計">Vo設計</h2>
<blockquote>
<p>類似之前做的書城項目</p>
</blockquote>
<ul>
<li>CartVo是完整的一台車，這邊有CartItemVo構成的List、總件數、總價</li>
<li>CartItemVo略等同於Sku，就是車中的某項商品，加上件數與價格</li>
</ul>
<p><img src="image-20220126011315913.png" alt="image-20220126011315913"></p>
<ul>
<li>在CartVo.java 將計算總價等等方法封裝起來</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> BigDecimal <span style="color:#008b45">getTotalAmount</span>() {
    BigDecimal amount = <span style="color:#8b008b;font-weight:bold">new</span> BigDecimal(<span style="color:#cd5555">&#34;0&#34;</span>);
    <span style="color:#228b22">// 計算購物項總價
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (!CollectionUtils.<span style="color:#658b00">isEmpty</span>(items)) {
        <span style="color:#8b008b;font-weight:bold">for</span> (CartItemVo cartItem : items) {
            <span style="color:#8b008b;font-weight:bold">if</span> (cartItem.<span style="color:#658b00">getCheck</span>()) {
                amount = amount.<span style="color:#658b00">add</span>(cartItem.<span style="color:#658b00">getTotalPrice</span>());
            }
        }
    }
    <span style="color:#228b22">// 計算優惠的價格
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">return</span> amount.<span style="color:#658b00">subtract</span>(getReduce());
}
</code></pre></div><h1 id="實作">實作</h1>
<h2 id="攔截器">攔截器</h2>
<ul>
<li>
<p>當用戶想用購物車，必須判斷是否已登入，若無登入，創造一個臨時用戶cookie:user-key</p>
</li>
<li>
<p>造一個WebMvcConfigurer配置類註冊攔截器，MallWebConfig.java</p>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Configuration</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">MallWebConfig</span> <span style="color:#8b008b;font-weight:bold">implements</span> WebMvcConfigurer {
    <span style="color:#707a7c">@Override</span>
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">addInterceptors</span>(InterceptorRegistry registry) {
        registry.<span style="color:#658b00">addInterceptor</span>(<span style="color:#8b008b;font-weight:bold">new</span> CartInterceptor())<span style="color:#228b22">// 註冊攔截器
</span><span style="color:#228b22"></span>                .<span style="color:#658b00">addPathPatterns</span>(<span style="color:#cd5555">&#34;/**&#34;</span>);
    }
}
</code></pre></div><ul>
<li>用ThreadLocal來儲存用戶的登入狀態UserInfoTo</li>
</ul>
<p><img src="image-20220126143902191.png" alt="image-20220126143902191"></p>
<ul>
<li>ThreadLocal在同一個線程內都能存取，之前學過</li>
</ul>
<blockquote>
<p><a href="https://yoziming.github.io/post/220110-agg-javaweb-10/#threadlocal">https://yoziming.github.io/post/220110-agg-javaweb-10/#threadlocal</a></p>
</blockquote>
<ul>
<li>CartInterceptor.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 在執行目標方法之前，判斷用戶的登入狀態.並封裝傳遞給controller目標請求
</span><span style="color:#228b22"> */</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">CartInterceptor</span> <span style="color:#8b008b;font-weight:bold">implements</span> HandlerInterceptor {
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> ThreadLocal&lt;UserInfoTo&gt; toThreadLocal = <span style="color:#8b008b;font-weight:bold">new</span> ThreadLocal&lt;&gt;();

    <span style="color:#228b22">/***
</span><span style="color:#228b22">     * 攔截所有請求給ThreadLocal封裝UserInfoTo物件
</span><span style="color:#228b22">     * 1、從session中獲取MemberResponseVo != null，登入狀態，為UserInfoTo設置Id
</span><span style="color:#228b22">     * 2、從request中獲取cookie，找到user-key的value，
</span><span style="color:#228b22">     * 目標方法執行之前：在ThreadLocal中存入用戶信息【同一個線程共享數據】
</span><span style="color:#228b22">     * 從session中獲取數據【使用session需要cookie中的GULISESSION 值】
</span><span style="color:#228b22">     */</span>
    <span style="color:#707a7c">@Override</span>
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">boolean</span> <span style="color:#008b45">preHandle</span>(HttpServletRequest request, HttpServletResponse response, Object handler) <span style="color:#8b008b;font-weight:bold">throws</span> Exception {
        UserInfoTo userInfoTo = <span style="color:#8b008b;font-weight:bold">new</span> UserInfoTo();
        HttpSession session = request.<span style="color:#658b00">getSession</span>();
        <span style="color:#228b22">// 獲得當前登入用戶的信息
</span><span style="color:#228b22"></span>        MemberResponseVo memberResponseVo = (MemberResponseVo) session.<span style="color:#658b00">getAttribute</span>(AuthServerConstant.<span style="color:#658b00">LOGIN_USER</span>);
        <span style="color:#8b008b;font-weight:bold">if</span> (memberResponseVo != <span style="color:#8b008b;font-weight:bold">null</span>) {
            <span style="color:#228b22">// 用戶登入了
</span><span style="color:#228b22"></span>            userInfoTo.<span style="color:#658b00">setUserId</span>(memberResponseVo.<span style="color:#658b00">getId</span>());
        }
        Cookie[] cookies = request.<span style="color:#658b00">getCookies</span>();
        <span style="color:#8b008b;font-weight:bold">if</span> (cookies != <span style="color:#8b008b;font-weight:bold">null</span> &amp;&amp; cookies.<span style="color:#658b00">length</span> &gt; 0) {
            <span style="color:#8b008b;font-weight:bold">for</span> (Cookie cookie : cookies) {
                <span style="color:#228b22">// user-key
</span><span style="color:#228b22"></span>                String name = cookie.<span style="color:#658b00">getName</span>();
                <span style="color:#8b008b;font-weight:bold">if</span> (name.<span style="color:#658b00">equals</span>(CartConstant.<span style="color:#658b00">TEMP_USER_COOKIE_NAME</span>)) {
                    userInfoTo.<span style="color:#658b00">setUserKey</span>(cookie.<span style="color:#658b00">getValue</span>());
                    <span style="color:#228b22">// 標識客戶端已經存儲了 user-key
</span><span style="color:#228b22"></span>                    userInfoTo.<span style="color:#658b00">setTempUser</span>(<span style="color:#8b008b;font-weight:bold">true</span>);
                }
            }
        }
        <span style="color:#228b22">// 如果沒有臨時用戶一定分配一個臨時用戶UUID
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isEmpty</span>(userInfoTo.<span style="color:#658b00">getUserKey</span>())) {
            String uuid = UUID.<span style="color:#658b00">randomUUID</span>().<span style="color:#658b00">toString</span>();
            userInfoTo.<span style="color:#658b00">setUserKey</span>(uuid);
        }
        <span style="color:#228b22">// 目標方法執行之前
</span><span style="color:#228b22"></span>        toThreadLocal.<span style="color:#658b00">set</span>(userInfoTo);
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">true</span>;
    }

    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 業務執行之後，讓瀏覽器保存臨時用戶user-key的Cookie
</span><span style="color:#228b22">     */</span>
    <span style="color:#707a7c">@Override</span>
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">postHandle</span>(HttpServletRequest request, HttpServletResponse response, Object handler,
                           ModelAndView modelAndView) <span style="color:#8b008b;font-weight:bold">throws</span> Exception {
        <span style="color:#228b22">// 獲取當前用戶的值
</span><span style="color:#228b22"></span>        UserInfoTo userInfoTo = toThreadLocal.<span style="color:#658b00">get</span>();
        <span style="color:#228b22">// 1、判斷是否登入；2、判斷是否創建user-token的cookie
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">if</span> (userInfoTo != <span style="color:#8b008b;font-weight:bold">null</span> &amp;&amp; !userInfoTo.<span style="color:#658b00">isTempUser</span>()) {
            <span style="color:#228b22">// 創建一個cookie
</span><span style="color:#228b22"></span>            Cookie cookie = <span style="color:#8b008b;font-weight:bold">new</span> Cookie(CartConstant.<span style="color:#658b00">TEMP_USER_COOKIE_NAME</span>, userInfoTo.<span style="color:#658b00">getUserKey</span>());
            cookie.<span style="color:#658b00">setDomain</span>(<span style="color:#cd5555">&#34;mall.com&#34;</span>);
            cookie.<span style="color:#658b00">setMaxAge</span>(CartConstant.<span style="color:#658b00">TEMP_USER_COOKIE_TIMEOUT</span>);
            response.<span style="color:#658b00">addCookie</span>(cookie);
        }
    }
}
</code></pre></div><h3 id="攔截器與過濾器">攔截器與過濾器</h3>
<blockquote>
<p>參考 <a href="https://iter01.com/527287.html">https://iter01.com/527287.html</a></p>
</blockquote>
<ul>
<li>執行順序: 過濾前-攔截前-action執行-攔截後-過濾後</li>
</ul>
<p><img src="image-20220126144548868.png" alt="image-20220126144548868"></p>
<ul>
<li>總的來說攔截器更好用一點</li>
</ul>
<h2 id="查看整車">查看整車</h2>
<ul>
<li>CartController.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 去購物車頁面的請求【未登入狀態也可以查看】
</span><span style="color:#228b22"> * 瀏覽器有一個cookie:user-key 標識用戶的身份，一個月過期
</span><span style="color:#228b22"> * 如果第一次使用jd的購物車功能，都會給一個臨時的用戶身份:
</span><span style="color:#228b22"> * 瀏覽器以後保存，每次訪問都會帶上這個cookie；
</span><span style="color:#228b22"> * 登入：session有用戶的身份
</span><span style="color:#228b22"> * 沒登入：按照cookie裏面帶來user-key來做
</span><span style="color:#228b22"> * 第一次，如果沒有臨時用戶，自動創建一個臨時用戶
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@GetMapping</span>(value = <span style="color:#cd5555">&#34;/cart.html&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> String <span style="color:#008b45">cartListPage</span>(Model model) <span style="color:#8b008b;font-weight:bold">throws</span> ExecutionException, InterruptedException {
    CartVo cartVo = cartService.<span style="color:#658b00">getCart</span>();
    model.<span style="color:#658b00">addAttribute</span>(<span style="color:#cd5555">&#34;cart&#34;</span>, cartVo);
    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;cartList&#34;</span>;
}
</code></pre></div><ul>
<li>CartServiceImpl.java
<ul>
<li>如果登入了，要把臨時車上的合併過來並清空臨時車</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 跳轉cartList頁面
</span><span style="color:#228b22"> * 封裝購物車類【所有商品，所有商品的價格】
</span><span style="color:#228b22"> * 【整合登入狀態與未登入狀態】
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> CartVo <span style="color:#008b45">getCart</span>() <span style="color:#8b008b;font-weight:bold">throws</span> ExecutionException, InterruptedException {
    CartVo cartVo = <span style="color:#8b008b;font-weight:bold">new</span> CartVo();
    UserInfoTo userInfoTo = CartInterceptor.<span style="color:#658b00">toThreadLocal</span>.<span style="color:#658b00">get</span>();
    System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(userInfoTo);
    <span style="color:#8b008b;font-weight:bold">if</span> (userInfoTo.<span style="color:#658b00">getUserId</span>() != <span style="color:#8b008b;font-weight:bold">null</span>) {
        <span style="color:#228b22">//  1）、登入後購物車的key
</span><span style="color:#228b22"></span>        String cartKey = CartConstant.<span style="color:#658b00">CART_PREFIX</span> + userInfoTo.<span style="color:#658b00">getUserId</span>();
        <span style="color:#228b22">//  2）、臨時購物車的key
</span><span style="color:#228b22"></span>        String temptCartKey = CartConstant.<span style="color:#658b00">CART_PREFIX</span> + userInfoTo.<span style="color:#658b00">getUserKey</span>();
        <span style="color:#228b22">// 如果臨時購物車的數據還未進行合併
</span><span style="color:#228b22"></span>        List&lt;CartItemVo&gt; tempCartItems = getCartItems(temptCartKey);
        <span style="color:#8b008b;font-weight:bold">if</span> (tempCartItems != <span style="color:#8b008b;font-weight:bold">null</span>) {
            <span style="color:#228b22">// 臨時購物車有數據需要進行合併操作
</span><span style="color:#228b22"></span>            <span style="color:#8b008b;font-weight:bold">for</span> (CartItemVo item : tempCartItems) {
                addToCart(item.<span style="color:#658b00">getSkuId</span>(), item.<span style="color:#658b00">getCount</span>());
            }
            <span style="color:#228b22">// 清除臨時購物車的數據
</span><span style="color:#228b22"></span>            clearCartInfo(temptCartKey);
        }
        <span style="color:#228b22">// 獲取登入後的購物車數據【包含合併過來的臨時購物車的數據和登入後購物車的數據】
</span><span style="color:#228b22"></span>        List&lt;CartItemVo&gt; cartItems = getCartItems(cartKey);
        cartVo.<span style="color:#658b00">setItems</span>(cartItems);
    } <span style="color:#8b008b;font-weight:bold">else</span> {
        <span style="color:#228b22">// 沒登入
</span><span style="color:#228b22"></span>        String cartKey = CartConstant.<span style="color:#658b00">CART_PREFIX</span> + userInfoTo.<span style="color:#658b00">getUserKey</span>();
        <span style="color:#228b22">// 獲取臨時購物車裡面的所有購物項
</span><span style="color:#228b22"></span>        List&lt;CartItemVo&gt; cartItems = getCartItems(cartKey);
        cartVo.<span style="color:#658b00">setItems</span>(cartItems);
    }
    <span style="color:#8b008b;font-weight:bold">return</span> cartVo;
}
</code></pre></div><div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 獲取購物車裡面的數據【根據key，包裝成List&lt;CartItemVo&gt;】，合併臨時車用
</span><span style="color:#228b22"> * key=【mall:cart:2 或 mall:cart:lkajkashjghj2989dsj】
</span><span style="color:#228b22"> *
</span><span style="color:#228b22"> * @param cartKey
</span><span style="color:#228b22"> * @return
</span><span style="color:#228b22"> */</span>
<span style="color:#8b008b;font-weight:bold">private</span> List&lt;CartItemVo&gt; <span style="color:#008b45">getCartItems</span>(String cartKey) {
    <span style="color:#228b22">// 獲取購物車裡面的所有商品
</span><span style="color:#228b22"></span>    BoundHashOperations&lt;String, Object, Object&gt; operations = redisTemplate.<span style="color:#658b00">boundHashOps</span>(cartKey);
    List&lt;Object&gt; values = operations.<span style="color:#658b00">values</span>();
    <span style="color:#8b008b;font-weight:bold">if</span> (values != <span style="color:#8b008b;font-weight:bold">null</span> &amp;&amp; values.<span style="color:#658b00">size</span>() &gt; 0) {
        List&lt;CartItemVo&gt; cartItemVoStream = values.<span style="color:#658b00">stream</span>().<span style="color:#658b00">map</span>((obj) -&gt; {
            String str = (String) obj;
            CartItemVo cartItem = JSON.<span style="color:#658b00">parseObject</span>(str, CartItemVo.<span style="color:#658b00">class</span>);
            <span style="color:#8b008b;font-weight:bold">return</span> cartItem;
        }).<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toList</span>());
        <span style="color:#8b008b;font-weight:bold">return</span> cartItemVoStream;
    }
    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">null</span>;
}
</code></pre></div><h2 id="添加至車">添加至車</h2>
<ul>
<li>CartController.java
<ul>
<li>添加完用redirect跳轉，防止重複提交</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 添加商品到購物車
</span><span style="color:#228b22"> * attributes.addFlashAttribute():將數據放在session中，可以在頁面中取出，但是只能取一次
</span><span style="color:#228b22"> * attributes.addAttribute():將數據放在url後面
</span><span style="color:#228b22"> *
</span><span style="color:#228b22"> * @return
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@GetMapping</span>(value = <span style="color:#cd5555">&#34;/addCartItem&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> String <span style="color:#008b45">addCartItem</span>(<span style="color:#707a7c">@RequestParam</span>(<span style="color:#cd5555">&#34;skuId&#34;</span>) Long skuId,
                          <span style="color:#707a7c">@RequestParam</span>(<span style="color:#cd5555">&#34;num&#34;</span>) Integer num,
                          RedirectAttributes attributes) <span style="color:#8b008b;font-weight:bold">throws</span> ExecutionException, InterruptedException {
    cartService.<span style="color:#658b00">addToCart</span>(skuId, num);
    attributes.<span style="color:#658b00">addAttribute</span>(<span style="color:#cd5555">&#34;skuId&#34;</span>, skuId);<span style="color:#228b22">// 給重定向請求用的【參數會拼接在下面請求之後】【轉發會在請求域中】
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;redirect:http://cart.mall.com/addToCartSuccessPage.html&#34;</span>;
}

<span style="color:#228b22">/**
</span><span style="color:#228b22"> * 跳轉到添加購物車成功頁面【防止重複提交】
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@GetMapping</span>(value = <span style="color:#cd5555">&#34;/addToCartSuccessPage.html&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> String <span style="color:#008b45">addToCartSuccessPage</span>(<span style="color:#707a7c">@RequestParam</span>(<span style="color:#cd5555">&#34;skuId&#34;</span>) Long skuId,
                                   Model model) {
    <span style="color:#228b22">//重定向到成功頁面。再次查詢購物車數據即可
</span><span style="color:#228b22"></span>    CartItemVo cartItemVo = cartService.<span style="color:#658b00">getCartItem</span>(skuId);
    model.<span style="color:#658b00">addAttribute</span>(<span style="color:#cd5555">&#34;cartItem&#34;</span>, cartItemVo);
    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;success&#34;</span>;
}

</code></pre></div><ul>
<li>CartServiceImpl.java
<ul>
<li>首先要在redis中開闢屬於某用戶的購物車物件，用<code>redisTemplate.boundHashOps()</code>方法，Key就是UserID，為了在redis中整理方便加上前綴<code>mall:cart:</code></li>
<li>前面在攔截器中把userInfo存到toThreadLocal了，如果未登入則會創造臨時的，所以從裡面必定能取出一個userId</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 獲取到我們要操作的購物車
</span><span style="color:#228b22"> * 簡化代碼：
</span><span style="color:#228b22"> * 1、判斷是否登入，拼接key
</span><span style="color:#228b22"> * 2、數據是hash類型，所以每次要調用兩次key【直接綁定外層key】
</span><span style="color:#228b22"> * 第一層key：mall:cart:2
</span><span style="color:#228b22"> * 第二層key：skuId
</span><span style="color:#228b22"> */</span>
<span style="color:#8b008b;font-weight:bold">private</span> BoundHashOperations&lt;String, Object, Object&gt; <span style="color:#008b45">getCartOps</span>() {
    <span style="color:#228b22">// 先得到當前用戶信息
</span><span style="color:#228b22"></span>    UserInfoTo userInfoTo = CartInterceptor.<span style="color:#658b00">toThreadLocal</span>.<span style="color:#658b00">get</span>();
    String cartKey = <span style="color:#cd5555">&#34;&#34;</span>;
    <span style="color:#8b008b;font-weight:bold">if</span> (userInfoTo.<span style="color:#658b00">getUserId</span>() != <span style="color:#8b008b;font-weight:bold">null</span>) {
        <span style="color:#228b22">// mall:cart:UserID
</span><span style="color:#228b22"></span>        cartKey = CartConstant.<span style="color:#658b00">CART_PREFIX</span> + userInfoTo.<span style="color:#658b00">getUserId</span>();
    } <span style="color:#8b008b;font-weight:bold">else</span> {
        cartKey = CartConstant.<span style="color:#658b00">CART_PREFIX</span> + userInfoTo.<span style="color:#658b00">getUserKey</span>();
    }
    <span style="color:#228b22">// 綁定指定的key操作Redis
</span><span style="color:#228b22"></span>    BoundHashOperations&lt;String, Object, Object&gt; operations = redisTemplate.<span style="color:#658b00">boundHashOps</span>(cartKey);
    <span style="color:#8b008b;font-weight:bold">return</span> operations;
}
</code></pre></div><ul>
<li>接著實作添加，先判斷商品項是否已經在車中
<ul>
<li>若無，就新增，需要遠程調用獲取skuInfo與skuAttrValues，這邊複製一份使用之前設定好的線程池config來用，異步獲取資訊後一樣用allOf與get等待全部任務完成，轉JSON後存到redis</li>
<li>若已經存在，只需要修改數量</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 添加商品到購物車
</span><span style="color:#228b22"> *
</span><span style="color:#228b22"> * @param skuId
</span><span style="color:#228b22"> * @param num
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> CartItemVo <span style="color:#008b45">addToCart</span>(Long skuId, Integer num) <span style="color:#8b008b;font-weight:bold">throws</span> ExecutionException, InterruptedException {
    <span style="color:#228b22">// 拿到要操作的購物車信息【cartOps就相當於綁定了當前用戶購物車數據的hash】
</span><span style="color:#228b22"></span>    BoundHashOperations&lt;String, Object, Object&gt; cartOps = getCartOps();
    <span style="color:#228b22">// 判斷Redis是否有該商品的信息
</span><span style="color:#228b22"></span>    String productRedisValue = (String) cartOps.<span style="color:#658b00">get</span>(skuId.<span style="color:#658b00">toString</span>());
    <span style="color:#228b22">// 如果沒有就添加數據【遠程查詢skuId】
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isEmpty</span>(productRedisValue)) {
        <span style="color:#228b22">// 添加新的商品到購物車(redis)
</span><span style="color:#228b22"></span>        CartItemVo cartItem = <span style="color:#8b008b;font-weight:bold">new</span> CartItemVo();
        <span style="color:#228b22">// 開啟第一個異步任務
</span><span style="color:#228b22"></span>        CompletableFuture&lt;Void&gt; getSkuInfoFuture = CompletableFuture.<span style="color:#658b00">runAsync</span>(() -&gt; {
            <span style="color:#228b22">// 遠程查詢當前要添加商品的信息
</span><span style="color:#228b22"></span>            R productSkuInfo = productFeignService.<span style="color:#658b00">getInfo</span>(skuId);
            SkuInfoVo skuInfo = productSkuInfo.<span style="color:#658b00">getData</span>(<span style="color:#cd5555">&#34;skuInfo&#34;</span>, <span style="color:#8b008b;font-weight:bold">new</span> TypeReference&lt;SkuInfoVo&gt;() {
            });
            <span style="color:#228b22">// 數據賦值操作
</span><span style="color:#228b22"></span>            cartItem.<span style="color:#658b00">setSkuId</span>(skuInfo.<span style="color:#658b00">getSkuId</span>());
            cartItem.<span style="color:#658b00">setTitle</span>(skuInfo.<span style="color:#658b00">getSkuTitle</span>());
            cartItem.<span style="color:#658b00">setImage</span>(skuInfo.<span style="color:#658b00">getSkuDefaultImg</span>());
            cartItem.<span style="color:#658b00">setPrice</span>(skuInfo.<span style="color:#658b00">getPrice</span>());
            cartItem.<span style="color:#658b00">setCount</span>(num);
            cartItem.<span style="color:#658b00">setCheck</span>(<span style="color:#8b008b;font-weight:bold">true</span>);
        }, executor);

        <span style="color:#228b22">// 開啟第二個異步任務
</span><span style="color:#228b22"></span>        CompletableFuture&lt;Void&gt; getSkuAttrValuesFuture = CompletableFuture.<span style="color:#658b00">runAsync</span>(() -&gt; {
            <span style="color:#228b22">// 遠程查詢skuAttrValues組合信息
</span><span style="color:#228b22"></span>            List&lt;String&gt; skuSaleAttrValues = productFeignService.<span style="color:#658b00">getSkuSaleAttrValues</span>(skuId);
            cartItem.<span style="color:#658b00">setSkuAttrValues</span>(skuSaleAttrValues);
        }, executor);
        <span style="color:#228b22">// 等待所有的異步任務全部完成
</span><span style="color:#228b22"></span>        CompletableFuture.<span style="color:#658b00">allOf</span>(getSkuInfoFuture, getSkuAttrValuesFuture).<span style="color:#658b00">get</span>();
        <span style="color:#228b22">// 序列化並存到redis
</span><span style="color:#228b22"></span>        String cartItemJson = JSON.<span style="color:#658b00">toJSONString</span>(cartItem);
        cartOps.<span style="color:#658b00">put</span>(skuId.<span style="color:#658b00">toString</span>(), cartItemJson);
        <span style="color:#8b008b;font-weight:bold">return</span> cartItem;
    } <span style="color:#8b008b;font-weight:bold">else</span> {
        <span style="color:#228b22">// 購物車中已有此商品，修改數量即可
</span><span style="color:#228b22"></span>        CartItemVo cartItemVo = JSON.<span style="color:#658b00">parseObject</span>(productRedisValue, CartItemVo.<span style="color:#658b00">class</span>);
        cartItemVo.<span style="color:#658b00">setCount</span>(cartItemVo.<span style="color:#658b00">getCount</span>() + num);
        <span style="color:#228b22">// 修改redis的數據
</span><span style="color:#228b22"></span>        String cartItemJson = JSON.<span style="color:#658b00">toJSONString</span>(cartItemVo);
        cartOps.<span style="color:#658b00">put</span>(skuId.<span style="color:#658b00">toString</span>(), cartItemJson);
        <span style="color:#8b008b;font-weight:bold">return</span> cartItemVo;
    }
}
</code></pre></div><h3 id="sql-concat的用法">SQL CONCAT的用法</h3>
<ul>
<li>在第二個遠程調用skuSaleAttrValues，想要返回 <code>機身：黑色</code>這樣的資料格式，用<code>CONCAT(A, &quot;：&quot;, B)</code></li>
</ul>
<pre tabindex="0"><code>&lt;select id=&quot;getSkuSaleAttrValuesAsStringList&quot; resultType=&quot;java.lang.String&quot;&gt;
    SELECT CONCAT(attr_name, &quot;：&quot;, attr_value)
    FROM pms_sku_sale_attr_value
    WHERE sku_id = #{skuId}
&lt;/select&gt;
</code></pre><h3 id="引導至添加成功頁面">引導至添加成功頁面</h3>
<ul>
<li>雖然我覺得這個功能怪怪的，誰添加成功還專門跑去看那一個品項，不應該是加了就顯示一個收過去車子的小動畫，讓用戶繼續逛同類項目嗎?</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 重定向頁面獲取當前購物車中sku商品信息
</span><span style="color:#228b22"> *
</span><span style="color:#228b22"> * @param skuId
</span><span style="color:#228b22"> * @return
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> CartItemVo <span style="color:#008b45">getCartItem</span>(Long skuId) {
    <span style="color:#228b22">//拿到要操作的購物車信息
</span><span style="color:#228b22"></span>    BoundHashOperations&lt;String, Object, Object&gt; cartOps = getCartOps();
    String redisValue = (String) cartOps.<span style="color:#658b00">get</span>(skuId.<span style="color:#658b00">toString</span>());
    CartItemVo cartItemVo = JSON.<span style="color:#658b00">parseObject</span>(redisValue, CartItemVo.<span style="color:#658b00">class</span>);
    <span style="color:#8b008b;font-weight:bold">return</span> cartItemVo;
}
</code></pre></div><h2 id="刪改">刪、改</h2>
<ul>
<li>沒什麼特殊的，就不多貼</li>
<li>比較特別的是&quot;選中&quot;這個功能，也做成了一個欄位跟修改的方法去保存到redis，即使關掉重開上次選中那些都會保留</li>
<li>可是他每次更改選/不選中都發一次請求給後端然後redirect，感覺好囧，應該用ajax，這個真的太扯了</li>
<li>立意良好，但感覺有點多餘了，應該給前端做就好，也沒人care關掉下次再進到購物車選中的狀態是否跟上次一樣吧</li>
<li>下單的時候也是要根據選中那些去計算價格與生成訂單</li>
</ul>
<h2 id="下單前計算價格">下單前計算價格</h2>
<ul>
<li>這個倒是能理解，下訂單之前，以前添加到車裡的項目，價格說不定有變動，不過只查價格是不是又不夠周全，如果商品下架了呢?
<ul>
<li>還是說他在訂單模組才會確認這點，不管了就先這樣吧</li>
</ul>
</li>
<li>CartServiceImpl.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 遠程調用：訂單服務調用【更新最新價格】
</span><span style="color:#228b22"> * 獲取當前用戶購物車所有選中的商品項check=true【從redis中取】
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> List&lt;CartItemVo&gt; <span style="color:#008b45">getUserCartItems</span>() {
    List&lt;CartItemVo&gt; cartItemVoList = <span style="color:#8b008b;font-weight:bold">new</span> ArrayList&lt;&gt;();
    <span style="color:#228b22">//獲取當前用戶登入的信息
</span><span style="color:#228b22"></span>    UserInfoTo userInfoTo = CartInterceptor.<span style="color:#658b00">toThreadLocal</span>.<span style="color:#658b00">get</span>();
    <span style="color:#228b22">//如果用戶未登入直接返回null
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (userInfoTo.<span style="color:#658b00">getUserId</span>() == <span style="color:#8b008b;font-weight:bold">null</span>) {
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">null</span>;
    } <span style="color:#8b008b;font-weight:bold">else</span> {
        <span style="color:#228b22">//獲取購物車項
</span><span style="color:#228b22"></span>        String cartKey = CartConstant.<span style="color:#658b00">CART_PREFIX</span> + userInfoTo.<span style="color:#658b00">getUserId</span>();
        <span style="color:#228b22">//獲取所有的
</span><span style="color:#228b22"></span>        List&lt;CartItemVo&gt; cartItems = getCartItems(cartKey);
        <span style="color:#8b008b;font-weight:bold">if</span> (cartItems == <span style="color:#8b008b;font-weight:bold">null</span>) {
            <span style="color:#8b008b;font-weight:bold">throw</span> <span style="color:#8b008b;font-weight:bold">new</span> CartExceptionHandler();
        }
        <span style="color:#228b22">//篩選出選中的
</span><span style="color:#228b22"></span>        cartItemVoList = cartItems.<span style="color:#658b00">stream</span>()
                .<span style="color:#658b00">filter</span>(items -&gt; items.<span style="color:#658b00">getCheck</span>())
                .<span style="color:#658b00">map</span>(item -&gt; {
                    <span style="color:#228b22">//更新為最新的價格（查詢數據庫）
</span><span style="color:#228b22"></span>                    <span style="color:#228b22">// redis中的價格不是最新的
</span><span style="color:#228b22"></span>                    BigDecimal price = productFeignService.<span style="color:#658b00">getPrice</span>(item.<span style="color:#658b00">getSkuId</span>());
                    item.<span style="color:#658b00">setPrice</span>(price);
                    <span style="color:#8b008b;font-weight:bold">return</span> item;
                })
                .<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toList</span>());
    }
    <span style="color:#8b008b;font-weight:bold">return</span> cartItemVoList;
}
</code></pre></div><h1 id="小結">小結</h1>
<h3 id="攔截器-1">攔截器</h3>
<ul>
<li>可以用來修飾request</li>
<li>到WebMvcConfigurer註冊，重寫preHandle或postHandle方法</li>
<li>用ThreadLocal作為同一線程的置物櫃
<ul>
<li>這玩意我記得用完要清，但是找不到好地方清，只能期待他的弱引用過自己清理吧</li>
</ul>
</li>
</ul>
<h2 id="在redis添加hash">在redis添加hash</h2>
<pre tabindex="0"><code>redisTemplate.boundHashOps(key)
</code></pre><h2 id="異步任務">異步任務</h2>
<h3 id="先自訂線程池">先自訂線程池</h3>
<ul>
<li>application.properties</li>
</ul>
<pre tabindex="0"><code class="language-properties" data-lang="properties"># 線程池相關
mall.thread.core-size=20
mall.thread.max-size=200
mall.thread.keep-alive-time=10
</code></pre><ul>
<li>ThreadPoolConfigProperties.java
<ul>
<li>這是造了一個類，應該也可以用<code>@values</code></li>
<li>後來才懂原來那些框架底層就是這樣寫的封裝好了，所以在properties寫參數就能完成配置</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@ConfigurationProperties</span>(prefix = <span style="color:#cd5555">&#34;mall.thread&#34;</span>)
<span style="color:#707a7c">@Component</span>
<span style="color:#707a7c">@Data</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">ThreadPoolConfigProperties</span> {
    <span style="color:#8b008b;font-weight:bold">private</span> Integer coreSize;
    <span style="color:#8b008b;font-weight:bold">private</span> Integer maxSize;
    <span style="color:#8b008b;font-weight:bold">private</span> Integer keepAliveTime;
}
</code></pre></div><ul>
<li>CustomThreadConfig.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Configuration</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">CustomThreadConfig</span> {

    <span style="color:#707a7c">@Bean</span>
    <span style="color:#8b008b;font-weight:bold">public</span> ThreadPoolExecutor <span style="color:#008b45">threadPoolExecutor</span>(ThreadPoolConfigProperties properties) {
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">new</span> ThreadPoolExecutor(
                properties.<span style="color:#658b00">getCoreSize</span>(),
                properties.<span style="color:#658b00">getMaxSize</span>(),
                properties.<span style="color:#658b00">getKeepAliveTime</span>(),
                TimeUnit.<span style="color:#658b00">SECONDS</span>,
                <span style="color:#8b008b;font-weight:bold">new</span> LinkedBlockingDeque&lt;&gt;(10000),
                Executors.<span style="color:#658b00">defaultThreadFactory</span>(),
                <span style="color:#8b008b;font-weight:bold">new</span> ThreadPoolExecutor.<span style="color:#658b00">AbortPolicy</span>()
        );
    }
}
</code></pre></div><h3 id="使用">使用</h3>
<ul>
<li>注入 ThreadPoolExecutor</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Autowired</span>
<span style="color:#8b008b;font-weight:bold">private</span> ThreadPoolExecutor executor;
</code></pre></div><ul>
<li>編排CompletableFuture
<ul>
<li>記得傳入自定義的executor，否則會造預設的線程池
<ul>
<li>用同一個鍋煮菜，而非一直用新鍋</li>
</ul>
</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java">CompletableFuture&lt;Void&gt; xxxFuture = CompletableFuture.<span style="color:#658b00">runAsync</span>(() -&gt; {
<span style="color:#228b22">// 任務
</span><span style="color:#228b22"></span>}, executor);
</code></pre></div><ul>
<li>阻塞等待收集結果</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java">CompletableFuture.<span style="color:#658b00">allOf</span>(xxxFuture, oooFuture...).<span style="color:#658b00">get</span>();
</code></pre></div>- https://yoziming.github.io/post/220203-gulimall-17-offline-cart/ - Yoziming

柚子茶室 https://yoziming.github.io/post/220203-leetcode-easy-26-28/ -<h3 id="26-remove-duplicates-from-sorted-array">\26. Remove Duplicates from Sorted Array</h3>
<blockquote>
<p>數組去重</p>
</blockquote>
<ul>
<li>想對數組做啥，都可以考慮雙指針</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">int</span> <span style="color:#008b45">removeDuplicates</span>(<span style="color:#00688b;font-weight:bold">int</span>[] nums) {
    <span style="color:#228b22">// 起始第一個指針從頭開始
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">int</span> p = 0;
    <span style="color:#228b22">// 第二個指針，從p+1開始
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">for</span> (<span style="color:#00688b;font-weight:bold">int</span> q = 1; q &lt; nums.<span style="color:#658b00">length</span>; ) {
        <span style="color:#228b22">// 如果不一樣
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">if</span> (nums[p] != nums[q]) {
            <span style="color:#228b22">// 就把q往前搬，讓不一樣的數緊貼著第一個指針
</span><span style="color:#228b22"></span>            nums[p + 1] = nums[q];
            <span style="color:#228b22">// 並且讓第一個指針P移往下一步
</span><span style="color:#228b22"></span>            p++;
        }
        <span style="color:#228b22">// 如果數字一樣表示要被忽略，q往後移，直到找到不同的數字
</span><span style="color:#228b22"></span>        q++;
    }
    <span style="color:#228b22">//
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">return</span> p + 1;
}
</code></pre></div><h3 id="27-remove-element">\27. Remove Element</h3>
<ul>
<li>指針的妙用</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">int</span> <span style="color:#008b45">removeElement</span>(<span style="color:#00688b;font-weight:bold">int</span>[] nums, <span style="color:#00688b;font-weight:bold">int</span> val) {
    <span style="color:#228b22">// 指針
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">int</span> idx = 0;
    <span style="color:#228b22">// 遍歷數組
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">for</span> (<span style="color:#00688b;font-weight:bold">int</span> num : nums) {
        <span style="color:#228b22">// 如果不是要移除的
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">if</span> (num != val) {
            <span style="color:#228b22">// 就保持原樣
</span><span style="color:#228b22"></span>            nums[idx] = num;
            <span style="color:#228b22">// 並且指針往後移
</span><span style="color:#228b22"></span>            idx++;
        }
        <span style="color:#228b22">// 如果是要移除的，那就不會保留，且被之後的數據覆蓋
</span><span style="color:#228b22"></span>    }
    <span style="color:#8b008b;font-weight:bold">return</span> idx;
}
</code></pre></div><h3 id="28-implement-strstr">\28. Implement strStr()</h3>
<ul>
<li>匹配字符串，原諒我只會基礎暴力法</li>
<li>KMP 解法更優，然而我看半天，當下以為懂了隔一會再看又矇了，實在看暈了</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">int</span> <span style="color:#008b45">strStr</span>(String haystack, String needle) {
    <span style="color:#228b22">// 先取出長度，m是長串，n是要匹配的針
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">int</span> m = haystack.<span style="color:#658b00">length</span>(), n = needle.<span style="color:#658b00">length</span>();
    <span style="color:#228b22">// 轉換成Array
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">char</span>[] s = haystack.<span style="color:#658b00">toCharArray</span>(), p = needle.<span style="color:#658b00">toCharArray</span>();
    <span style="color:#228b22">// 開始第一層遍歷，動的是haystack的索引，最終要返回的是索引i位於何處
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// 因為假設haystack包含needle，所以i的長度不會大於m - n
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">for</span> (<span style="color:#00688b;font-weight:bold">int</span> i = 0; i &lt;= m - n; i++) {
        <span style="color:#228b22">// 第二層遍歷，在haystack的i位置上，嘗試匹配是否後續的字=needle
</span><span style="color:#228b22"></span>        <span style="color:#228b22">// a是i是haystack的索引，b是needle的頭
</span><span style="color:#228b22"></span>        <span style="color:#00688b;font-weight:bold">int</span> a = i, b = 0;
        <span style="color:#228b22">// 從haystack的i位置上，與needle的頭開始一位一位比較，相同就往後再比
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">while</span> (b &lt; n &amp;&amp; s[a] == p[b]) {
            a++;
            b++;
        }
        <span style="color:#228b22">// 當b的長度等於needle的長度n，表示完全匹配，haystack確實包含了needle
</span><span style="color:#228b22"></span>        <span style="color:#228b22">// 就返回索引i所在的位置
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">if</span> (b == n) <span style="color:#8b008b;font-weight:bold">return</span> i;
    }
    <span style="color:#228b22">// 全部跑完發現沒包含，返回-1
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">return</span> -1;
}
</code></pre></div>- https://yoziming.github.io/post/220203-leetcode-easy-26-28/ - Yoziming

柚子茶室 https://yoziming.github.io/post/220202-gulimall-16-spring-session/ -<h2 id="webmvcconfigurer">WebMvcConfigurer</h2>
<blockquote>
<p>參考 <a href="https://blog.csdn.net/pan_junbiao/article/details/120039885">https://blog.csdn.net/pan_junbiao/article/details/120039885</a></p>
</blockquote>
<ul>
<li>複習SpringMVC</li>
<li>WebMvcConfigurer是一個接口，用JavaBean的方式代替web.xml，常用於:</li>
<li>攔截器，例如:</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">addInterceptors</span>(InterceptorRegistry registry) {
    <span style="color:#8b008b;font-weight:bold">super</span>.<span style="color:#658b00">addInterceptors</span>(registry);
    registry.<span style="color:#658b00">addInterceptor</span>(<span style="color:#8b008b;font-weight:bold">new</span> TestInterceptor()).<span style="color:#658b00">addPathPatterns</span>(<span style="color:#cd5555">&#34;/**&#34;</span>).<span style="color:#658b00">excludePathPatterns</span>(<span style="color:#cd5555">&#34;/emp/toLogin&#34;</span>,<span style="color:#cd5555">&#34;/emp/login&#34;</span>,<span style="color:#cd5555">&#34;/js/**&#34;</span>,<span style="color:#cd5555">&#34;/css/**&#34;</span>,<span style="color:#cd5555">&#34;/images/**&#34;</span>);
}
</code></pre></div><ul>
<li>跨域設定，例如:</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">// 跨域
</span><span style="color:#228b22"></span><span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">addCorsMappings</span>(CorsRegistry registry) {
    registry.<span style="color:#658b00">addMapping</span>(<span style="color:#cd5555">&#34;/**&#34;</span>)
            .<span style="color:#658b00">allowedOrigins</span>(<span style="color:#cd5555">&#34;*&#34;</span>)  <span style="color:#228b22">//浏览器允许所有的域访问 / 注意 * 不能满足带有cookie的访问,Origin 必须是全匹配
</span><span style="color:#228b22"></span>            .<span style="color:#658b00">allowCredentials</span>(<span style="color:#8b008b;font-weight:bold">true</span>)   <span style="color:#228b22">// 允许带cookie访问
</span><span style="color:#228b22"></span>            .<span style="color:#658b00">allowedMethods</span>(<span style="color:#cd5555">&#34;GET&#34;</span>, <span style="color:#cd5555">&#34;POST&#34;</span>, <span style="color:#cd5555">&#34;PUT&#34;</span>, <span style="color:#cd5555">&#34;DELETE&#34;</span>, <span style="color:#cd5555">&#34;OPTIONS&#34;</span>)
            .<span style="color:#658b00">allowedHeaders</span>(<span style="color:#cd5555">&#34;token&#34;</span>)
            .<span style="color:#658b00">maxAge</span>(3600);
}
</code></pre></div><blockquote>
<p>更多關於跨域，參考 <a href="https://segmentfault.com/a/1190000019485883">https://segmentfault.com/a/1190000019485883</a></p>
</blockquote>
<ul>
<li>映射html頁面
<ul>
<li>前後綴一樣由thymeleaf加上</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Configuration</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">MallWebConfig</span> <span style="color:#8b008b;font-weight:bold">implements</span> WebMvcConfigurer {

    <span style="color:#228b22">// View映射，省下造controller一個一個設定
</span><span style="color:#228b22"></span>    <span style="color:#707a7c">@Override</span>
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">addViewControllers</span>(ViewControllerRegistry registry) {
        registry.<span style="color:#658b00">addViewController</span>(<span style="color:#cd5555">&#34;/&#34;</span>).<span style="color:#658b00">setViewName</span>(<span style="color:#cd5555">&#34;login&#34;</span>);
        registry.<span style="color:#658b00">addViewController</span>(<span style="color:#cd5555">&#34;/login.html&#34;</span>).<span style="color:#658b00">setViewName</span>(<span style="color:#cd5555">&#34;login&#34;</span>);
        registry.<span style="color:#658b00">addViewController</span>(<span style="color:#cd5555">&#34;/reg.html&#34;</span>).<span style="color:#658b00">setViewName</span>(<span style="color:#cd5555">&#34;reg&#34;</span>);
    }
}
