<span style="color:#707a7c">@GetMapping</span>(value = <span style="color:#cd5555">&#34;/login.html&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> String <span style="color:#008b45">loginPage</span>() {
<span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;login&#34;</span>;
}
</code></pre></div><h2 id="註冊">註冊</h2>
<ul>
<li>LoginController.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">// 註冊
</span><span style="color:#228b22"></span><span style="color:#707a7c">@PostMapping</span>(value = <span style="color:#cd5555">&#34;/register&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> String <span style="color:#008b45">register</span>(<span style="color:#707a7c">@Valid</span> UserRegisterVo vos, BindingResult result, RedirectAttributes attributes) {

    <span style="color:#228b22">// 如果有錯誤回到註冊頁面
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (result.<span style="color:#658b00">hasErrors</span>()) {
        Map&lt;String, String&gt; errors =
                result.<span style="color:#658b00">getFieldErrors</span>().<span style="color:#658b00">stream</span>().<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toMap</span>(FieldError::getField,
                        FieldError::getDefaultMessage));
        attributes.<span style="color:#658b00">addAttribute</span>(<span style="color:#cd5555">&#34;errors&#34;</span>, errors);
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;redirect:http://auth.mall.com/reg.html&#34;</span>;
    }
    <span style="color:#228b22">// 前端驗證被繞過，若傳空值讓他返回
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (vos.<span style="color:#658b00">getPassword</span>().<span style="color:#658b00">isEmpty</span>() || vos.<span style="color:#658b00">getCode</span>().<span style="color:#658b00">isEmpty</span>() || vos.<span style="color:#658b00">getUserName</span>().<span style="color:#658b00">isEmpty</span>() || vos.<span style="color:#658b00">getPhone</span>().<span style="color:#658b00">isEmpty</span>()) {
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;redirect:http://auth.mall.com/reg.html&#34;</span>;
    }

    <span style="color:#228b22">// 獲取驗證碼
</span><span style="color:#228b22"></span>    String code = vos.<span style="color:#658b00">getCode</span>();
    <span style="color:#228b22">//驗證碼通過，真正註冊，調用遠程服務進行註冊會員
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (code.<span style="color:#658b00">equals</span>(<span style="color:#cd5555">&#34;1234&#34;</span>)) {
        R register = memberFeignService.<span style="color:#658b00">register</span>(vos);
        <span style="color:#8b008b;font-weight:bold">if</span> (register.<span style="color:#658b00">getCode</span>() == 0) {
            <span style="color:#228b22">//成功
</span><span style="color:#228b22"></span>            <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;redirect:http://auth.mall.com/login.html&#34;</span>;
        } <span style="color:#8b008b;font-weight:bold">else</span> {
            <span style="color:#228b22">//失敗
</span><span style="color:#228b22"></span>            Map&lt;String, String&gt; errors = <span style="color:#8b008b;font-weight:bold">new</span> HashMap&lt;&gt;();
            errors.<span style="color:#658b00">put</span>(<span style="color:#cd5555">&#34;msg&#34;</span>, register.<span style="color:#658b00">getData</span>(<span style="color:#cd5555">&#34;msg&#34;</span>, <span style="color:#8b008b;font-weight:bold">new</span> TypeReference&lt;String&gt;() {
            }));
            attributes.<span style="color:#658b00">addFlashAttribute</span>(<span style="color:#cd5555">&#34;errors&#34;</span>, errors);
            <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;redirect:http://auth.mall.com/reg.html&#34;</span>;
        }
    } <span style="color:#8b008b;font-weight:bold">else</span> {
        <span style="color:#228b22">//驗證碼錯誤
</span><span style="color:#228b22"></span>        Map&lt;String, String&gt; errors = <span style="color:#8b008b;font-weight:bold">new</span> HashMap&lt;&gt;();
        errors.<span style="color:#658b00">put</span>(<span style="color:#cd5555">&#34;code&#34;</span>, <span style="color:#cd5555">&#34;驗證碼錯誤&#34;</span>);
        attributes.<span style="color:#658b00">addFlashAttribute</span>(<span style="color:#cd5555">&#34;errors&#34;</span>, errors);
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;redirect:http://auth.mall.com/reg.html&#34;</span>;
    }
}
</code></pre></div><ul>
<li>
<p>知識點:</p>
<ul>
<li>
<p>用拋出異常的方式告知是否重複註冊</p>
</li>
<li>
<p>用MD5加鹽加密，好處:</p>
<ul>
<li>快速、抗改(雪崩效應，只要有原始資料任何變化算出的MD5都會天差地別)、不可逆</li>
<li>但是可以暴力破解，所以要加鹽</li>
</ul>
</li>
</ul>
</li>
<li>
<p>MemberController.java</p>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@PostMapping</span>(value = <span style="color:#cd5555">&#34;/register&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> R <span style="color:#008b45">register</span>(<span style="color:#707a7c">@RequestBody</span> MemberUserRegisterVo vo) {
    <span style="color:#8b008b;font-weight:bold">try</span> {
        memberService.<span style="color:#658b00">register</span>(vo);
    } <span style="color:#8b008b;font-weight:bold">catch</span> (PhoneException e) {
        <span style="color:#8b008b;font-weight:bold">return</span> R.<span style="color:#658b00">error</span>(BizCodeEnum.<span style="color:#658b00">PHONE_EXIST_EXCEPTION</span>.<span style="color:#658b00">getCode</span>(), BizCodeEnum.<span style="color:#658b00">PHONE_EXIST_EXCEPTION</span>.<span style="color:#658b00">getMessage</span>());
    } <span style="color:#8b008b;font-weight:bold">catch</span> (UsernameException e) {
        <span style="color:#8b008b;font-weight:bold">return</span> R.<span style="color:#658b00">error</span>(BizCodeEnum.<span style="color:#658b00">USER_EXIST_EXCEPTION</span>.<span style="color:#658b00">getCode</span>(), BizCodeEnum.<span style="color:#658b00">USER_EXIST_EXCEPTION</span>.<span style="color:#658b00">getMessage</span>());
    }
    <span style="color:#8b008b;font-weight:bold">return</span> R.<span style="color:#658b00">ok</span>();
}
</code></pre></div><ul>
<li>MemberServiceImpl.java
<ul>
<li>Spring的BCryptPasswordEncoder已經自動加鹽了</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">register</span>(MemberUserRegisterVo vo) {
    MemberEntity memberEntity = <span style="color:#8b008b;font-weight:bold">new</span> MemberEntity();

    <span style="color:#228b22">// 設置等級為普通會員
</span><span style="color:#228b22"></span>    MemberLevelEntity levelEntity = memberLevelDao.<span style="color:#658b00">getDefaultLevel</span>();
    memberEntity.<span style="color:#658b00">setLevelId</span>(levelEntity.<span style="color:#658b00">getId</span>());

    <span style="color:#228b22">// 檢查用戶名和手機號是否唯一，可能拋出異常
</span><span style="color:#228b22"></span>    checkPhoneUnique(vo.<span style="color:#658b00">getPhone</span>());
    checkUserNameUnique(vo.<span style="color:#658b00">getUserName</span>());

    <span style="color:#228b22">// 設定帳號密碼
</span><span style="color:#228b22"></span>    memberEntity.<span style="color:#658b00">setNickname</span>(vo.<span style="color:#658b00">getUserName</span>());
    memberEntity.<span style="color:#658b00">setUsername</span>(vo.<span style="color:#658b00">getUserName</span>());
    <span style="color:#228b22">// 密碼進行MD5加密
</span><span style="color:#228b22"></span>    BCryptPasswordEncoder bCryptPasswordEncoder = <span style="color:#8b008b;font-weight:bold">new</span> BCryptPasswordEncoder();
    String encode = bCryptPasswordEncoder.<span style="color:#658b00">encode</span>(vo.<span style="color:#658b00">getPassword</span>());
    memberEntity.<span style="color:#658b00">setPassword</span>(encode);
    memberEntity.<span style="color:#658b00">setMobile</span>(vo.<span style="color:#658b00">getPhone</span>());
    memberEntity.<span style="color:#658b00">setGender</span>(0);
    <span style="color:#228b22">// memberEntity.setCreateTime(new Date());
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// 保存
</span><span style="color:#228b22"></span>    baseMapper.<span style="color:#658b00">insert</span>(memberEntity);
}

<span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">checkPhoneUnique</span>(String phone) <span style="color:#8b008b;font-weight:bold">throws</span> PhoneException {
    Long phoneCount = baseMapper.<span style="color:#658b00">selectCount</span>(<span style="color:#8b008b;font-weight:bold">new</span> QueryWrapper&lt;MemberEntity&gt;().<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;mobile&#34;</span>, phone));
    <span style="color:#8b008b;font-weight:bold">if</span> (phoneCount &gt; 0) {
        <span style="color:#8b008b;font-weight:bold">throw</span> <span style="color:#8b008b;font-weight:bold">new</span> PhoneException();
    }
}

<span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">checkUserNameUnique</span>(String userName) <span style="color:#8b008b;font-weight:bold">throws</span> UsernameException {
    Long usernameCount = baseMapper.<span style="color:#658b00">selectCount</span>(<span style="color:#8b008b;font-weight:bold">new</span> QueryWrapper&lt;MemberEntity&gt;().<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;username&#34;</span>, userName));
    <span style="color:#8b008b;font-weight:bold">if</span> (usernameCount &gt; 0) {
        <span style="color:#8b008b;font-weight:bold">throw</span> <span style="color:#8b008b;font-weight:bold">new</span> UsernameException();
    }
}
</code></pre></div><h3 id="知識點">知識點</h3>
<blockquote>
<p>addAttribute與addFlashAttribute的區別</p>
</blockquote>
<pre tabindex="0"><code>attr.addAttribute(“param”, value);
</code></pre><ul>
<li>這種方式就相當於重定向之後，在url後面拼接參數，這樣在重定向之後的頁面或者控制器再去獲取url後面的參數就可以了，但這個方式因為是在url後面添加參數的方式，所以暴露了參數，有風險</li>
</ul>
<pre tabindex="0"><code>attr.addFlashAttribute(“param”, value);
</code></pre><ul>
<li>這種方式也能達到重新向帶參，而且能隱藏參數，其原理就是放到session中，session在跳到頁面后馬上移除對象</li>
</ul>
<h2 id="登入">登入</h2>
<ul>
<li>LoginController.java
<ul>
<li><code>AuthServerConstant.LOGIN_USER</code>其實就是<code>&quot;loginUser&quot;</code>，放成常數是為了避免使用魔法值</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@PostMapping</span>(value = <span style="color:#cd5555">&#34;/login&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> String <span style="color:#008b45">login</span>(UserLoginVo vo, RedirectAttributes attributes, HttpSession session) {
    <span style="color:#228b22">// 遠程調用member的驗證帳號密碼服務
</span><span style="color:#228b22"></span>    R login = memberFeignService.<span style="color:#658b00">login</span>(vo);
    <span style="color:#8b008b;font-weight:bold">if</span> (login.<span style="color:#658b00">getCode</span>() == 0) {
        MemberResponseVo data = login.<span style="color:#658b00">getData</span>(<span style="color:#cd5555">&#34;data&#34;</span>, <span style="color:#8b008b;font-weight:bold">new</span> TypeReference&lt;MemberResponseVo&gt;() {
        });
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;用戶&#34;</span>+data.<span style="color:#658b00">getUsername</span>()+<span style="color:#cd5555">&#34;登入成功&#34;</span>);
        session.<span style="color:#658b00">setAttribute</span>(AuthServerConstant.<span style="color:#658b00">LOGIN_USER</span>, data);
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;redirect:http://mall.com&#34;</span>;
    } <span style="color:#8b008b;font-weight:bold">else</span> {
        Map&lt;String, String&gt; errors = <span style="color:#8b008b;font-weight:bold">new</span> HashMap&lt;&gt;();
        errors.<span style="color:#658b00">put</span>(<span style="color:#cd5555">&#34;msg&#34;</span>, login.<span style="color:#658b00">getData</span>(<span style="color:#cd5555">&#34;msg&#34;</span>, <span style="color:#8b008b;font-weight:bold">new</span> TypeReference&lt;String&gt;() {
        }));
        attributes.<span style="color:#658b00">addFlashAttribute</span>(<span style="color:#cd5555">&#34;errors&#34;</span>, errors);
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;redirect:http://auth.mall.com/login.html&#34;</span>;
    }
}
</code></pre></div><ul>
<li>驗證帳號密碼很簡單就不貼了，接著主要處理Session的問題</li>
</ul>
<h3 id="第三方登入">第三方登入</h3>
<ul>
<li>第三方登入我自己用google試了都不成功，主要卡在不知道request網址到底該怎寫</li>
</ul>
<p><img src="image-20220125222347983.png" alt="image-20220125222347983"></p>
<ul>
<li>搜教學比較多是用spring security，照教學能造一個新的Login頁面，結合起來搞半天都失敗，唉先跳過吧</li>
</ul>
<h2 id="session共享問題">session共享問題</h2>
<ul>
<li>
<p>子網域、分散式服務用傳統session應付不來，有幾種可選方案</p>
</li>
<li>
<p>session複製，每一個session都複製到所有webserver中，Tomcat修改配置文件就能辦到</p>
<ul>
<li>缺點: 佔用多</li>
</ul>
</li>
<li>
<p>客户端存儲，保存在cookie中</p>
<ul>
<li>缺點: 安全隱患(篡改)、網絡流量、cookie長度限制</li>
</ul>
</li>
<li>
<p>hash一致性，例如拿客户端IP來計算，算出來一樣就負載均衡分到指定的伺服器</p>
<ul>
<li>缺點: 水平擴展會引發session失效</li>
</ul>
</li>
<li>
<p>統一存儲，例如把session存到redis</p>
<ul>
<li>缺點: redis還是比記憶體慢，多增溝通消耗，但問題不大</li>
</ul>
</li>
</ul>
<h1 id="spring-session">Spring Session</h1>
<blockquote>
<p>官方 <a href="https://docs.spring.io/spring-session/reference/samples.html">https://docs.spring.io/spring-session/reference/samples.html</a></p>
</blockquote>
<ul>
<li>Spring都幫你想好了，引包吧</li>
</ul>
<pre tabindex="0"><code>&lt;dependency&gt;
    &lt;groupId&gt;org.springframework.session&lt;/groupId&gt;
    &lt;artifactId&gt;spring-session-data-redis&lt;/artifactId&gt;
    &lt;version&gt;2.6.1&lt;/version&gt;
&lt;/dependency&gt;
</code></pre><ul>
<li>application.properties
<ul>
<li>還可以設定過期時間等等，預設是30m</li>
</ul>
</li>
</ul>
<pre tabindex="0"><code>spring.session.store-type=redis
# 當然還要設定redis所在
spring.redis.host=localhost
spring.redis.port=6379
</code></pre><ul>
<li>到啟動類註解<code>@EnableRedisHttpSession</code></li>
</ul>
<p><img src="image-20220125201947928.png" alt="image-20220125201947928"></p>
<ul>
<li>將要存進session的bean序列化</li>
</ul>
<p><img src="image-20220125204057093.png" alt="image-20220125204057093"></p>
<h2 id="編碼問題">編碼問題</h2>
<ul>
<li>這樣一來存是能存了，然而是編成二進制類型，顯然不好用，應該改成JSON</li>
</ul>
<p><img src="image-20220125205905259.png" alt="image-20220125205905259"></p>
<h2 id="作用域問題">作用域問題</h2>
<ul>
<li>預設的session是根據當前域(在auth伺服器)存的，當回到主網域或轉到其他子網域就用不了</li>
</ul>
<p><img src="image-20220125210029897.png" alt="image-20220125210029897"></p>
<h2 id="一起解決">一起解決</h2>
<ul>
<li>MallSessionConfig.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Configuration</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">MallSessionConfig</span> {

    <span style="color:#707a7c">@Bean</span>
    <span style="color:#8b008b;font-weight:bold">public</span> CookieSerializer <span style="color:#008b45">cookieSerializer</span>() {
        DefaultCookieSerializer cookieSerializer = <span style="color:#8b008b;font-weight:bold">new</span> DefaultCookieSerializer();
        <span style="color:#228b22">// 放大作用域
</span><span style="color:#228b22"></span>        cookieSerializer.<span style="color:#658b00">setDomainName</span>(<span style="color:#cd5555">&#34;mall.com&#34;</span>);
        <span style="color:#228b22">// 自訂名稱
</span><span style="color:#228b22"></span>        cookieSerializer.<span style="color:#658b00">setCookieName</span>(<span style="color:#cd5555">&#34;MALLSESSION&#34;</span>);
        cookieSerializer.<span style="color:#658b00">setCookieMaxAge</span>(60 * 60 * 24 * 7);
        <span style="color:#8b008b;font-weight:bold">return</span> cookieSerializer;
    }

    <span style="color:#228b22">// 整成JSON格式
</span><span style="color:#228b22"></span>    <span style="color:#707a7c">@Bean</span>
    <span style="color:#8b008b;font-weight:bold">public</span> RedisSerializer&lt;Object&gt; <span style="color:#008b45">springSessionDefaultRedisSerializer</span>() {
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">new</span> GenericJackson2JsonRedisSerializer();
    }
}
</code></pre></div><ul>
<li>成功!</li>
</ul>
<p><img src="image-20220125211255800.png" alt="image-20220125211255800"></p>
<h2 id="核心原理">核心原理</h2>
<blockquote>
<p>裝飾者模式，就像鋼鐵人穿上<em>反浩克裝甲</em>，有額外增強但仍然保留原始功能</p>
</blockquote>
<ul>
<li><code>@EnablcRedisHttpSession</code>導入RedisHttpSessionConfiguration配置類，在這個配置類中有<code>SessionRepositoryFilter</code>過濾器</li>
<li>原始的http請求request和響應response經過濾器放行後，變成了<code>SessionRepositoryRequestWrapper</code>與<code>SessionRepositoryResponseWrapper</code></li>
<li>之後我們操作session其實就是操作這些Wrapper，而Wrapper把原始的session方法都重寫(加料)了，例如RedisHttpSession的<code>.getSession()</code>方法就是去redis找東西</li>
<li>Spring Session已經考慮過各種缺點，只要瀏覽器不關，會給redis中的session自動延期</li>
</ul>
<h2 id="完善登入功能">完善登入功能</h2>
<ul>
<li>添加Spring Session依賴、做好設定，現在Product模組、Search模組也都可以調用共享的session了</li>
<li>修改前端頁面，依據session判斷是否已登入</li>
</ul>
<p><img src="image-20220125222040181.png" alt="image-20220125222040181"></p>
<ul>
<li>LoginController.java
<ul>
<li>已經登入的人還想登入就讓它跳轉</li>
<li>要把之前設定的View映射關掉</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 判斷session是否有loginUser，沒有就跳轉登錄頁面，有就跳轉首頁
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@GetMapping</span>(value = <span style="color:#cd5555">&#34;/login.html&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> String <span style="color:#008b45">loginPage</span>(HttpSession session) {
    <span style="color:#228b22">// 從session先取出來用戶的信息，判斷用戶是否已經登錄過了
</span><span style="color:#228b22"></span>    Object attribute = session.<span style="color:#658b00">getAttribute</span>(AuthServerConstant.<span style="color:#658b00">LOGIN_USER</span>);
    <span style="color:#228b22">// 如果用戶沒登錄那就跳轉到登錄頁面
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (attribute == <span style="color:#8b008b;font-weight:bold">null</span>) {
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;login&#34;</span>;
    } <span style="color:#8b008b;font-weight:bold">else</span> {
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;redirect:http://mall.com&#34;</span>;
    }
}

<span style="color:#228b22">// 登出
</span><span style="color:#228b22"></span><span style="color:#707a7c">@GetMapping</span>(value = <span style="color:#cd5555">&#34;/loguot.html&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> String <span style="color:#008b45">logout</span>(HttpServletRequest request) {
    request.<span style="color:#658b00">getSession</span>().<span style="color:#658b00">removeAttribute</span>(AuthServerConstant.<span style="color:#658b00">LOGIN_USER</span>);
    request.<span style="color:#658b00">getSession</span>().<span style="color:#658b00">invalidate</span>();
    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;redirect:http://mall.com&#34;</span>;
}
</code></pre></div><h1 id="單點登入">單點登入</h1>
<blockquote>
<p>Single Sign On，簡稱SSO</p>
</blockquote>
<ul>
<li>用在不同域名，原理是有一個中央認證系統專門處理登入</li>
</ul>
<p><img src="image-20220125224243309.png" alt="image-20220125224243309"></p>
<ul>
<li>有很多實現方式，比較常見是用<strong>Token</strong></li>
<li>暫時應該是用不上，就只先了解一下，有需要再回來補</li>
<li><a href="https://www.bilibili.com/video/BV1np4y1C7Yf?p=233">https://www.bilibili.com/video/BV1np4y1C7Yf?p=233</a></li>
</ul>
- https://yoziming.github.io/post/220202-gulimall-16-spring-session/ - Yoziming

柚子茶室 https://yoziming.github.io/post/220131-gulimall-14-thread/ -<h1 id="多線程">多線程</h1>
<h2 id="初始化線程的4種方式">初始化線程的4種方式</h2>
<ol>
<li>繼承 Thread</li>
<li>實現 Runnable接口</li>
<li>實現 Callable接口 + FutureTask（可以拿到返回結果，可以處理異常）</li>
<li>線程池</li>
</ol>
<blockquote>
<p>複習 <a href="https://yoziming.github.io/post/211204-agg-ja-19/">https://yoziming.github.io/post/211204-agg-ja-19/</a></p>
</blockquote>
<h3 id="區別">區別</h3>
<ul>
<li>1、2不能得到返回值。3可以獲取返回值</li>
<li>1、2、3都不能控制資源</li>
<li>4可以控制資源，性能穩定，不會一下子所有線程一起運行</li>
<li>實際開發中，只用線程池，因為高併發狀態開啓了n個線程，會直接耗盡資源</li>
</ul>
<h2 id="線程池的優勢">線程池的優勢</h2>
<ul>
<li>降低資源的消耗: 省得在那創了又刪，刪了又創</li>
<li>提高響應速度: 已經在池子那等了，來活就幹</li>
<li>提高線程的可管理性: 例如系統中可以創建兩個線程池，核心線程池、非核心線程池，有需要時可以關閉非核心線程池釋放記憶體資源
<ul>
<li>就像公司分兩部門，壓力大就把非核心的部門關了</li>
</ul>
</li>
</ul>
<h2 id="手動創建線程池">手動創建線程池</h2>
<p><img src="image-20220124093616789.png" alt="image-20220124093616789"></p>
<ul>
<li>可以<code>new ThreadPoolExecutor(參數)</code>手動創建線程池，七大參數:</li>
</ul>
<pre tabindex="0"><code>// ThreadPoolExecutor.java 原始碼
corePoolSize – the number of threads to keep in the pool, even if they are idle, unless allowCoreThreadTimeOut is set
maximumPoolSize – the maximum number of threads to allow in the pool
keepAliveTime – when the number of threads is greater than the core, this is the maximum time that excess idle threads will wait for new tasks before terminating.
unit – the time unit for the keepAliveTime argument
workQueue – the queue to use for holding tasks before they are executed. This queue will hold only the Runnable tasks submitted by the execute method.
threadFactory – the factory to use when the executor creates a new thread
handler – the handler to use when execution is blocked because the thread bounds and queue capacities are reached
</code></pre><ul>
<li>corePoolSize: 元老級員工，即使摸魚也不會被解雇</li>
<li>maximumPoolSize: 最大招募數量，用於控制資源</li>
<li>keepAliveTime: 臨時員工摸魚多久就把他們解雇</li>
<li>unit: 計算摸魚時間的單位</li>
<li>workQueue: 阻塞隊列，任務太多暫時沒員工可分配了，新來的任務排隊的地方</li>
<li>threadFactory: 創建執行緒的工廠，給員工命名的人資</li>
<li>handler: 如果隊列滿了，執行指定的拒絕策略
<ul>
<li>RejectedExecutionHandler 有以下幾種</li>
<li>預設是AbortPolicy，跟客戶說公司幹不過來請他找別家</li>
<li>CallerRunsPolicy類似開小灶，硬幫你執行</li>
</ul>
</li>
</ul>
<p><img src="image-20220124090358219.png" alt="image-20220124090358219"></p>
<h3 id="順序">順序</h3>
<ul>
<li>創建線程池，懶加載核心線程(任務來了就招募核心員工)</li>
<li>核心線程滿放入阻塞隊列(員工不夠用，請任務先排隊，馬上招臨時工)</li>
<li>創建線程，直到達到maximumPoolSize</li>
<li>如果傳入了拒絕策略會執行，否則拋出異常</li>
</ul>
<h4 id="範例">範例</h4>
<ul>
<li>一個線程池 core = 7, max = 20, queue = 50 當100個併發進來</li>
<li>7個任務立即被核心執行，50個進隊列，然後創建13個線程執行13個任務。剩下30個執行拒絕策略</li>
</ul>
<h3 id="線程池execute和submit區別">線程池execute和submit區別</h3>
<ul>
<li>execute: 參數只能是Runnable，沒有返回值</li>
<li>submit: 參數可以是Runnable、Callable，返回值是FutureTask</li>
</ul>
<h2 id="四種線程池模板">四種線程池模板</h2>
<p><img src="image-20220124093548225.png" alt="image-20220124093548225"></p>
<ul>
<li>CachedThreadPool: 核心線程數是0，如果空閒會回收所有線程。全員派遣公司，沒事幹就裁員</li>
<li>FixedThreadPool: 核心線程數 = 最大線程數。佛心公司，永不拋棄員工，但占用就多、不靈活</li>
<li>ScheduledThreadPool: 定時任務線程池，多久之後執行，可設定核心線程數、最大線程數是Integer.Max。限定營業時間的公司</li>
<li>SingleThreadPool: 核心與最大都只有一個，後台從隊列中獲取任務。個人接案公司，一件一件幹</li>
</ul>
<h1 id="completablefuture-異步編排">CompletableFuture 異步編排</h1>
<blockquote>
<p>就像為了做咖哩飯，白米在電鍋蒸，紅蘿蔔難熟提前丟去煮，我還能一邊切馬鈴薯。類似vue的Promise也是為了異步任務</p>
</blockquote>
<ul>
<li>因為要實現Runnable，所以幾乎都是用lambda表達式來縮寫，省得寫好幾行</li>
</ul>
<h2 id="指派任務">指派任務</h2>
<blockquote>
<p>把紅蘿蔔丟去鍋裡煮</p>
</blockquote>
<ul>
<li>CompletableFuture提供了四個靜態方法來創建一個異步操作</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> Completab1eFuture&lt;Void&gt; <span style="color:#008b45">runAsync</span>(Runnable runnable)
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> completableFuturecVoid&gt; <span style="color:#008b45">runAsync</span>(Runnable runnable<span style="color:#a61717;background-color:#e3d2d2">，</span>Executor executor)
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> &lt;U&gt; CompletableFuture&lt;U&gt; <span style="color:#008b45">supplyAsync</span>(Supplier&lt;U&gt;supplier)
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> &lt;U&gt; CompletableFuturecU&gt; <span style="color:#008b45">supplyAsync</span>(Supplier&lt;U&gt; supplier<span style="color:#a61717;background-color:#e3d2d2">，</span>Executor executor)
</code></pre></div><ul>
<li>可以傳入自定義線程池，否則使用預設線程池</li>
<li>runXXX沒有返回結果，supplyXxx有返回結果
<ul>
<li>用<code>future.get()</code>獲取結果</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">ThreadTest</span> {

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> ExecutorService executor = Executors.<span style="color:#658b00">newFixedThreadPool</span>(10);

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">main</span>(String[] args) <span style="color:#8b008b;font-weight:bold">throws</span> ExecutionException, InterruptedException {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main start ....&#34;</span>);
        CompletableFuture&lt;Integer&gt; future = CompletableFuture.<span style="color:#658b00">supplyAsync</span>(ThreadTest::asyncFunction, executor);
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main end.... result: &#34;</span> + future.<span style="color:#658b00">get</span>());
    }

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> <span style="color:#00688b;font-weight:bold">int</span> <span style="color:#008b45">asyncFunction</span>() {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;執行任務 1+1&#34;</span>);
        <span style="color:#8b008b;font-weight:bold">return</span> 1 + 1;
    }

}
</code></pre></div><h2 id="接收任務返回值">接收任務返回值</h2>
<blockquote>
<p>煮了紅蘿蔔之後要幹嘛</p>
</blockquote>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> completableFuture&lt;T&gt; <span style="color:#008b45">whencomplete</span>(BiConsumer&lt;? <span style="color:#8b008b;font-weight:bold">super</span> T, ? <span style="color:#8b008b;font-weight:bold">super</span> Throwable&gt; action);

<span style="color:#8b008b;font-weight:bold">public</span> completableFuture&lt;T&gt; <span style="color:#008b45">whenCompleteAsync</span>(BiConsumer&lt;? <span style="color:#8b008b;font-weight:bold">super</span> T, ? <span style="color:#8b008b;font-weight:bold">super</span> Throwable&gt; action<span style="color:#a61717;background-color:#e3d2d2">，</span>Executor executor);

<span style="color:#8b008b;font-weight:bold">public</span> completableFuture&lt;T&gt; <span style="color:#008b45">exceptionally</span>(Function&lt;Throwable, ? <span style="color:#8b008b;font-weight:bold">extends</span> T&gt; fn);
</code></pre></div><ul>
<li>whenComplete可以處理正常結果和感知異常，exceptionally特別用於處理異常情況</li>
<li>whenComplete和whenCompleteAsync的區別:
<ul>
<li>whenComplete: 是執行當前任務的線程執行繼續執行whenComplete的任務</li>
<li>whenCompleteAsync: 是執行把 whenCompleteAsync這個任務繼續提交給線程池來進行執行</li>
</ul>
</li>
<li>方法不以Async結尾，意味着Action使用相同的線程執行，而Async可能會使用其他線程執行（如果是使用相同的線程池，也可能會被同一個線程選中執行)
<ul>
<li>就是這個鍋煮完這批紅蘿蔔要不要換個鍋</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">ThreadTest</span> {

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> ExecutorService executor = Executors.<span style="color:#658b00">newFixedThreadPool</span>(10);

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">main</span>(String[] args) <span style="color:#8b008b;font-weight:bold">throws</span> ExecutionException, InterruptedException {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main start ...&#34;</span>);
        CompletableFuture&lt;String&gt; future = CompletableFuture
                .<span style="color:#658b00">supplyAsync</span>(ThreadTest::asyncFunction, executor)
                .<span style="color:#658b00">whenComplete</span>(ThreadTest::accept)
                .<span style="color:#658b00">exceptionally</span>(ThreadTest::apply);
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main end... 返回值：&#34;</span> + future.<span style="color:#658b00">get</span>());
    }

    <span style="color:#228b22">// 指派任務
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> String <span style="color:#008b45">asyncFunction</span>() {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;線程池執行任務 煮紅蘿蔔&#34;</span>);
        <span style="color:#00688b;font-weight:bold">int</span> i = 10 / 0; <span style="color:#228b22">// 讓異常發生
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;煮好了&#34;</span>;
    }

    <span style="color:#228b22">// 指派任務完成後要幹的事
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">accept</span>(String result, Throwable exception) {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;獲取任務1的結果：&#34;</span> + result);
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;獲取任務1的異常：&#34;</span> + exception);
    }

    <span style="color:#228b22">// 異常時要返回的
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> String <span style="color:#008b45">apply</span>(Throwable exception) {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;紅蘿蔔異常&#34;</span> + exception);
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;紅蘿蔔沒熟需要重煮&#34;</span>;
    }
}
</code></pre></div><h3 id="handle方法">handle方法</h3>
<p>whenComplete只能感知異常，他只能跟你說結果沒熟，但是不能對沒熟的紅蘿蔔怎樣，太弱了所以通常不用。通常是用handle</p>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">ThreadTest</span> {

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> ExecutorService executor = Executors.<span style="color:#658b00">newFixedThreadPool</span>(10);

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">main</span>(String[] args) <span style="color:#8b008b;font-weight:bold">throws</span> ExecutionException, InterruptedException {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main start ...&#34;</span>);
        CompletableFuture&lt;String&gt; future = CompletableFuture
                .<span style="color:#658b00">supplyAsync</span>(ThreadTest::asyncFunction, executor)
                .<span style="color:#658b00">whenComplete</span>(ThreadTest::accept)
                .<span style="color:#658b00">exceptionally</span>(ThreadTest::apply)
                .<span style="color:#658b00">handle</span>(ThreadTest::handle);
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main end... 返回值：&#34;</span> + future.<span style="color:#658b00">get</span>());
    }

    <span style="color:#228b22">// 指派任務
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> String <span style="color:#008b45">asyncFunction</span>() {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;線程池執行任務 煮紅蘿蔔&#34;</span>);
        <span style="color:#00688b;font-weight:bold">int</span> i = 10 / 0; <span style="color:#228b22">// 讓異常發生
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;煮好了&#34;</span>;
    }

    <span style="color:#228b22">// 指派任務完成後要幹的事
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">accept</span>(String result, Throwable exception) {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;獲取任務1的結果：&#34;</span> + result);
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;獲取任務1的異常：&#34;</span> + exception);
    }

    <span style="color:#228b22">// 異常時要返回的
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> String <span style="color:#008b45">apply</span>(Throwable exception) {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;紅蘿蔔異常&#34;</span> + exception);
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;紅蘿蔔沒熟需要重煮&#34;</span>;
    }

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> String <span style="color:#008b45">handle</span>(String result, Throwable exception) {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;獲取任務1的結果：&#34;</span> + result);
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;獲取任務1的異常：&#34;</span> + exception);
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;異常不會傳播，前面調用exceptionally方法處理了異常&#34;</span>);
        <span style="color:#8b008b;font-weight:bold">return</span> result + <span style="color:#cd5555">&#34;，並且基於任務1的結果，把鍋裡的東西撈出來&#34;</span>;
    }
}
</code></pre></div><h2 id="串行化">串行化</h2>
<blockquote>
<p>handle是用於處理a方法的結果，接著執行b方法要用串行</p>
</blockquote>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> Completionstage&lt;Void&gt; <span style="color:#008b45">thenRun</span>(Runnable action);

<span style="color:#8b008b;font-weight:bold">public</span> completionstage&lt;Void&gt; <span style="color:#008b45">thenAccept</span>(Consumer&lt;? <span style="color:#8b008b;font-weight:bold">super</span> T&gt; action);

<span style="color:#8b008b;font-weight:bold">public</span> &lt;U&gt; CompletableFuturecU&gt; <span style="color:#008b45">thenApply</span>(Function&lt;? <span style="color:#8b008b;font-weight:bold">super</span> T,? <span style="color:#8b008b;font-weight:bold">extends</span> U&gt; fn)
</code></pre></div><ul>
<li>thenRun：繼續執行，不接受上一個任務的返回結果</li>
<li>thenAccept：繼續執行，接受上一個任務的返回結果</li>
<li>thenApply：繼續執行，接受上一任務的返回結果，並且自己有返回值</li>
<li>他們也都有Async版本，跟前面一樣就不多說</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">main</span>(String[] args) <span style="color:#8b008b;font-weight:bold">throws</span> ExecutionException, InterruptedException {
    System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main start ...&#34;</span>);
    CompletableFuture&lt;String&gt; future = CompletableFuture
            .<span style="color:#658b00">supplyAsync</span>(ThreadTest::asyncFunction, executor)
            .<span style="color:#658b00">whenComplete</span>(ThreadTest::accept)
            .<span style="color:#658b00">exceptionally</span>(ThreadTest::apply)
            .<span style="color:#658b00">handle</span>(ThreadTest::handle)
            .<span style="color:#658b00">thenApply</span>(ThreadTest::thenApply);
    System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main end... 返回值：&#34;</span> + future.<span style="color:#658b00">get</span>());
}

<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> String <span style="color:#008b45">thenApply</span>(String result) {
    System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務2啓動&#34;</span>);
    System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務2可以獲取任務1的結果：&#34;</span> + result);
    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;現在換煮馬鈴薯&#34;</span>;
}
</code></pre></div><h2 id="彙整任務">彙整任務</h2>
<blockquote>
<p>現在米飯、咖哩、紅蘿蔔、馬鈴薯都煮了，要來擺盤</p>
</blockquote>
<h3 id="兩個任務必須都完成">兩個任務必須都完成</h3>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> &lt;U,V&gt; CompletableFuture&lt;V&gt; <span style="color:#008b45">thenCombine</span>(CompletionStage&lt;? <span style="color:#8b008b;font-weight:bold">extends</span> U&gt; other, BiFunction&lt;? <span style="color:#8b008b;font-weight:bold">super</span> T,? <span style="color:#8b008b;font-weight:bold">super</span> U,? <span style="color:#8b008b;font-weight:bold">extends</span> V&gt; fn);

<span style="color:#8b008b;font-weight:bold">public</span> &lt;U&gt; CompletableFuture&lt;Void&gt; <span style="color:#008b45">thenAcceptBoth</span>(CompletionStage&lt;? <span style="color:#8b008b;font-weight:bold">extends</span> U&gt; other, BiConsumer&lt;? <span style="color:#8b008b;font-weight:bold">super</span> T, ? <span style="color:#8b008b;font-weight:bold">super</span> U&gt; action);

<span style="color:#8b008b;font-weight:bold">public</span> CompletableFuture&lt;Void&gt; <span style="color:#008b45">runAfterBoth</span>(CompletionStage&lt;?&gt; other, Runnable action);

</code></pre></div><ul>
<li>thenCombine: 獲取兩個future的返回結果，並返回當前任務的返回值</li>
<li>thenAcceptBoth: 獲取兩個future任務的返回結果，然後處理任務，沒有返回值</li>
<li>runAfterBoth: 不需要獲取future的結果，只需兩個future處理完任務後，處理該任務</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">main</span>(String[] args) <span style="color:#8b008b;font-weight:bold">throws</span> ExecutionException, InterruptedException {
    System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main start ...&#34;</span>);
    CompletableFuture&lt;String&gt; future1 = CompletableFuture.<span style="color:#658b00">supplyAsync</span>(() -&gt; {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務1 煮紅蘿蔔start..&#34;</span>);
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務1 end..&#34;</span>);
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;紅蘿蔔煮好了&#34;</span>;
    });

    CompletableFuture&lt;String&gt; future2 = CompletableFuture.<span style="color:#658b00">supplyAsync</span>(() -&gt; {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務2 煮馬鈴薯start..&#34;</span>);
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務2 end..&#34;</span>);
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;馬鈴薯煮好了&#34;</span>;
    });

    CompletableFuture&lt;String&gt; future3 = future1.<span style="color:#658b00">thenCombineAsync</span>(future2, (result1, result2) -&gt; {
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;任務3 組合前兩個任務的返回值返回: &#34;</span> + result1 + <span style="color:#cd5555">&#34;且&#34;</span> + result2;
    }, executor);
    System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main end... 返回值：&#34;</span> + future3.<span style="color:#658b00">get</span>());
}
</code></pre></div><h3 id="二者中有一個完成">二者中有一個完成</h3>
<blockquote>
<p>應該很少用到，了解就好</p>
</blockquote>
<ul>
<li>applyToEither: 帶參有返回值，能獲取前面任務的結果(成功的那個)，自己有返回結果</li>
<li>acceptEither: 帶參無返回值，能獲取前面任務的結果</li>
<li>runAfterEither: 無參無返回值，不能獲取前面任務的結果，自己也沒有返回結果(要你何用)</li>
</ul>
<h3 id="全完成或至少一個">全完成或至少一個</h3>
<ul>
<li>
<p>都是CompletableFuture的靜態方法</p>
<ul>
<li>
<p>allOf</p>
</li>
<li>
<p>anyOf</p>
</li>
</ul>
</li>
<li>
<p>配合<code>.get()</code>可以讓線程阻塞</p>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">ThreadTest</span> {

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> ExecutorService executor = Executors.<span style="color:#658b00">newFixedThreadPool</span>(10);

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">main</span>(String[] args) <span style="color:#8b008b;font-weight:bold">throws</span> ExecutionException, InterruptedException {
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main start ...&#34;</span>);
        CompletableFuture&lt;String&gt; future1 = CompletableFuture.<span style="color:#658b00">supplyAsync</span>(() -&gt; {
            System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務1 煮紅蘿蔔start..&#34;</span>);
            <span style="color:#8b008b;font-weight:bold">try</span> {
                Thread.<span style="color:#658b00">sleep</span>(3000);
            } <span style="color:#8b008b;font-weight:bold">catch</span> (InterruptedException e) {
                e.<span style="color:#658b00">printStackTrace</span>();
            }
            System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務1 end..&#34;</span>);
            <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;紅蘿蔔煮好了&#34;</span>;
        });

        CompletableFuture&lt;String&gt; future2 = CompletableFuture.<span style="color:#658b00">supplyAsync</span>(() -&gt; {
            System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務2 煮馬鈴薯start..&#34;</span>);
            System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務2 end..&#34;</span>);
            <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;馬鈴薯煮好了&#34;</span>;
        });

        CompletableFuture&lt;String&gt; future3 = future1.<span style="color:#658b00">thenCombineAsync</span>(future2, (result1, result2) -&gt; {
            System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務3 組合配菜，需要配菜都煮熟&#34;</span>);
            <span style="color:#8b008b;font-weight:bold">try</span> {
                Thread.<span style="color:#658b00">sleep</span>(3000);
            } <span style="color:#8b008b;font-weight:bold">catch</span> (InterruptedException e) {
                e.<span style="color:#658b00">printStackTrace</span>();
            }
            System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;任務3 end..&#34;</span>);
            <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;配菜完成&#34;</span>;
        }, executor);

        CompletableFuture&lt;Void&gt; all = CompletableFuture.<span style="color:#658b00">allOf</span>(future1, future2, future3);
        all.<span style="color:#658b00">get</span>(); <span style="color:#228b22">// 使方法阻塞，不阻塞若有人超時，主線程會提前關閉
</span><span style="color:#228b22"></span>        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(future1.<span style="color:#658b00">get</span>() + future2.<span style="color:#658b00">get</span>() + future3.<span style="color:#658b00">get</span>());
        System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(<span style="color:#cd5555">&#34;main end...&#34;</span>);
    }
}
</code></pre></div><h1 id="小結">小結</h1>
<ul>
<li>實際都用線程池，省資源、反應快、好控制</li>
<li>線程池七參數:
<ul>
<li>core: 核心員工，創了就不滅</li>
<li>max: 最大員工數量(含臨時工)</li>
<li>factory: 工廠，人資</li>
<li>aliveTime: 臨時工過期時間</li>
<li>unit: 過期時間單位</li>
<li>queue: 任務排隊處</li>
<li>handler: 拒絕策略</li>
</ul>
</li>
<li>併發進來，核心接活、去排隊、擴大池子臨時工接活直到max，超出的依照拒絕策略辦事</li>
<li>CompletableFuture:
<ul>
<li>Accept就是純接收結果</li>
<li>Apply是接收結果，且自己也有結果</li>
<li>Run就是不管上一個結果，現在做這件事</li>
<li><code>get()</code>方法可以讓線程阻塞</li>
</ul>
</li>
</ul>
