</span><span style="color:#228b22">     */</span>
    <span style="color:#8b008b;font-weight:bold">private</span> String icon;
    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 可選值列表[用逗號分隔]
</span><span style="color:#228b22">     */</span>
    <span style="color:#8b008b;font-weight:bold">private</span> String valueSelect;
    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 屬性類型[0-銷售屬性，1-基本屬性，2-既是銷售屬性又是基本屬性]
</span><span style="color:#228b22">     */</span>
    <span style="color:#8b008b;font-weight:bold">private</span> Integer attrType;
    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 啟用狀態[0 - 禁用，1 - 啟用]
</span><span style="color:#228b22">     */</span>
    <span style="color:#8b008b;font-weight:bold">private</span> Long enable;
    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 所屬分類
</span><span style="color:#228b22">     */</span>
    <span style="color:#8b008b;font-weight:bold">private</span> Long catalogId;
    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 快速展示【是否展示在介紹上；0-否 1-是】，在sku中仍然可以調整
</span><span style="color:#228b22">     */</span>
    <span style="color:#8b008b;font-weight:bold">private</span> Integer showDesc;

    <span style="color:#8b008b;font-weight:bold">private</span> Long attrGroupId;

    <span style="color:#8b008b;font-weight:bold">private</span> String catalogName;

    <span style="color:#8b008b;font-weight:bold">private</span> String groupName;

    <span style="color:#8b008b;font-weight:bold">private</span> Long[] catalogPath;

}
</code></pre></div><h2 id="查詢">查詢</h2>
<blockquote>
<p>這一節真的太偏了，前後端不分的thymeleaf本身已經很少人用，ES查詢語句的編寫真的枯燥又無聊，暫時先複製貼上跳過</p>
</blockquote>
<ul>
<li>簡單整理一下流程:
<ul>
<li>造Vo封裝搜索條件與呈現的結果</li>
<li>先在ES根據搜索條件寫出DSL</li>
<li>將DSL編譯成Java語法</li>
<li>處理聚合</li>
<li>將結果封裝，推回給前端</li>
</ul>
</li>
<li>SearchController.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@GetMapping</span>(value = <span style="color:#cd5555">&#34;/list.html&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> String <span style="color:#008b45">listPage</span>(SearchParam param, Model model, HttpServletRequest request) {
    <span style="color:#228b22">// Spring自動將頁面提交過來的所有請求參數封裝成我們指定的SearchParam
</span><span style="color:#228b22"></span>    param.<span style="color:#658b00">set_queryString</span>(request.<span style="color:#658b00">getQueryString</span>());

    <span style="color:#228b22">// 根據傳遞來的頁面的查詢參數，去es中檢索商品
</span><span style="color:#228b22"></span>    SearchResult result = mallSearchService.<span style="color:#658b00">search</span>(param);
    <span style="color:#228b22">// 存到model
</span><span style="color:#228b22"></span>    model.<span style="color:#658b00">addAttribute</span>(<span style="color:#cd5555">&#34;result&#34;</span>, result);
    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;list&#34;</span>;
}
</code></pre></div><ul>
<li>MallSearchServiceImpl.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 在es檢索
</span><span style="color:#228b22"> *
</span><span style="color:#228b22"> * @param param 檢索的所有參數
</span><span style="color:#228b22"> * @return 返回的結果
</span><span style="color:#228b22"> */</span>
<span style="color:#8b008b;font-weight:bold">public</span> SearchResult <span style="color:#008b45">search</span>(SearchParam param) {
    SearchResult result = <span style="color:#8b008b;font-weight:bold">null</span>;
    <span style="color:#228b22">// 1、動態構建檢索需要的DSL語句
</span><span style="color:#228b22"></span>
    <span style="color:#228b22">// 1、準備檢索請求
</span><span style="color:#228b22"></span>    SearchRequest searchRequest = buildSearchRequest(param);
    <span style="color:#8b008b;font-weight:bold">try</span> {
        <span style="color:#228b22">// 2、執行檢索請求
</span><span style="color:#228b22"></span>        SearchResponse searchResponse = client.<span style="color:#658b00">search</span>(searchRequest, ElasticConfig.<span style="color:#658b00">COMMON_OPTIONS</span>);

        <span style="color:#228b22">// 3、分析響應數據，封裝成需要的格式
</span><span style="color:#228b22"></span>        result = buildSearchResponse(param, searchResponse);

    } <span style="color:#8b008b;font-weight:bold">catch</span> (IOException e) {
        e.<span style="color:#658b00">printStackTrace</span>();
    }
    <span style="color:#8b008b;font-weight:bold">return</span> result;
}

<span style="color:#8b008b;font-weight:bold">private</span> SearchRequest <span style="color:#008b45">buildSearchRequest</span>(SearchParam param) {
    <span style="color:#228b22">// 構建DSL語句對象
</span><span style="color:#228b22"></span>    SearchSourceBuilder sourceBuilder = <span style="color:#8b008b;font-weight:bold">new</span> SearchSourceBuilder();
    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 模糊匹配，過濾（按照屬性，分類，品牌，價格區間，庫存）
</span><span style="color:#228b22">     */</span>
    <span style="color:#228b22">// 1、構建bool - query
</span><span style="color:#228b22"></span>    BoolQueryBuilder boolQueryBuilder = QueryBuilders.<span style="color:#658b00">boolQuery</span>();

    <span style="color:#228b22">// 1.1、must【得分】
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// 分詞匹配skuTitle
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (!StringUtils.<span style="color:#658b00">isEmpty</span>(param.<span style="color:#658b00">getKeyword</span>())) {
        boolQueryBuilder.<span style="color:#658b00">must</span>(QueryBuilders.<span style="color:#658b00">matchQuery</span>(<span style="color:#cd5555">&#34;skuTitle&#34;</span>, param.<span style="color:#658b00">getKeyword</span>()));
    }

    <span style="color:#228b22">// 1.2、filter【無得分】
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// 三級分類
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (param.<span style="color:#658b00">getCatalog3Id</span>() != <span style="color:#8b008b;font-weight:bold">null</span>) {
        boolQueryBuilder.<span style="color:#658b00">filter</span>(QueryBuilders.<span style="color:#658b00">termQuery</span>(<span style="color:#cd5555">&#34;catalogId&#34;</span>, param.<span style="color:#658b00">getCatalog3Id</span>()));
    }

    <span style="color:#228b22">// 1.3、品牌
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (!CollectionUtils.<span style="color:#658b00">isEmpty</span>(param.<span style="color:#658b00">getBrandId</span>())) {
        boolQueryBuilder.<span style="color:#658b00">filter</span>(QueryBuilders.<span style="color:#658b00">termsQuery</span>(<span style="color:#cd5555">&#34;brandId&#34;</span>, param.<span style="color:#658b00">getBrandId</span>()));
    }

    <span style="color:#228b22">// 1.4、屬性
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (!CollectionUtils.<span style="color:#658b00">isEmpty</span>(param.<span style="color:#658b00">getAttrs</span>())) {
        <span style="color:#8b008b;font-weight:bold">for</span> (String attr : param.<span style="color:#658b00">getAttrs</span>()) {
            BoolQueryBuilder boolQuery = QueryBuilders.<span style="color:#658b00">boolQuery</span>();
            String[] s = attr.<span style="color:#658b00">split</span>(<span style="color:#cd5555">&#34;_&#34;</span>);
            String attrId = s[0];
            String[] attrValues = s[1].<span style="color:#658b00">split</span>(<span style="color:#cd5555">&#34;:&#34;</span>);
            <span style="color:#228b22">// must中的必須是同時滿足的，如果boolQuery不是內層的
</span><span style="color:#228b22"></span>            <span style="color:#228b22">// 那麼boolQuery會拼接多個must(attrs.attrId)，例如id = 6時，同時必須id = 7，沒有此attr
</span><span style="color:#228b22"></span>            boolQuery.<span style="color:#658b00">must</span>(QueryBuilders.<span style="color:#658b00">termQuery</span>(<span style="color:#cd5555">&#34;attrs.attrId&#34;</span>, attrId));
            boolQuery.<span style="color:#658b00">must</span>(QueryBuilders.<span style="color:#658b00">termsQuery</span>(<span style="color:#cd5555">&#34;attrs.attrValue&#34;</span>, attrValues));
            <span style="color:#228b22">// 每一個屬性都要生成一個嵌入式查詢
</span><span style="color:#228b22"></span>            <span style="color:#228b22">// 商品必須包含每一個 傳入的屬性
</span><span style="color:#228b22"></span>            NestedQueryBuilder nestedQuery = QueryBuilders.<span style="color:#658b00">nestedQuery</span>(<span style="color:#cd5555">&#34;attrs&#34;</span>, boolQuery, ScoreMode.<span style="color:#658b00">None</span>);
            boolQueryBuilder.<span style="color:#658b00">filter</span>(nestedQuery);
        }
    }

    <span style="color:#228b22">// 1.5、庫存
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (param.<span style="color:#658b00">getHasStock</span>() != <span style="color:#8b008b;font-weight:bold">null</span>) {
        boolQueryBuilder.<span style="color:#658b00">filter</span>(QueryBuilders.<span style="color:#658b00">termQuery</span>(<span style="color:#cd5555">&#34;hasStock&#34;</span>, param.<span style="color:#658b00">getHasStock</span>() == 1));
    }

    <span style="color:#228b22">// 1.6、價格區間 0_500  _500  500_
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (!StringUtils.<span style="color:#658b00">isEmpty</span>(param.<span style="color:#658b00">getSkuPrice</span>())) {
        RangeQueryBuilder rangeQuery = QueryBuilders.<span style="color:#658b00">rangeQuery</span>(<span style="color:#cd5555">&#34;skuPrice&#34;</span>);
        String[] s = param.<span style="color:#658b00">getSkuPrice</span>().<span style="color:#658b00">split</span>(<span style="color:#cd5555">&#34;_&#34;</span>);
        <span style="color:#8b008b;font-weight:bold">if</span> (s.<span style="color:#658b00">length</span> == 2) {
            rangeQuery.<span style="color:#658b00">gte</span>(s[0]).<span style="color:#658b00">lte</span>(s[1]);
        } <span style="color:#8b008b;font-weight:bold">else</span> <span style="color:#8b008b;font-weight:bold">if</span> (s.<span style="color:#658b00">length</span> == 1) {
            <span style="color:#8b008b;font-weight:bold">if</span> (param.<span style="color:#658b00">getSkuPrice</span>().<span style="color:#658b00">startsWith</span>(<span style="color:#cd5555">&#34;_&#34;</span>)) {
                rangeQuery.<span style="color:#658b00">lte</span>(s[0]);
            }
            <span style="color:#8b008b;font-weight:bold">if</span> (param.<span style="color:#658b00">getSkuPrice</span>().<span style="color:#658b00">endsWith</span>(<span style="color:#cd5555">&#34;_&#34;</span>)) {
                rangeQuery.<span style="color:#658b00">gte</span>(s[0]);
            }
        }
        boolQueryBuilder.<span style="color:#658b00">filter</span>(rangeQuery);
    }

    <span style="color:#228b22">// 1、END 封裝查詢條件
</span><span style="color:#228b22"></span>    sourceBuilder.<span style="color:#658b00">query</span>(boolQueryBuilder);

    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 排序，分頁，高亮
</span><span style="color:#228b22">     */</span>
    <span style="color:#228b22">// 2.1、排序
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (!StringUtils.<span style="color:#658b00">isEmpty</span>(param.<span style="color:#658b00">getSort</span>())) {
        String[] s = param.<span style="color:#658b00">getSort</span>().<span style="color:#658b00">split</span>(<span style="color:#cd5555">&#34;_&#34;</span>);
        SortOrder order = s[1].<span style="color:#658b00">equalsIgnoreCase</span>(<span style="color:#cd5555">&#34;asc&#34;</span>) ? SortOrder.<span style="color:#658b00">ASC</span> : SortOrder.<span style="color:#658b00">DESC</span>;
        sourceBuilder.<span style="color:#658b00">sort</span>(s[0], order);
    }

    <span style="color:#228b22">// 2.2、分頁
</span><span style="color:#228b22"></span>    sourceBuilder.<span style="color:#658b00">from</span>((param.<span style="color:#658b00">getPageNum</span>() - 1) * EsConstant.<span style="color:#658b00">PRODUCT_PAGESIZE</span>);
    sourceBuilder.<span style="color:#658b00">size</span>(EsConstant.<span style="color:#658b00">PRODUCT_PAGESIZE</span>);

    <span style="color:#228b22">// 2.3、高亮
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (!StringUtils.<span style="color:#658b00">isEmpty</span>(param.<span style="color:#658b00">getKeyword</span>())) {
        HighlightBuilder highlightBuilder = <span style="color:#8b008b;font-weight:bold">new</span> HighlightBuilder();
        highlightBuilder.<span style="color:#658b00">field</span>(<span style="color:#cd5555">&#34;skuTitle&#34;</span>);
        highlightBuilder.<span style="color:#658b00">preTags</span>(<span style="color:#cd5555">&#34;&lt;b style=&#39;color:red&#39;&gt;&#34;</span>);
        highlightBuilder.<span style="color:#658b00">postTags</span>(<span style="color:#cd5555">&#34;&lt;/b&gt;&#34;</span>);
        sourceBuilder.<span style="color:#658b00">highlighter</span>(highlightBuilder);
    }

    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 聚合分析【品牌、分類、分析所有可選的規格】
</span><span style="color:#228b22">     */</span>
    <span style="color:#228b22">// 3.1、品牌聚合
</span><span style="color:#228b22"></span>    TermsAggregationBuilder brand_agg = AggregationBuilders.<span style="color:#658b00">terms</span>(<span style="color:#cd5555">&#34;brand_agg&#34;</span>).<span style="color:#658b00">field</span>(<span style="color:#cd5555">&#34;brandId&#34;</span>).<span style="color:#658b00">size</span>(10);
    <span style="color:#228b22">// 子聚合，獲得品牌name和圖片
</span><span style="color:#228b22"></span>    brand_agg.<span style="color:#658b00">subAggregation</span>(AggregationBuilders.<span style="color:#658b00">terms</span>(<span style="color:#cd5555">&#34;brand_name_agg&#34;</span>).<span style="color:#658b00">field</span>(<span style="color:#cd5555">&#34;brandName&#34;</span>).<span style="color:#658b00">size</span>(1));
    brand_agg.<span style="color:#658b00">subAggregation</span>(AggregationBuilders.<span style="color:#658b00">terms</span>(<span style="color:#cd5555">&#34;brand_img_agg&#34;</span>).<span style="color:#658b00">field</span>(<span style="color:#cd5555">&#34;brandImg&#34;</span>).<span style="color:#658b00">size</span>(1));
    <span style="color:#228b22">// 構建DSL
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// TODO 聚合品牌
</span><span style="color:#228b22"></span>    sourceBuilder.<span style="color:#658b00">aggregation</span>(brand_agg);

    <span style="color:#228b22">// 3.2、分類聚合
</span><span style="color:#228b22"></span>    TermsAggregationBuilder catalog_agg = AggregationBuilders.<span style="color:#658b00">terms</span>(<span style="color:#cd5555">&#34;catalog_agg&#34;</span>).<span style="color:#658b00">field</span>(<span style="color:#cd5555">&#34;catalogId&#34;</span>).<span style="color:#658b00">size</span>(20);
    <span style="color:#228b22">// 子聚合，獲得分類名
</span><span style="color:#228b22"></span>    catalog_agg.<span style="color:#658b00">subAggregation</span>(AggregationBuilders.<span style="color:#658b00">terms</span>(<span style="color:#cd5555">&#34;catalog_name_agg&#34;</span>).<span style="color:#658b00">field</span>(<span style="color:#cd5555">&#34;catalogName&#34;</span>).<span style="color:#658b00">size</span>(1));
    <span style="color:#228b22">// 構建DSL
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// TODO 聚合分類
</span><span style="color:#228b22"></span>    sourceBuilder.<span style="color:#658b00">aggregation</span>(catalog_agg);

    <span style="color:#228b22">// 3.3、規格聚合【嵌入式】
</span><span style="color:#228b22"></span>    NestedAggregationBuilder attr_agg = AggregationBuilders.<span style="color:#658b00">nested</span>(<span style="color:#cd5555">&#34;attr_agg&#34;</span>, <span style="color:#cd5555">&#34;attrs&#34;</span>);
    <span style="color:#228b22">// 根據id分組
</span><span style="color:#228b22"></span>    TermsAggregationBuilder attr_id_agg = AggregationBuilders.<span style="color:#658b00">terms</span>(<span style="color:#cd5555">&#34;attr_id_agg&#34;</span>).<span style="color:#658b00">field</span>(<span style="color:#cd5555">&#34;attrs.attrId&#34;</span>).<span style="color:#658b00">size</span>(10);
    <span style="color:#228b22">// 子聚合=》在id分組內部，繼續按照 attr_name分組
</span><span style="color:#228b22"></span>    attr_id_agg.<span style="color:#658b00">subAggregation</span>(AggregationBuilders.<span style="color:#658b00">terms</span>(<span style="color:#cd5555">&#34;attr_name_agg&#34;</span>).<span style="color:#658b00">field</span>(<span style="color:#cd5555">&#34;attrs.attrName&#34;</span>).<span style="color:#658b00">size</span>(1));
    <span style="color:#228b22">// 子聚合=》在id分組內部，繼續按照 attr_value分組
</span><span style="color:#228b22"></span>    attr_id_agg.<span style="color:#658b00">subAggregation</span>(AggregationBuilders.<span style="color:#658b00">terms</span>(<span style="color:#cd5555">&#34;attr_value_agg&#34;</span>).<span style="color:#658b00">field</span>(<span style="color:#cd5555">&#34;attrs.attrValue&#34;</span>).<span style="color:#658b00">size</span>(50));
    <span style="color:#228b22">// 嵌入式聚合
</span><span style="color:#228b22"></span>    attr_agg.<span style="color:#658b00">subAggregation</span>(attr_id_agg);
    <span style="color:#228b22">// 構建DSL
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// TODO 聚合屬性規格
</span><span style="color:#228b22"></span>    sourceBuilder.<span style="color:#658b00">aggregation</span>(attr_agg);

    SearchRequest searchRequest = <span style="color:#8b008b;font-weight:bold">new</span> SearchRequest(<span style="color:#8b008b;font-weight:bold">new</span> String[]{EsConstant.<span style="color:#658b00">PRODUCT_INDEX</span>}, sourceBuilder);

    <span style="color:#228b22">// 打印DSL
</span><span style="color:#228b22"></span>    System.<span style="color:#658b00">out</span>.<span style="color:#658b00">println</span>(sourceBuilder.<span style="color:#658b00">toString</span>());
    <span style="color:#8b008b;font-weight:bold">return</span> searchRequest;
}

<span style="color:#228b22">/**
</span><span style="color:#228b22"> * 封裝檢索結果
</span><span style="color:#228b22"> * 1、返回所有查詢到的商品
</span><span style="color:#228b22"> * 2、當前所有商品涉及到的所有屬性信息
</span><span style="color:#228b22"> * 3、當前所有商品涉及到的所有品牌信息
</span><span style="color:#228b22"> * 4、當前所有商品涉及到的所有分類信息
</span><span style="color:#228b22"> * 5、分頁信息   pageNum:當前頁碼  total:總記錄數    totalPages: 總頁碼
</span><span style="color:#228b22"> */</span>
<span style="color:#8b008b;font-weight:bold">private</span> SearchResult <span style="color:#008b45">buildSearchResponse</span>(SearchParam param, SearchResponse searchResponse) {
    SearchResult result = <span style="color:#8b008b;font-weight:bold">new</span> SearchResult();
    SearchHits hits = searchResponse.<span style="color:#658b00">getHits</span>();
    <span style="color:#228b22">// 1、返回所有查詢到的商品
</span><span style="color:#228b22"></span>    List&lt;SkuEsModel&gt; products = <span style="color:#8b008b;font-weight:bold">new</span> ArrayList&lt;&gt;();
    <span style="color:#8b008b;font-weight:bold">if</span> (!ArrayUtils.<span style="color:#658b00">isEmpty</span>(hits.<span style="color:#658b00">getHits</span>())) {
        <span style="color:#8b008b;font-weight:bold">for</span> (SearchHit hit : hits.<span style="color:#658b00">getHits</span>()) {
            String jsonStr = hit.<span style="color:#658b00">getSourceAsString</span>();
            SkuEsModel model = JSON.<span style="color:#658b00">parseObject</span>(jsonStr, SkuEsModel.<span style="color:#658b00">class</span>);
            <span style="color:#228b22">// 設置高亮信息
</span><span style="color:#228b22"></span>            <span style="color:#8b008b;font-weight:bold">if</span> (!StringUtils.<span style="color:#658b00">isEmpty</span>(param.<span style="color:#658b00">getKeyword</span>())) {
                HighlightField skuTitle = hit.<span style="color:#658b00">getHighlightFields</span>().<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;skuTitle&#34;</span>);
                model.<span style="color:#658b00">setSkuTitle</span>(skuTitle.<span style="color:#658b00">getFragments</span>()[0].<span style="color:#658b00">string</span>());
            }
            products.<span style="color:#658b00">add</span>(model);
        }
    }
    result.<span style="color:#658b00">setProducts</span>(products);

    <span style="color:#228b22">// 2、當前所有商品涉及到的所有屬性信息
</span><span style="color:#228b22"></span>    List&lt;SearchResult.<span style="color:#658b00">AttrVo</span>&gt; attrVos = <span style="color:#8b008b;font-weight:bold">new</span> ArrayList&lt;&gt;();
    ParsedNested attr_agg = searchResponse.<span style="color:#658b00">getAggregations</span>().<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;attr_agg&#34;</span>);
    ParsedLongTerms attr_id_agg = attr_agg.<span style="color:#658b00">getAggregations</span>().<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;attr_id_agg&#34;</span>);
    List&lt;? <span style="color:#8b008b;font-weight:bold">extends</span> Terms.<span style="color:#658b00">Bucket</span>&gt; attrBuckets = attr_id_agg.<span style="color:#658b00">getBuckets</span>();
    <span style="color:#8b008b;font-weight:bold">for</span> (Terms.<span style="color:#658b00">Bucket</span> bucket : attrBuckets) {
        SearchResult.<span style="color:#658b00">AttrVo</span> attrVo = <span style="color:#8b008b;font-weight:bold">new</span> SearchResult.<span style="color:#658b00">AttrVo</span>();
        <span style="color:#228b22">// 提取屬性ID
</span><span style="color:#228b22"></span>        attrVo.<span style="color:#658b00">setAttrId</span>(bucket.<span style="color:#658b00">getKeyAsNumber</span>().<span style="color:#658b00">longValue</span>());
        <span style="color:#228b22">// 提取屬性名字
</span><span style="color:#228b22"></span>        ParsedStringTerms attr_name_agg = bucket.<span style="color:#658b00">getAggregations</span>().<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;attr_name_agg&#34;</span>);
        attrVo.<span style="color:#658b00">setAttrName</span>(attr_name_agg.<span style="color:#658b00">getBuckets</span>().<span style="color:#658b00">get</span>(0).<span style="color:#658b00">getKeyAsString</span>());
        <span style="color:#228b22">// 提取品牌圖片
</span><span style="color:#228b22"></span>        ParsedStringTerms attr_value_agg = bucket.<span style="color:#658b00">getAggregations</span>().<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;attr_value_agg&#34;</span>);
        List&lt;String&gt; attrValues = attr_value_agg.<span style="color:#658b00">getBuckets</span>().<span style="color:#658b00">stream</span>().<span style="color:#658b00">map</span>(item -&gt; {
            <span style="color:#8b008b;font-weight:bold">return</span> ((Terms.<span style="color:#658b00">Bucket</span>) item).<span style="color:#658b00">getKeyAsString</span>();
        }).<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toList</span>());
        attrVo.<span style="color:#658b00">setAttrValue</span>(attrValues);
        attrVos.<span style="color:#658b00">add</span>(attrVo);
    }
    result.<span style="color:#658b00">setAttrs</span>(attrVos);

    <span style="color:#228b22">// 3、當前所有商品涉及到的所有品牌信息
</span><span style="color:#228b22"></span>    List&lt;SearchResult.<span style="color:#658b00">BrandVo</span>&gt; brandVos = <span style="color:#8b008b;font-weight:bold">new</span> ArrayList&lt;&gt;();
    ParsedLongTerms brand_agg = searchResponse.<span style="color:#658b00">getAggregations</span>().<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;brand_agg&#34;</span>);
    List&lt;? <span style="color:#8b008b;font-weight:bold">extends</span> Terms.<span style="color:#658b00">Bucket</span>&gt; brandBuckets = brand_agg.<span style="color:#658b00">getBuckets</span>();
    <span style="color:#8b008b;font-weight:bold">for</span> (Terms.<span style="color:#658b00">Bucket</span> bucket : brandBuckets) {
        SearchResult.<span style="color:#658b00">BrandVo</span> brandVo = <span style="color:#8b008b;font-weight:bold">new</span> SearchResult.<span style="color:#658b00">BrandVo</span>();
        <span style="color:#228b22">// 提取品牌ID
</span><span style="color:#228b22"></span>        brandVo.<span style="color:#658b00">setBrandId</span>(bucket.<span style="color:#658b00">getKeyAsNumber</span>().<span style="color:#658b00">longValue</span>());
        <span style="color:#228b22">// 提取品牌名字
</span><span style="color:#228b22"></span>        ParsedStringTerms brand_name_agg = bucket.<span style="color:#658b00">getAggregations</span>().<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;brand_name_agg&#34;</span>);
        brandVo.<span style="color:#658b00">setBrandName</span>(brand_name_agg.<span style="color:#658b00">getBuckets</span>().<span style="color:#658b00">get</span>(0).<span style="color:#658b00">getKeyAsString</span>());
        <span style="color:#228b22">// 提取品牌圖片
</span><span style="color:#228b22"></span>        ParsedStringTerms brand_img_agg = bucket.<span style="color:#658b00">getAggregations</span>().<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;brand_img_agg&#34;</span>);
        brandVo.<span style="color:#658b00">setBrandImg</span>(brand_img_agg.<span style="color:#658b00">getBuckets</span>().<span style="color:#658b00">get</span>(0).<span style="color:#658b00">getKeyAsString</span>());
        brandVos.<span style="color:#658b00">add</span>(brandVo);
    }
    result.<span style="color:#658b00">setBrands</span>(brandVos);

    <span style="color:#228b22">// 4、當前所有商品涉及到的所有分類信息
</span><span style="color:#228b22"></span>    List&lt;SearchResult.<span style="color:#658b00">CatalogVo</span>&gt; catalogVos = <span style="color:#8b008b;font-weight:bold">new</span> ArrayList&lt;&gt;();
    ParsedLongTerms catalog_agg = searchResponse.<span style="color:#658b00">getAggregations</span>().<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;catalog_agg&#34;</span>);
    List&lt;? <span style="color:#8b008b;font-weight:bold">extends</span> Terms.<span style="color:#658b00">Bucket</span>&gt; catalogBuckets = catalog_agg.<span style="color:#658b00">getBuckets</span>();
    <span style="color:#8b008b;font-weight:bold">for</span> (Terms.<span style="color:#658b00">Bucket</span> bucket : catalogBuckets) {
        SearchResult.<span style="color:#658b00">CatalogVo</span> catalogVo = <span style="color:#8b008b;font-weight:bold">new</span> SearchResult.<span style="color:#658b00">CatalogVo</span>();
        <span style="color:#228b22">// 提取分類Id
</span><span style="color:#228b22"></span>        catalogVo.<span style="color:#658b00">setCatalogId</span>(Long.<span style="color:#658b00">parseLong</span>(bucket.<span style="color:#658b00">getKeyAsString</span>()));
        <span style="color:#228b22">// 提取分類名字
</span><span style="color:#228b22"></span>        ParsedStringTerms catalog_name_agg = bucket.<span style="color:#658b00">getAggregations</span>().<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;catalog_name_agg&#34;</span>);
        catalogVo.<span style="color:#658b00">setCatalogName</span>(catalog_name_agg.<span style="color:#658b00">getBuckets</span>().<span style="color:#658b00">get</span>(0).<span style="color:#658b00">getKeyAsString</span>());
        catalogVos.<span style="color:#658b00">add</span>(catalogVo);
    }
    result.<span style="color:#658b00">setCatalogs</span>(catalogVos);
    <span style="color:#228b22">// 5、分頁信息   pageNum:當前頁碼 、total:總記錄數 、totalPages: 總頁碼
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">long</span> total = hits.<span style="color:#658b00">getTotalHits</span>().<span style="color:#658b00">value</span>;
    <span style="color:#00688b;font-weight:bold">int</span> totalPages = (<span style="color:#00688b;font-weight:bold">int</span>) total % EsConstant.<span style="color:#658b00">PRODUCT_PAGESIZE</span> == 0 ? (<span style="color:#00688b;font-weight:bold">int</span>) total / EsConstant.<span style="color:#658b00">PRODUCT_PAGESIZE</span> :
            ((<span style="color:#00688b;font-weight:bold">int</span>) total / EsConstant.<span style="color:#658b00">PRODUCT_PAGESIZE</span> + 1);
    result.<span style="color:#658b00">setPageNum</span>(param.<span style="color:#658b00">getPageNum</span>());
    result.<span style="color:#658b00">setTotal</span>(total);
    result.<span style="color:#658b00">setTotalPages</span>(totalPages);

    <span style="color:#228b22">// 6、所有頁碼數
</span><span style="color:#228b22"></span>    List&lt;Integer&gt; pageNavs = <span style="color:#8b008b;font-weight:bold">new</span> ArrayList&lt;&gt;();
    <span style="color:#8b008b;font-weight:bold">for</span> (<span style="color:#00688b;font-weight:bold">int</span> i = 1; i &lt;= totalPages; i++) {
        pageNavs.<span style="color:#658b00">add</span>(i);
    }
    result.<span style="color:#658b00">setPageNavs</span>(pageNavs);

    <span style="color:#228b22">// 7、構建麵包屑導航功能
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (param.<span style="color:#658b00">getAttrs</span>() != <span style="color:#8b008b;font-weight:bold">null</span> &amp;&amp; param.<span style="color:#658b00">getAttrs</span>().<span style="color:#658b00">size</span>() &gt; 0) {
        List&lt;SearchResult.<span style="color:#658b00">NavVo</span>&gt; collect = param.<span style="color:#658b00">getAttrs</span>().<span style="color:#658b00">stream</span>().<span style="color:#658b00">map</span>(attr -&gt; {
            <span style="color:#228b22">//1、分析每一個attrs傳過來的參數值
</span><span style="color:#228b22"></span>            SearchResult.<span style="color:#658b00">NavVo</span> navVo = <span style="color:#8b008b;font-weight:bold">new</span> SearchResult.<span style="color:#658b00">NavVo</span>();
            <span style="color:#228b22">// attrs=2_5寸:6寸
</span><span style="color:#228b22"></span>            String[] s = attr.<span style="color:#658b00">split</span>(<span style="color:#cd5555">&#34;_&#34;</span>);
            navVo.<span style="color:#658b00">setNavValue</span>(s[1]);
            R r = productFeignService.<span style="color:#658b00">attrInfo</span>(Long.<span style="color:#658b00">parseLong</span>(s[0]));
            <span style="color:#228b22">// 根據請求構造麵包屑 規格屬性Id集合，這個集合包含的屬性規格不显示【前端會遍歷每個參數显示】
</span><span style="color:#228b22"></span>            result.<span style="color:#658b00">getAttrIds</span>().<span style="color:#658b00">add</span>(Long.<span style="color:#658b00">parseLong</span>(s[0]));
            <span style="color:#8b008b;font-weight:bold">if</span> (r.<span style="color:#658b00">getCode</span>() == 0) {
                AttrResponseVo data = r.<span style="color:#658b00">getData</span>(<span style="color:#cd5555">&#34;attr&#34;</span>, <span style="color:#8b008b;font-weight:bold">new</span> TypeReference&lt;AttrResponseVo&gt;() {
                });
                <span style="color:#228b22">// 設置屬性名
</span><span style="color:#228b22"></span>                navVo.<span style="color:#658b00">setNavName</span>(data.<span style="color:#658b00">getAttrName</span>());
            } <span style="color:#8b008b;font-weight:bold">else</span> {
                navVo.<span style="color:#658b00">setNavName</span>(s[0]);
            }

            <span style="color:#228b22">//2、取消了這個麵包屑以後，我們要跳轉到哪個地方，將請求的地址url裏面的當前置空
</span><span style="color:#228b22"></span>            <span style="color:#228b22">//拿到所有的查詢條件，去掉當前
</span><span style="color:#228b22"></span>            String replace = replaceQueryString(param, attr, <span style="color:#cd5555">&#34;attrs&#34;</span>);
            navVo.<span style="color:#658b00">setLink</span>(<span style="color:#cd5555">&#34;http://search.mall.com/list.html?&#34;</span> + replace);

            <span style="color:#8b008b;font-weight:bold">return</span> navVo;
        }).<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toList</span>());

        result.<span style="color:#658b00">setNavs</span>(collect);
    }

    <span style="color:#228b22">// 品牌、分類
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">if</span> (param.<span style="color:#658b00">getBrandId</span>() != <span style="color:#8b008b;font-weight:bold">null</span> &amp;&amp; param.<span style="color:#658b00">getBrandId</span>().<span style="color:#658b00">size</span>() &gt; 0) {
        List&lt;SearchResult.<span style="color:#658b00">NavVo</span>&gt; navs = result.<span style="color:#658b00">getNavs</span>();
        SearchResult.<span style="color:#658b00">NavVo</span> navVo = <span style="color:#8b008b;font-weight:bold">new</span> SearchResult.<span style="color:#658b00">NavVo</span>();
        navVo.<span style="color:#658b00">setNavName</span>(<span style="color:#cd5555">&#34;品牌&#34;</span>);
        <span style="color:#228b22">// TODO 遠程查詢所有品牌
</span><span style="color:#228b22"></span>        R r = productFeignService.<span style="color:#658b00">brandsInfo</span>(param.<span style="color:#658b00">getBrandId</span>());
        <span style="color:#8b008b;font-weight:bold">if</span> (r.<span style="color:#658b00">getCode</span>() == 0) {
            List&lt;BrandVo&gt; brand = r.<span style="color:#658b00">getData</span>(<span style="color:#cd5555">&#34;brand&#34;</span>, <span style="color:#8b008b;font-weight:bold">new</span> TypeReference&lt;List&lt;BrandVo&gt;&gt;() {
            });
            StringBuffer sb = <span style="color:#8b008b;font-weight:bold">new</span> StringBuffer();
            String replace = <span style="color:#cd5555">&#34;&#34;</span>;
            <span style="color:#8b008b;font-weight:bold">for</span> (BrandVo brandVo : brand) {
                sb.<span style="color:#658b00">append</span>(brandVo.<span style="color:#658b00">getName</span>() + <span style="color:#cd5555">&#34;;&#34;</span>);
                replace = replaceQueryString(param, brandVo.<span style="color:#658b00">getBrandId</span>() + <span style="color:#cd5555">&#34;&#34;</span>, <span style="color:#cd5555">&#34;brandId&#34;</span>);
            }
            navVo.<span style="color:#658b00">setNavValue</span>(sb.<span style="color:#658b00">toString</span>());
            navVo.<span style="color:#658b00">setLink</span>(<span style="color:#cd5555">&#34;http://search.mall.com/list.html?&#34;</span> + replace);
        }
        navs.<span style="color:#658b00">add</span>(navVo);
    }

    <span style="color:#228b22">// TODO 分類 麵包屑
</span><span style="color:#228b22"></span>
    <span style="color:#8b008b;font-weight:bold">return</span> result;
}

<span style="color:#8b008b;font-weight:bold">private</span> String <span style="color:#008b45">replaceQueryString</span>(SearchParam param, String value, String key) {
    String encode = <span style="color:#8b008b;font-weight:bold">null</span>;
    <span style="color:#8b008b;font-weight:bold">try</span> {
        encode = URLEncoder.<span style="color:#658b00">encode</span>(value, <span style="color:#cd5555">&#34;UTF-8&#34;</span>);
        encode = encode.<span style="color:#658b00">replace</span>(<span style="color:#cd5555">&#34;+&#34;</span>, <span style="color:#cd5555">&#34;%20&#34;</span>);  <span style="color:#228b22">//瀏覽器對空格的編碼和Java不一樣，差異化處理
</span><span style="color:#228b22"></span>    } <span style="color:#8b008b;font-weight:bold">catch</span> (UnsupportedEncodingException e) {
        e.<span style="color:#658b00">printStackTrace</span>();
    }
    <span style="color:#228b22">// 就是點了X之後，應該跳轉的地址
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// 這裏要判斷一下，attrs是不是第一個參數，因為第一個參數 沒有&amp;符號
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// TODO BUG，第一個參數不帶&amp;
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">return</span> param.<span style="color:#658b00">get_queryString</span>().<span style="color:#658b00">replace</span>(<span style="color:#cd5555">&#34;&amp;&#34;</span> + key + <span style="color:#cd5555">&#34;=&#34;</span> + encode, <span style="color:#cd5555">&#34;&#34;</span>);
}
</code></pre></div><h3 id="麵包屑導航">麵包屑導航</h3>
