<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java">    <span style="color:#707a7c">@Override</span>
    <span style="color:#8b008b;font-weight:bold">public</span> List&lt;SkuHasStockTo&gt; <span style="color:#008b45">getSkuHasStock</span>(List&lt;Long&gt; ids) {
        List&lt;SkuHasStockTo&gt; collect = ids.<span style="color:#658b00">stream</span>().<span style="color:#658b00">map</span>(e -&gt; {
            Long count = baseMapper.<span style="color:#658b00">getStock</span>(e);
            SkuHasStockTo to = <span style="color:#8b008b;font-weight:bold">new</span> SkuHasStockTo();
            to.<span style="color:#658b00">setSkuId</span>(e);
            to.<span style="color:#658b00">setHasStock</span>(count &gt; 0);
            <span style="color:#8b008b;font-weight:bold">return</span> to;
        }).<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toList</span>());
        <span style="color:#8b008b;font-weight:bold">return</span> collect;
    }
</code></pre></div><ul>
