<span style="color:#8b008b;font-weight:bold">public</span> R <span style="color:#008b45">productStatusUp</span>(<span style="color:#707a7c">@RequestBody</span> List&lt;SkuEsModel&gt; skuEsModels) {
    <span style="color:#00688b;font-weight:bold">boolean</span> status = <span style="color:#8b008b;font-weight:bold">false</span>;
    <span style="color:#8b008b;font-weight:bold">try</span> {
        status = productSaveService.<span style="color:#658b00">productStatusUp</span>(skuEsModels);
    } <span style="color:#8b008b;font-weight:bold">catch</span> (IOException e) {
