    } <span style="color:#8b008b;font-weight:bold">else</span> {
        <span style="color:#8b008b;font-weight:bold">return</span> R.<span style="color:#658b00">ok</span>();
    }
}
</code></pre></div><ul>
<li>ProductSaveServiceImpl.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">boolean</span> <span style="color:#008b45">productStatusUp</span>(List&lt;SkuEsModel&gt; skuEsModels) <span style="color:#8b008b;font-weight:bold">throws</span> IOException {
    <span style="color:#228b22">// 1.在ES中建立索引，建立mapping（doc/json/product-mapping.json）
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// 2.在ES中保存這些數據
</span><span style="color:#228b22"></span>    BulkRequest bulkRequest = <span style="color:#8b008b;font-weight:bold">new</span> BulkRequest();
    <span style="color:#8b008b;font-weight:bold">for</span> (SkuEsModel skuEsModel : skuEsModels) {
        <span style="color:#228b22">// 構造保存請求
</span><span style="color:#228b22"></span>        IndexRequest indexRequest = <span style="color:#8b008b;font-weight:bold">new</span> IndexRequest(EsConstant.<span style="color:#658b00">PRODUCT_INDEX</span>);
        <span style="color:#228b22">// ES中的ID就是SKUID
</span><span style="color:#228b22"></span>        indexRequest.<span style="color:#658b00">id</span>(skuEsModel.<span style="color:#658b00">getSkuId</span>().<span style="color:#658b00">toString</span>());
        String jsonString = JSONUtil.<span style="color:#658b00">toJsonStr</span>(skuEsModel);
        indexRequest.<span style="color:#658b00">source</span>(jsonString, XContentType.<span style="color:#658b00">JSON</span>);
        <span style="color:#228b22">// 批量保存
</span><span style="color:#228b22"></span>        bulkRequest.<span style="color:#658b00">add</span>(indexRequest);
    }
    BulkResponse bulk = esRestClient.<span style="color:#658b00">bulk</span>(bulkRequest, ElasticConfig.<span style="color:#658b00">COMMON_OPTIONS</span>);
    <span style="color:#228b22">// TODO 如果批量錯誤
</span><span style="color:#228b22"></span>    <span style="color:#00688b;font-weight:bold">boolean</span> hasFailures = bulk.<span style="color:#658b00">hasFailures</span>();
    <span style="color:#228b22">// 收集結果印到log
</span><span style="color:#228b22"></span>    List&lt;String&gt; collect = Arrays.<span style="color:#658b00">asList</span>(bulk.<span style="color:#658b00">getItems</span>()).<span style="color:#658b00">stream</span>().<span style="color:#658b00">map</span>(item -&gt; {
        <span style="color:#8b008b;font-weight:bold">return</span> item.<span style="color:#658b00">getId</span>();
    }).<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toList</span>());
    log.<span style="color:#658b00">info</span>(<span style="color:#cd5555">&#34;商品上架完成：{}&#34;</span>, collect);
    <span style="color:#8b008b;font-weight:bold">return</span> hasFailures;
}
</code></pre></div><ul>
<li>註冊到feign等待調用</li>
</ul>
<h3 id="記一個5小時的坑">記一個5小時的坑</h3>
<ul>
<li>這邊用到feign遠程調用，由於查庫存想一次查一批，所以傳了一個List過去，沒想到竟然是個悲劇的開端</li>
<li>因為傳遞時轉JSON會擦掉泛型，所以傳遞<code>List&lt;XXX&gt;</code>的時候，轉回來反序列化不注意就會出事</li>
<li>我天真的以為用castvar去接就好，接了也沒報錯，還能sout出東西，乍看沒啥不對勁</li>
<li>結果下面死活報錯</li>
</ul>
<pre tabindex="0"><code>java.lang.ClassCastException: java.util.LinkedHashMap cannot be cast to xxxx
</code></pre><ul>
<li>我就一直在找原因，原來強轉接到的List是假象，是**<code>LinkedHashMap</code>**假扮的，因為SpringMVC將Object轉json會變成key-value形式，而轉回來它也這麼覺得，所以是一個Map，害我試到懷疑人生，熬夜到天明，氣氣氣氣氣</li>
</ul>
<h4 id="解法">解法</h4>
<ul>
<li>老師在這邊對R封裝了一個方法
<ul>
<li>用的是<code>com.alibaba.fastjson</code>的包</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> R <span style="color:#008b45">setData</span>(Object data) {
    put(<span style="color:#cd5555">&#34;data&#34;</span>, data);
    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">this</span>;
}

<span style="color:#228b22">// 利用fastjson進行反序列化
</span><span style="color:#228b22"></span><span style="color:#8b008b;font-weight:bold">public</span> &lt;T&gt; T <span style="color:#008b45">getData</span>(TypeReference&lt;T&gt; typeReference) {
    Object data = get(<span style="color:#cd5555">&#34;data&#34;</span>);
    String jsonString = JSON.<span style="color:#658b00">toJSONString</span>(data);
    T t = JSON.<span style="color:#658b00">parseObject</span>(jsonString, typeReference);
    <span style="color:#8b008b;font-weight:bold">return</span> t;
}

<span style="color:#228b22">// 利用fastjson進行反序列化
</span><span style="color:#228b22"></span><span style="color:#8b008b;font-weight:bold">public</span> &lt;T&gt; T <span style="color:#008b45">getData</span>(String key, TypeReference&lt;T&gt; typeReference) {
    Object data = get(key);
    String jsonString = JSON.<span style="color:#658b00">toJSONString</span>(data);
    T t = JSON.<span style="color:#658b00">parseObject</span>(jsonString, typeReference);
    <span style="color:#8b008b;font-weight:bold">return</span> t;
}
</code></pre></div><ul>
<li>返回的時候把list裝進去了，WareSkuController.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java">List&lt;SkuHasStockTo&gt; list = wareSkuService.<span style="color:#658b00">getSkuHasStock</span>(ids);

<span style="color:#8b008b;font-weight:bold">return</span> R.<span style="color:#658b00">ok</span>().<span style="color:#658b00">setData</span>(list);
</code></pre></div><ul>
<li>最後接收的時候，用<code>TypeReference</code>去指定反序列化的List&lt;&gt;類型
<ul>
<li>後面的<code>() {}</code>因為它是一個匿名內部類，別漏了</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java">R skuHasStock = wareFeignService.<span style="color:#658b00">getSkuHasStock</span>(skuIdList);
TypeReference&lt;List&lt;SkuHasStockTo&gt;&gt; typeReference = <span style="color:#8b008b;font-weight:bold">new</span> TypeReference&lt;List&lt;SkuHasStockTo&gt;&gt;() {
};
<span style="color:#228b22">// 把查詢結果拿出來，裝到Map&lt;Long, Boolean&gt;
</span><span style="color:#228b22"></span>stockMap = skuHasStock.<span style="color:#658b00">getData</span>(typeReference).<span style="color:#658b00">stream</span>().<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toMap</span>(SkuHasStockTo::getSkuId,
SkuHasStockTo::getHasStock));
</code></pre></div><ul>
<li>參考 <a href="https://www.1ju.org/article/jackson-linkedhashmap-cannot-be-cast">https://www.1ju.org/article/jackson-linkedhashmap-cannot-be-cast</a></li>
</ul>
<h1 id="thymeleaf">Thymeleaf</h1>
<blockquote>
<p>模板引擎 = 做模板填入資源內容，引擎幫我生成HTML頁面</p>
</blockquote>
<p>Thymeleaf是一個XML/HTML5模板引擎，能夠應用轉換於模板檔案，以顯示應用程式產生的資料，簡單來說只要照它的規則寫好模板與靜態資源，就能快速做出能看的HTML頁面</p>
<ul>
<li>有點回到Javaweb的感覺，thymeleaf就像JSP的強化版，它能做到動靜分離，但是不能前後分離
<ul>
<li>優勢在於簡單，直觀(html直接就能看，相較於JSP要有網路服務捧著)、渲染快</li>
<li>不過現在幾乎都是前後端分離，這個技術比較少見了</li>
</ul>
</li>
</ul>
<h3 id="使用">使用</h3>
<ul>
<li>引依賴，版本號給父模組的spring-boot管</li>
</ul>
<pre tabindex="0"><code>&lt;dependency&gt;
&lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;
&lt;artifactId&gt;spring-boot-starter-thymeleaf&lt;/artifactId&gt;
&lt;/dependency&gt;
</code></pre><ul>
<li>放入靜態資源，這個黃色圖標就是classpath
<ul>
<li>靜態檔案放 <code>/src/java/resources/static</code></li>
<li>模板檔案放 <code>/src/java/resources/templates</code></li>
</ul>
</li>
</ul>
<p><img src="image-20220120161915473.png" alt="image-20220120161915473"></p>
<ul>
<li>首頁預設會在這些地方找</li>
</ul>
<pre tabindex="0"><code>classpath:/META-INF/resources/index.html 
classpath:/resources/index.html 
classpath:/static/index.html 
calsspath:/public/index.html 
</code></pre><ul>
<li>預設約定了Controller試圖跳轉中thymeleaf模板檔案的的字首</li>
</ul>
<pre tabindex="0"><code>spring.thymeleaf.prefix: /templates/ 
spring.thymeleaf.suffix: .html 
</code></pre><ul>
<li>application.properties先把cache關掉</li>
</ul>
<pre tabindex="0"><code>spring.thymeleaf.cache=false
</code></pre><ul>
<li>若出現不明原因頁面顯示不出來，對模組右鍵添加依賴勾選thymeleaf</li>
</ul>
<h3 id="小結">小結</h3>
<ul>
<li>最上面引入 <code>xmlns:th=&quot;http://www.thymeleaf.org&quot;</code></li>
<li>每個標籤都要有結束標籤不可省略</li>
<li>在link標籤引用css標籤內要增加此屬性<code>th:href=&quot;@{/vendor/bootstrap/css/bootstrap.min.css}&quot;</code></li>
<li>在src標籤引用javascript內要增加此屬性
<code>th:src=&quot;@{/vendor/bootstrap/js/bootstrap.min.js}&quot;</code></li>
<li>要告訴thymeleaf靜態資源在哪，可以在<code>application.properties</code>內指定</li>
</ul>
<pre tabindex="0"><code>spring.resources.static-locations=classpath:/static/
</code></pre><ul>
<li>以下開始分頁面製作</li>
</ul>
<h2 id="首頁">首頁</h2>
<ul>
<li>IndexController.java
<ul>
<li>前面說過Controller會自動給跳轉到模板的請求加上前後綴，所以想讓人訪問首頁只要簡單的送他一個getmapping就OK</li>
<li>把模版頁面都放在templates之下方便統一管理，首頁也不例外</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@GetMapping</span>(value = {<span style="color:#cd5555">&#34;/&#34;</span>, <span style="color:#cd5555">&#34;index.html&#34;</span>})
<span style="color:#8b008b;font-weight:bold">private</span> String <span style="color:#008b45">indexPage</span>(Model model) {
    <span style="color:#228b22">// 查出所有的一級分類
</span><span style="color:#228b22"></span>    List&lt;CategoryEntity&gt; categoryEntities = categoryService.<span style="color:#658b00">getLevel1Catalog</span>();
    model.<span style="color:#658b00">addAttribute</span>(<span style="color:#cd5555">&#34;categories&#34;</span>, categoryEntities);
    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#cd5555">&#34;index&#34;</span>;
}
</code></pre></div><ul>
<li>Model類，相當於這個頁面本身(感覺類似JSP的pagescope)
<ul>
<li>想要在訪問的同時獲取一些資源，並且用model.addAttribute存在裡面</li>
</ul>
</li>
<li>在html裡面用<code>th:each</code>把它遍歷取出</li>
</ul>
<pre tabindex="0"><code>&lt;li th:each=&quot;category : ${categories}&quot;&gt;
&lt;a href=&quot;#&quot; class=&quot;header_main_left_a&quot; th:attr=&quot;ctg-data = ${category.catId}&quot;&gt;&lt;b
th:text=&quot;${category.name}&quot;&gt;家用電器&lt;/b&gt;&lt;/a&gt;
&lt;/li&gt;
</code></pre><h3 id="商品分類表">商品分類表</h3>
<ul>
<li>複雜的Vo，類中有類，沒辦法它前端API就這樣要求
<ul>
<li><code>@AllArgsConstructor</code> 請lombok造一個全參構造器</li>
<li>然而重點是<code>@NoArgsConstructor</code>一定要補上，否則沒有空參構造器很多地方會出錯</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Data</span>
<span style="color:#707a7c">@AllArgsConstructor</span>
<span style="color:#707a7c">@NoArgsConstructor</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">Catalogs2Vo</span> {

    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 一級父分類的id
</span><span style="color:#228b22">     */</span>
    <span style="color:#8b008b;font-weight:bold">private</span> String catalog1Id;

    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 三級子分類
</span><span style="color:#228b22">     */</span>
    <span style="color:#8b008b;font-weight:bold">private</span> List&lt;Category3Vo&gt; catalog3List;
    <span style="color:#8b008b;font-weight:bold">private</span> String id;
    <span style="color:#8b008b;font-weight:bold">private</span> String name;

    <span style="color:#228b22">/**
</span><span style="color:#228b22">     * 三級分類vo
</span><span style="color:#228b22">     */</span>
    <span style="color:#707a7c">@Data</span>
    <span style="color:#707a7c">@AllArgsConstructor</span>
    <span style="color:#707a7c">@NoArgsConstructor</span>
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">static</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">Category3Vo</span> {

        <span style="color:#228b22">/**
</span><span style="color:#228b22">         * 父分類、二級分類id
</span><span style="color:#228b22">         */</span>
        <span style="color:#8b008b;font-weight:bold">private</span> String catalog2Id;
        <span style="color:#8b008b;font-weight:bold">private</span> String id;
        <span style="color:#8b008b;font-weight:bold">private</span> String name;
    }
}
</code></pre></div><ul>
<li>IndexController.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">/**
</span><span style="color:#228b22"> * 獲取所有分類，且二、三級分類以封裝好
</span><span style="color:#228b22"> *
</span><span style="color:#228b22"> * @return
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@GetMapping</span>(value = <span style="color:#cd5555">&#34;/index/catalog.json&#34;</span>)
<span style="color:#707a7c">@ResponseBody</span>
<span style="color:#8b008b;font-weight:bold">public</span> Map&lt;String, List&lt;Catalogs2Vo&gt;&gt; <span style="color:#008b45">getCatalogJson</span>() {
    <span style="color:#8b008b;font-weight:bold">return</span> categoryService.<span style="color:#658b00">getCatalogJson</span>();
}
</code></pre></div><ul>
<li>CategoryServiceImpl.java
<ul>
<li>這個真的超繞，我覺得應該跟之前後台獲取分類的寫的treelist整合一下，不過肚子太餓就先算了，想來技術債就這這樣累積的吧</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">// 獲取所有分類，且二、三級分類以封裝好
</span><span style="color:#228b22"></span><span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> Map&lt;String, List&lt;Catalogs2Vo&gt;&gt; <span style="color:#008b45">getCatalogJson</span>() {
    <span style="color:#228b22">// 性能優化：將數據庫的多次查詢變為一次
</span><span style="color:#228b22"></span>    List&lt;CategoryEntity&gt; selectList = <span style="color:#8b008b;font-weight:bold">this</span>.<span style="color:#658b00">baseMapper</span>.<span style="color:#658b00">selectList</span>(<span style="color:#8b008b;font-weight:bold">null</span>);

    <span style="color:#228b22">// 查出所有一級分類
</span><span style="color:#228b22"></span>    List&lt;CategoryEntity&gt; level1Categories = getLevel1Catalog();

    <span style="color:#228b22">// 封裝數據
</span><span style="color:#228b22"></span>    Map&lt;String, List&lt;Catalogs2Vo&gt;&gt; parentCid =
            level1Categories.<span style="color:#658b00">stream</span>().<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toMap</span>(k -&gt; k.<span style="color:#658b00">getCatId</span>().<span style="color:#658b00">toString</span>(), v -&gt; {
                <span style="color:#228b22">// 1、每一個的一級分類,查到這個一級分類的二級分類
</span><span style="color:#228b22"></span>                List&lt;CategoryEntity&gt; categoryEntities = getParentCid(selectList, v.<span style="color:#658b00">getCatId</span>());

                <span style="color:#228b22">// 2、封裝上面的結果
</span><span style="color:#228b22"></span>                List&lt;Catalogs2Vo&gt; catalogs2Vos = <span style="color:#8b008b;font-weight:bold">null</span>;
                <span style="color:#8b008b;font-weight:bold">if</span> (categoryEntities != <span style="color:#8b008b;font-weight:bold">null</span>) {
                    catalogs2Vos = categoryEntities.<span style="color:#658b00">stream</span>().<span style="color:#658b00">map</span>(l2 -&gt; {
                        Catalogs2Vo catalogs2Vo = <span style="color:#8b008b;font-weight:bold">new</span> Catalogs2Vo(v.<span style="color:#658b00">getCatId</span>().<span style="color:#658b00">toString</span>(), <span style="color:#8b008b;font-weight:bold">null</span>,
                                l2.<span style="color:#658b00">getCatId</span>().<span style="color:#658b00">toString</span>()
                                , l2.<span style="color:#658b00">getName</span>().<span style="color:#658b00">toString</span>());

                        <span style="color:#228b22">// 1、找當前二級分類的三級分類封裝成vo
</span><span style="color:#228b22"></span>                        List&lt;CategoryEntity&gt; level3Catelog = getParentCid(selectList, l2.<span style="color:#658b00">getCatId</span>());

                        <span style="color:#8b008b;font-weight:bold">if</span> (level3Catelog != <span style="color:#8b008b;font-weight:bold">null</span>) {
                            List&lt;Catalogs2Vo.<span style="color:#658b00">Category3Vo</span>&gt; category3Vos = level3Catelog.<span style="color:#658b00">stream</span>().<span style="color:#658b00">map</span>(l3 -&gt; {
                                <span style="color:#228b22">//2、封裝成指定格式
</span><span style="color:#228b22"></span>                                Catalogs2Vo.<span style="color:#658b00">Category3Vo</span> category3Vo =
                                        <span style="color:#8b008b;font-weight:bold">new</span> Catalogs2Vo.<span style="color:#658b00">Category3Vo</span>(l2.<span style="color:#658b00">getCatId</span>().<span style="color:#658b00">toString</span>(),
                                                l3.<span style="color:#658b00">getCatId</span>().<span style="color:#658b00">toString</span>(),
                                                l3.<span style="color:#658b00">getName</span>());

                                <span style="color:#8b008b;font-weight:bold">return</span> category3Vo;
                            }).<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toList</span>());
                            catalogs2Vo.<span style="color:#658b00">setCatalog3List</span>(category3Vos);
                        }
                        <span style="color:#8b008b;font-weight:bold">return</span> catalogs2Vo;
                    }).<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toList</span>());
                }
                <span style="color:#8b008b;font-weight:bold">return</span> catalogs2Vos;
            }));
    <span style="color:#8b008b;font-weight:bold">return</span> parentCid;
}

<span style="color:#8b008b;font-weight:bold">private</span> List&lt;CategoryEntity&gt; <span style="color:#008b45">getParentCid</span>(List&lt;CategoryEntity&gt; selectList, Long parentCid) {
    <span style="color:#8b008b;font-weight:bold">return</span> selectList.<span style="color:#658b00">stream</span>().<span style="color:#658b00">filter</span>(item -&gt; item.<span style="color:#658b00">getParentCid</span>().<span style="color:#658b00">equals</span>(parentCid)).<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toList</span>());
}
</code></pre></div><ul>
<li>前端頁面是一個JS，長這樣</li>
</ul>
<p><img src="image-20220120174709917.png" alt="image-20220120174709917"></p>
<ul>
<li>JS不想多研究了，總之成功實現跟隨選滑鼠指向的一級分類，顯示對應的下級
<ul>
<li>這玩意之後還會加到redis</li>
</ul>
</li>
</ul>
