柚子茶室 https://yoziming.github.io/post/220124-gulimall-07/ -<h1 id="商品屬性維護">商品屬性維護</h1>
<h2 id="spu檢索">spu檢索</h2>
<ul>
<li>一個快速找到API的方法
<ul>
<li>裝上插件<code>RestfulTool</code>，直接貼上文檔給的URL瞬間就能定位</li>
</ul>
</li>
</ul>
<p><img src="image-20220118092156668.png" alt="image-20220118092156668"></p>
<ul>
<li>SpuInfoServiceImpl.java
<ul>
<li>處理多條件模糊搜索</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> PageUtils <span style="color:#008b45">queryPageByKeyword</span>(Map&lt;String, Object&gt; params) {
<span style="color:#228b22">/*
</span><span style="color:#228b22">key: &#39;華為&#39;,//檢索關鍵字
</span><span style="color:#228b22">catelogId: 6,//三級分類id
</span><span style="color:#228b22">brandId: 1,//品牌id
</span><span style="color:#228b22">status: 0,//商品狀態
</span><span style="color:#228b22">*/</span>
    QueryWrapper&lt;SpuInfoEntity&gt; wrapper = <span style="color:#8b008b;font-weight:bold">new</span> QueryWrapper&lt;&gt;();
    String key = (String) params.<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;key&#34;</span>);
    <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isNotBlank</span>(key) &amp;&amp; !<span style="color:#cd5555">&#34;0&#34;</span>.<span style="color:#658b00">equalsIgnoreCase</span>(key)) {
        wrapper.<span style="color:#658b00">and</span>(w -&gt; {
            <span style="color:#228b22">// 模糊搜索為了怕蓋掉下面的所以用and，其實也能放最後就好
</span><span style="color:#228b22"></span>            <span style="color:#228b22">// 優先 NOT&gt;AND&gt;OR
</span><span style="color:#228b22"></span>            w.<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;id&#34;</span>, key).<span style="color:#658b00">or</span>().<span style="color:#658b00">like</span>(<span style="color:#cd5555">&#34;spu_name&#34;</span>, key);
        });
    }
    String status = (String) params.<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;status&#34;</span>);
    <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isNotBlank</span>(status)) {
        wrapper.<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;publish_status&#34;</span>, status);
    }
    String catelogId = (String) params.<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;catelogId&#34;</span>);
    <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isNotBlank</span>(catelogId) &amp;&amp; !<span style="color:#cd5555">&#34;0&#34;</span>.<span style="color:#658b00">equalsIgnoreCase</span>(catelogId)) {
        wrapper.<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;catalog_id&#34;</span>, catelogId);
    }
    String brandId = (String) params.<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;brandId&#34;</span>);
    <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isNotBlank</span>(brandId) &amp;&amp; !<span style="color:#cd5555">&#34;0&#34;</span>.<span style="color:#658b00">equalsIgnoreCase</span>(brandId)) {
        wrapper.<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;brand_id&#34;</span>, brandId);
    }

    IPage&lt;SpuInfoEntity&gt; page = <span style="color:#8b008b;font-weight:bold">this</span>.<span style="color:#658b00">page</span>(
            <span style="color:#8b008b;font-weight:bold">new</span> Query&lt;SpuInfoEntity&gt;().<span style="color:#658b00">getPage</span>(params), wrapper
    );
    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">new</span> PageUtils(page);
}
</code></pre></div><ul>
<li>指定時間日期格式，application.properties</li>
</ul>
<pre tabindex="0"><code>spring.jackson.date-format=yyyy-MM-dd HH:mm:ss
spring.jackson.time-zone=GMT+8
</code></pre><ul>
<li>另外發現一個小BUG，保存時沒指定status狀態竟然不是0自己修正一下
<ul>
<li>不對後來發現是因為Vo用long用接，結果原來他在資料庫與entity中是int所以對不上，BeanUtils對拷失敗</li>
<li>其實這就存在一個坑點，就是前端校驗做不好，傳來null就算了，如果傳來0或&quot;0&quot;就容易坑</li>
<li>我感覺當初設計代號碼就該直接避開0，就像HTTP錯誤代碼也沒見用0的，反正int能用到127</li>
<li>但是預設0有時候又挺方便的，還是看實際狀況吧</li>
</ul>
</li>
</ul>
<h3 id="獲取spu規格與修改">獲取spu規格與修改</h3>
<ul>
<li>AttrController.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">// 獲取spu規格
</span><span style="color:#228b22"></span><span style="color:#707a7c">@GetMapping</span>(<span style="color:#cd5555">&#34;/base/listforspu/{spuId}&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> R <span style="color:#008b45">baseAttrlistforspu</span>(<span style="color:#707a7c">@PathVariable</span>(<span style="color:#cd5555">&#34;spuId&#34;</span>) Long spuId) {
    List&lt;ProductAttrValueEntity&gt; entities = productAttrValueService.<span style="color:#658b00">baseAttrListforspu</span>(spuId);
    <span style="color:#8b008b;font-weight:bold">return</span> R.<span style="color:#658b00">ok</span>().<span style="color:#658b00">put</span>(<span style="color:#cd5555">&#34;data&#34;</span>, entities);
}

<span style="color:#228b22">// 修改spu
</span><span style="color:#228b22"></span><span style="color:#707a7c">@PostMapping</span>(<span style="color:#cd5555">&#34;/update/{spuId}&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> R <span style="color:#008b45">updateSpuAttr</span>(<span style="color:#707a7c">@PathVariable</span>(<span style="color:#cd5555">&#34;spuId&#34;</span>) Long spuId,
                       <span style="color:#707a7c">@RequestBody</span> List&lt;ProductAttrValueEntity&gt; entities) {
    productAttrValueService.<span style="color:#658b00">updateSpuAttr</span>(spuId, entities);
    <span style="color:#8b008b;font-weight:bold">return</span> R.<span style="color:#658b00">ok</span>();
}
</code></pre></div><ul>
<li>ProductAttrValueServiceImpl.java</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">// 獲取spu規格
</span><span style="color:#228b22"></span><span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> List&lt;ProductAttrValueEntity&gt; <span style="color:#008b45">baseAttrListforspu</span>(Long spuId) {
    List&lt;ProductAttrValueEntity&gt; attrValueEntityList = <span style="color:#8b008b;font-weight:bold">this</span>.<span style="color:#658b00">baseMapper</span>.<span style="color:#658b00">selectList</span>(
            <span style="color:#8b008b;font-weight:bold">new</span> QueryWrapper&lt;ProductAttrValueEntity&gt;().<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;spu_id&#34;</span>, spuId));
    <span style="color:#8b008b;font-weight:bold">return</span> attrValueEntityList;
}

<span style="color:#228b22">/**
</span><span style="color:#228b22"> * 修改商品規格
</span><span style="color:#228b22"> *
</span><span style="color:#228b22"> * @param spuId
</span><span style="color:#228b22"> * @param entities
</span><span style="color:#228b22"> */</span>
<span style="color:#707a7c">@Transactional</span>(rollbackFor = Exception.<span style="color:#658b00">class</span>)
<span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">updateSpuAttr</span>(Long spuId, List&lt;ProductAttrValueEntity&gt; entities) {
    <span style="color:#228b22">// 1、刪除spuId之前對應的所有屬性
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">this</span>.<span style="color:#658b00">baseMapper</span>.<span style="color:#658b00">delete</span>(<span style="color:#8b008b;font-weight:bold">new</span> QueryWrapper&lt;ProductAttrValueEntity&gt;().<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;spu_id&#34;</span>, spuId));

    <span style="color:#228b22">// 2、添加商品規格信息
</span><span style="color:#228b22"></span>    List&lt;ProductAttrValueEntity&gt; collect = entities.<span style="color:#658b00">stream</span>().<span style="color:#658b00">map</span>(item -&gt; {
        item.<span style="color:#658b00">setSpuId</span>(spuId);
        <span style="color:#8b008b;font-weight:bold">return</span> item;
    }).<span style="color:#658b00">collect</span>(Collectors.<span style="color:#658b00">toList</span>());

    <span style="color:#228b22">// 批量新增
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">this</span>.<span style="color:#658b00">saveBatch</span>(collect);
}
</code></pre></div><ul>
<li>前端又要補一個非空判斷，我感覺這是因為不同版本載入順序不同造成的BUG，暫且不深究</li>
</ul>
<p><img src="image-20220118170207649.png" alt="image-20220118170207649"></p>
<ul>
<li>另外還有一個小BUG就是多選的屬性，只賦予單個值，且該值不屬於管理的屬性(attr表中可選的values，會出現在下拉表單中)，就是說那個值是save的時候或修改時現加的。會導致它在前端頁面修改屬性時回顯失敗(但資料庫中表格欄位沒錯)</li>
</ul>
<h2 id="sku檢索">sku檢索</h2>
<ul>
<li>SkuInfoServiceImpl.java
<ul>
<li>大同小異，另外從網友那學到mybatisplus自帶的工具包<code>StringUtils.isNotBlank</code>比Spring的<code>!StringUtils.isEmpty</code>更好用</li>
<li>另外注意價格區間搜索，前端預設傳來是0要做判斷</li>
<li>我注意到傳來的參數都轉成String處理，而mybatisplus搜索時也是會自動把String轉成資料庫中的對應的格式</li>
<li>總之都用String乍看沒毛病</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> PageUtils <span style="color:#008b45">queryPageByKeyword</span>(Map&lt;String, Object&gt; params) {
    <span style="color:#228b22">// key: &#39;華為&#39;,//檢索關鍵字
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// catelogId: 0,
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// brandId: 0,
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// min: 0,
</span><span style="color:#228b22"></span>    <span style="color:#228b22">// max: 0
</span><span style="color:#228b22"></span>    QueryWrapper&lt;SkuInfoEntity&gt; wrapper = <span style="color:#8b008b;font-weight:bold">new</span> QueryWrapper&lt;&gt;();
    String key = (String) params.<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;key&#34;</span>);
    <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isNotBlank</span>(key) &amp;&amp; !<span style="color:#cd5555">&#34;0&#34;</span>.<span style="color:#658b00">equalsIgnoreCase</span>(key)) {
        wrapper.<span style="color:#658b00">and</span>(w -&gt; {
            <span style="color:#228b22">// 模糊搜索為了怕蓋掉下面的所以用and，其實也能放最後就好
</span><span style="color:#228b22"></span>            <span style="color:#228b22">// 優先 NOT&gt;AND&gt;OR
</span><span style="color:#228b22"></span>            w.<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;sku_id&#34;</span>, key).<span style="color:#658b00">or</span>().<span style="color:#658b00">like</span>(<span style="color:#cd5555">&#34;sku_name&#34;</span>, key);
        });
    }
    String catelogId = (String) params.<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;catelogId&#34;</span>);
    <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isNotBlank</span>(catelogId) &amp;&amp; !<span style="color:#cd5555">&#34;0&#34;</span>.<span style="color:#658b00">equalsIgnoreCase</span>(catelogId)) {
        wrapper.<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;catalog_id&#34;</span>, catelogId);
    }
    String brandId = (String) params.<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;brandId&#34;</span>);
    <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isNotBlank</span>(brandId) &amp;&amp; !<span style="color:#cd5555">&#34;0&#34;</span>.<span style="color:#658b00">equalsIgnoreCase</span>(brandId)) {
        wrapper.<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;brand_id&#34;</span>, brandId);
    }
    String min = (String) params.<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;min&#34;</span>);
    <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isNotBlank</span>(min) &amp;&amp; <span style="color:#8b008b;font-weight:bold">new</span> BigDecimal(min).<span style="color:#658b00">compareTo</span>(BigDecimal.<span style="color:#658b00">ZERO</span>) &gt; 0) {
        wrapper.<span style="color:#658b00">ge</span>(<span style="color:#cd5555">&#34;price&#34;</span>, min);
    }
    String max = (String) params.<span style="color:#658b00">get</span>(<span style="color:#cd5555">&#34;max&#34;</span>);
    <span style="color:#8b008b;font-weight:bold">if</span> (StringUtils.<span style="color:#658b00">isNotBlank</span>(max) &amp;&amp; <span style="color:#8b008b;font-weight:bold">new</span> BigDecimal(max).<span style="color:#658b00">compareTo</span>(BigDecimal.<span style="color:#658b00">ZERO</span>) &gt; 0) {
        wrapper.<span style="color:#658b00">le</span>(<span style="color:#cd5555">&#34;price&#34;</span>, max);
    }

    IPage&lt;SkuInfoEntity&gt; page = <span style="color:#8b008b;font-weight:bold">this</span>.<span style="color:#658b00">page</span>(<span style="color:#8b008b;font-weight:bold">new</span> Query&lt;SkuInfoEntity&gt;().<span style="color:#658b00">getPage</span>(params), wrapper);
    <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">new</span> PageUtils(page);
}
</code></pre></div><hr>
