<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java">    <span style="color:#707a7c">@ApiOperation</span>(<span style="color:#cd5555">&#34;上傳科室&#34;</span>)
    <span style="color:#707a7c">@PostMapping</span>(<span style="color:#cd5555">&#34;saveDepartment&#34;</span>)
    <span style="color:#8b008b;font-weight:bold">public</span> Result <span style="color:#008b45">saveDepartment</span>(HttpServletRequest request) {
