        <span style="color:#8b008b;font-weight:bold">return</span> departmentService.<span style="color:#658b00">save</span>(parameterMap) ? Result.<span style="color:#658b00">ok</span>() : Result.<span style="color:#658b00">build</span>(230, <span style="color:#cd5555">&#34;醫院科室編號已存在，修改請聯絡工程師&#34;</span>);
