<h3 id="後端-寫接口">後端-寫接口</h3>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">// DictController
</span><span style="color:#228b22"></span><span style="color:#707a7c">@Api</span>(value = <span style="color:#cd5555">&#34;數據字典&#34;</span>, tags = <span style="color:#cd5555">&#34;數據字典&#34;</span>)
<span style="color:#707a7c">@RestController</span>
<span style="color:#707a7c">@RequestMapping</span>(<span style="color:#cd5555">&#34;/admin/cmn/Dict&#34;</span>)
<span style="color:#707a7c">@CrossOrigin</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">DictController</span> {
    <span style="color:#707a7c">@Autowired</span>
    <span style="color:#8b008b;font-weight:bold">private</span> DictService dictService;

    <span style="color:#707a7c">@ApiOperation</span>(<span style="color:#cd5555">&#34;根據id查詢子數據列表&#34;</span>)
    <span style="color:#707a7c">@GetMapping</span>(<span style="color:#cd5555">&#34;getAllChildDictById/{id}&#34;</span>)
    <span style="color:#8b008b;font-weight:bold">public</span> Result <span style="color:#008b45">getAllChildDictById</span>(<span style="color:#707a7c">@PathVariable</span> Long id) {
        <span style="color:#8b008b;font-weight:bold">return</span> Result.<span style="color:#658b00">ok</span>(dictService.<span style="color:#658b00">getAllChildDictById</span>(id));

    }
}

<span style="color:#228b22">// DictServiceImpl
</span><span style="color:#228b22"></span><span style="color:#707a7c">@Service</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">DictServiceImpl</span> <span style="color:#8b008b;font-weight:bold">extends</span> ServiceImpl&lt;DictMapper, Dict&gt; <span style="color:#8b008b;font-weight:bold">implements</span> DictService {

    <span style="color:#228b22">// 判斷id下面是否還有子節點
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">private</span> <span style="color:#00688b;font-weight:bold">boolean</span> <span style="color:#008b45">hasChildren</span>(<span style="color:#00688b;font-weight:bold">long</span> id) {
        QueryWrapper&lt;Dict&gt; qw = <span style="color:#8b008b;font-weight:bold">new</span> QueryWrapper&lt;&gt;();
        <span style="color:#228b22">// 以自己為爸爸查兒子數量
</span><span style="color:#228b22"></span>        qw.<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;parent_id&#34;</span>, id);
        Integer count = baseMapper.<span style="color:#658b00">selectCount</span>(qw);
        <span style="color:#228b22">// 有就是true
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">return</span> count &gt; 0;
    }

    <span style="color:#228b22">// 根據id查詢子數據列表
</span><span style="color:#228b22"></span>    <span style="color:#707a7c">@Override</span>
    <span style="color:#8b008b;font-weight:bold">public</span> List&lt;Dict&gt; <span style="color:#008b45">getAllChildDictById</span>(Long id) {
        QueryWrapper&lt;Dict&gt; qw = <span style="color:#8b008b;font-weight:bold">new</span> QueryWrapper&lt;&gt;();
        <span style="color:#228b22">// 根據id查表中子id，所以找parent_id是傳入的id的
</span><span style="color:#228b22"></span>        qw.<span style="color:#658b00">eq</span>(<span style="color:#cd5555">&#34;parent_id&#34;</span>, id);
        List&lt;Dict&gt; dictList = baseMapper.<span style="color:#658b00">selectList</span>(qw);
        <span style="color:#228b22">// 給bean賦值，因為資料庫中沒記載是否有子節點
</span><span style="color:#228b22"></span>        <span style="color:#228b22">// 對應的是@TableField(exist = false)
</span><span style="color:#228b22"></span>        <span style="color:#8b008b;font-weight:bold">for</span> (Dict dict : dictList) {
            Long dictId = dict.<span style="color:#658b00">getId</span>();
            <span style="color:#00688b;font-weight:bold">boolean</span> b = <span style="color:#8b008b;font-weight:bold">this</span>.<span style="color:#658b00">hasChildren</span>(dictId);
            <span style="color:#228b22">// 這個this是當前類DictServiceImpl，調用自己的方法查
</span><span style="color:#228b22"></span>            <span style="color:#228b22">// 某個dictId是否有子節點，我用dict.has找半天有點昏頭
</span><span style="color:#228b22"></span>            dict.<span style="color:#658b00">setHasChildren</span>(b);
        }
        <span style="color:#8b008b;font-weight:bold">return</span> dictList;
    }

}
</code></pre></div><h3 id="前端">前端</h3>
<blockquote>
<p>一樣三步驟: 加路由、寫接口、造頁面</p>
</blockquote>
<h4 id="路由側邊欄">路由(側邊欄)</h4>
<ul>
<li><code>@/router/index.js</code>
<ul>
<li><code>path &amp; redirect</code>是自訂的側邊欄網址，與實際頁面無關</li>
<li><code>alwaysShow: true</code>讓單子項也顯示側邊欄</li>
<li>綁定實際存在的頁面是<code>component: () =&gt; import('@/views/dict/list'),</code></li>
<li>另外<code>children: [</code>的<code>[</code>不能刪除否則報錯</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-json" data-lang="json">  {
    <span style="color:#a61717;background-color:#e3d2d2">path:</span> <span style="color:#a61717;background-color:#e3d2d2">&#39;/cmn&#39;,</span>
    <span style="color:#a61717;background-color:#e3d2d2">component:</span> <span style="color:#a61717;background-color:#e3d2d2">Layout,</span>
    <span style="color:#a61717;background-color:#e3d2d2">redirect:</span> <span style="color:#a61717;background-color:#e3d2d2">&#39;/cmn/list&#39;,</span>
    <span style="color:#a61717;background-color:#e3d2d2">name:</span> <span style="color:#a61717;background-color:#e3d2d2">&#39;字典管理&#39;,</span>
    <span style="color:#a61717;background-color:#e3d2d2">alwaysShow:</span> <span style="color:#a61717;background-color:#e3d2d2">true,</span>
    <span style="color:#a61717;background-color:#e3d2d2">meta:</span> <span style="color:#a61717;background-color:#e3d2d2">{</span> <span style="color:#a61717;background-color:#e3d2d2">title:</span> <span style="color:#a61717;background-color:#e3d2d2">&#39;字典管理&#39;,</span> <span style="color:#a61717;background-color:#e3d2d2">icon:</span> <span style="color:#a61717;background-color:#e3d2d2">&#39;el-icon-s-help&#39;</span> }<span style="color:#a61717;background-color:#e3d2d2">,</span>
    <span style="color:#a61717;background-color:#e3d2d2">children:</span> [
      {
        <span style="color:#a61717;background-color:#e3d2d2">path:</span> <span style="color:#a61717;background-color:#e3d2d2">&#39;list&#39;,</span>
        <span style="color:#a61717;background-color:#e3d2d2">name:</span> <span style="color:#a61717;background-color:#e3d2d2">&#39;字典列表&#39;,</span>
        <span style="color:#a61717;background-color:#e3d2d2">component:</span> <span style="color:#a61717;background-color:#e3d2d2">()</span> <span style="color:#a61717;background-color:#e3d2d2">=&gt;</span> <span style="color:#a61717;background-color:#e3d2d2">import(&#39;@/views/dict/list&#39;),</span>
        <span style="color:#a61717;background-color:#e3d2d2">meta:</span> <span style="color:#a61717;background-color:#e3d2d2">{</span> <span style="color:#a61717;background-color:#e3d2d2">title:</span> <span style="color:#a61717;background-color:#e3d2d2">&#39;字典列表&#39;,</span> <span style="color:#a61717;background-color:#e3d2d2">icon:</span> <span style="color:#a61717;background-color:#e3d2d2">&#39;table&#39;</span> }
      <span style="color:#a61717;background-color:#e3d2d2">}</span>
    ]
  <span style="color:#a61717;background-color:#e3d2d2">},</span>
</code></pre></div><h4 id="接口">接口</h4>
<p><code>@/api/dict.js</code></p>
<pre tabindex="0"><code>import request from '@/utils/request'

export default {
  getAllChildDictById(id) {
    return request({
      // ES6特性，反引號包裹強化字串
      url: `http://localhost:8202/admin/cmn/dict/getAllChildDictById/${id}`,
      method: 'get'
    })
  }
}
</code></pre><h4 id="頁面">頁面</h4>
<p><code>@/views/dict/list.vue</code></p>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-html" data-lang="html">&lt;<span style="color:#8b008b;font-weight:bold">template</span>&gt;
  &lt;<span style="color:#8b008b;font-weight:bold">div</span> <span style="color:#658b00">class</span>=<span style="color:#cd5555">&#34;app-container&#34;</span>&gt;
    &lt;<span style="color:#8b008b;font-weight:bold">el-table</span>
      <span style="color:#658b00">:data</span>=<span style="color:#cd5555">&#34;list&#34;</span>
      <span style="color:#658b00">style</span>=<span style="color:#cd5555">&#34;width: 100%&#34;</span>
      <span style="color:#658b00">row-key</span>=<span style="color:#cd5555">&#34;id&#34;</span>
      <span style="color:#658b00">border</span>
      <span style="color:#658b00">lazy</span>
      <span style="color:#658b00">:load</span>=<span style="color:#cd5555">&#34;getChildrens&#34;</span>
      <span style="color:#658b00">:tree-props</span>=<span style="color:#cd5555">&#34;{ children: &#39;children&#39;, hasChildren: &#39;hasChildren&#39; }&#34;</span>
    &gt;
      &lt;<span style="color:#8b008b;font-weight:bold">el-table-column</span> <span style="color:#658b00">label</span>=<span style="color:#cd5555">&#34;名稱&#34;</span> <span style="color:#658b00">width</span>=<span style="color:#cd5555">&#34;230&#34;</span> <span style="color:#658b00">align</span>=<span style="color:#cd5555">&#34;left&#34;</span>&gt;
        &lt;<span style="color:#8b008b;font-weight:bold">template</span> <span style="color:#658b00">slot-scope</span>=<span style="color:#cd5555">&#34;scope&#34;</span>&gt;
          &lt;<span style="color:#8b008b;font-weight:bold">span</span>&gt;{{ scope.row.name }}&lt;/<span style="color:#8b008b;font-weight:bold">span</span>&gt;
        &lt;/<span style="color:#8b008b;font-weight:bold">template</span>&gt;
      &lt;/<span style="color:#8b008b;font-weight:bold">el-table-column</span>&gt;
      &lt;<span style="color:#8b008b;font-weight:bold">el-table-column</span> <span style="color:#658b00">label</span>=<span style="color:#cd5555">&#34;編碼&#34;</span> <span style="color:#658b00">width</span>=<span style="color:#cd5555">&#34;220&#34;</span>&gt;
        &lt;<span style="color:#8b008b;font-weight:bold">template</span> <span style="color:#658b00">slot-scope</span>=<span style="color:#cd5555">&#34;{ row }&#34;</span>&gt;
          {{ row.dictCode }}
        &lt;/<span style="color:#8b008b;font-weight:bold">template</span>&gt;
      &lt;/<span style="color:#8b008b;font-weight:bold">el-table-column</span>&gt;
      &lt;<span style="color:#8b008b;font-weight:bold">el-table-column</span> <span style="color:#658b00">label</span>=<span style="color:#cd5555">&#34;值&#34;</span> <span style="color:#658b00">width</span>=<span style="color:#cd5555">&#34;230&#34;</span> <span style="color:#658b00">align</span>=<span style="color:#cd5555">&#34;left&#34;</span>&gt;
        &lt;<span style="color:#8b008b;font-weight:bold">template</span> <span style="color:#658b00">slot-scope</span>=<span style="color:#cd5555">&#34;scope&#34;</span>&gt;
          &lt;<span style="color:#8b008b;font-weight:bold">span</span>&gt;{{ scope.row.value }}&lt;/<span style="color:#8b008b;font-weight:bold">span</span>&gt;
        &lt;/<span style="color:#8b008b;font-weight:bold">template</span>&gt;
      &lt;/<span style="color:#8b008b;font-weight:bold">el-table-column</span>&gt;

      &lt;<span style="color:#8b008b;font-weight:bold">el-table-column</span> <span style="color:#658b00">label</span>=<span style="color:#cd5555">&#34;創建時間&#34;</span> <span style="color:#658b00">align</span>=<span style="color:#cd5555">&#34;center&#34;</span>&gt;
        &lt;<span style="color:#8b008b;font-weight:bold">template</span> <span style="color:#658b00">slot-scope</span>=<span style="color:#cd5555">&#34;scope&#34;</span>&gt;
          &lt;<span style="color:#8b008b;font-weight:bold">span</span>&gt;{{ scope.row.createTime }}&lt;/<span style="color:#8b008b;font-weight:bold">span</span>&gt;
        &lt;/<span style="color:#8b008b;font-weight:bold">template</span>&gt;
      &lt;/<span style="color:#8b008b;font-weight:bold">el-table-column</span>&gt;
    &lt;/<span style="color:#8b008b;font-weight:bold">el-table</span>&gt;
  &lt;/<span style="color:#8b008b;font-weight:bold">div</span>&gt;
&lt;/<span style="color:#8b008b;font-weight:bold">template</span>&gt;

&lt;<span style="color:#8b008b;font-weight:bold">script</span>&gt;
<span style="color:#228b22">// 引入接口的js
</span><span style="color:#228b22"></span><span style="color:#8b008b;font-weight:bold">import</span> dict from <span style="color:#cd5555">&#34;@/api/dict&#34;</span>;
<span style="color:#8b008b;font-weight:bold">export</span> <span style="color:#8b008b;font-weight:bold">default</span> {
  <span style="color:#228b22">// 定義接收用的變量與初始值
</span><span style="color:#228b22"></span>  data() {
    <span style="color:#8b008b;font-weight:bold">return</span> {
      list: [],
    };
  },
  created() {
    <span style="color:#8b008b;font-weight:bold">this</span>.getList(<span style="color:#b452cd">1</span>);
  },
  methods: {
    getList(id) {
      <span style="color:#228b22">// 發送axaj請求
</span><span style="color:#228b22"></span>      dict
        .getAllChildDictById(id)
        .then((response) =&gt; {
          <span style="color:#228b22">// 請求成功，取出回應資料
</span><span style="color:#228b22"></span>          <span style="color:#8b008b;font-weight:bold">this</span>.list = response.data;
        })
        <span style="color:#228b22">// 請求失敗
</span><span style="color:#228b22"></span>        .<span style="color:#8b008b;font-weight:bold">catch</span>((error) =&gt; {
          console.log(error);
        });
    },
    getChildrens(tree, treeNode, resolve) {
      dict.getAllChildDictById(tree.id).then((response) =&gt; {
        resolve(response.data);
      });
    },
  },
};
&lt;/<span style="color:#8b008b;font-weight:bold">script</span>&gt;
&lt;<span style="color:#8b008b;font-weight:bold">style</span>&gt;
&lt;/<span style="color:#8b008b;font-weight:bold">style</span>&gt;
</code></pre></div><ul>
<li>引用的是&quot;树形数据与懒加载&quot;
<ul>
<li><a href="https://element.eleme.io/#/zh-CN/component/table#shu-xing-shu-ju-yu-lan-jia-zai">https://element.eleme.io/#/zh-CN/component/table#shu-xing-shu-ju-yu-lan-jia-zai</a></li>
</ul>
</li>
<li>注意下面方法需要實現<code>getChildrens</code>，並且以id作為依據</li>
<li>另外axios的ajax請求已經封裝過，<code>response.data</code>就是通常意義的那層了，不要再寫成<code>.data.data</code>坑到自己</li>
</ul>
<hr>
<h2 id="導出列表">導出列表</h2>
<blockquote>
<p>讓使用者下載整個列表</p>
</blockquote>
<ul>
<li>需要引用easyExcel依賴，由於依賴管理已經宣告過，這邊不用寫版本號</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-xml" data-lang="xml">        <span style="color:#8b008b;font-weight:bold">&lt;dependency&gt;</span>
            <span style="color:#8b008b;font-weight:bold">&lt;groupId&gt;</span>com.alibaba<span style="color:#8b008b;font-weight:bold">&lt;/groupId&gt;</span>
            <span style="color:#8b008b;font-weight:bold">&lt;artifactId&gt;</span>easyexcel<span style="color:#8b008b;font-weight:bold">&lt;/artifactId&gt;</span>
            <span style="color:#8b008b;font-weight:bold">&lt;scope&gt;</span>provided<span style="color:#8b008b;font-weight:bold">&lt;/scope&gt;</span>
        <span style="color:#8b008b;font-weight:bold">&lt;/dependency&gt;</span>
</code></pre></div><ul>
<li>先造一個Vo實體類，屬性名跟原來的bean一樣，然後用<code>@ExcelProperty</code>註解宣告欄位</li>
<li>當然實際操作的是List，遍歷把bean屬性用<code>BeanUtils.copyProperties</code>塞到Vo中</li>
<li>最後用<code>doWrite(dictVoList)</code>讓他一行一行寫下去</li>
</ul>
<p><img src="image-20220108215545141.png" alt="image-20220108215545141"></p>
<ul>
<li>控制器與服務實體類
<ul>
<li>// TODO 這邊我覺得有點怪，為啥接收的參數是<code>response</code>，後端不應該是接<code>req</code>嗎</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">exportData</span>(HttpServletResponse response) {
    response.<span style="color:#658b00">setContentType</span>(<span style="color:#cd5555">&#34;application/vnd.ms-excel&#34;</span>);
    response.<span style="color:#658b00">setCharacterEncoding</span>(<span style="color:#cd5555">&#34;utf-8&#34;</span>);
    <span style="color:#228b22">// 檔案名想取中文用URLEncoder.encode
</span><span style="color:#228b22"></span>    String fileName = (<span style="color:#cd5555">&#34;dict-export-&#34;</span> + <span style="color:#8b008b;font-weight:bold">new</span> LocalDateTime());
    <span style="color:#228b22">// 設定回應是&#34;下載檔案&#34;
</span><span style="color:#228b22"></span>    response.<span style="color:#658b00">setHeader</span>(<span style="color:#cd5555">&#34;Content-disposition&#34;</span>, <span style="color:#cd5555">&#34;attachment;filename=&#34;</span> + fileName + <span style="color:#cd5555">&#34;.xlsx&#34;</span>);

    <span style="color:#228b22">// 查資料庫
</span><span style="color:#228b22"></span>    List&lt;Dict&gt; dictList = baseMapper.<span style="color:#658b00">selectList</span>(<span style="color:#8b008b;font-weight:bold">null</span>);
    <span style="color:#228b22">// 把資料塞到對應的excel表格vo實體類
</span><span style="color:#228b22"></span>    List&lt;DictEeVo&gt; dictVoList = <span style="color:#8b008b;font-weight:bold">new</span> ArrayList&lt;&gt;(dictList.<span style="color:#658b00">size</span>());
    <span style="color:#8b008b;font-weight:bold">for</span> (Dict dict : dictList) {
        DictEeVo dictVo = <span style="color:#8b008b;font-weight:bold">new</span> DictEeVo();
        BeanUtils.<span style="color:#658b00">copyProperties</span>(dict, dictVo, DictEeVo.<span style="color:#658b00">class</span>);
        dictVoList.<span style="color:#658b00">add</span>(dictVo);
    }
    <span style="color:#8b008b;font-weight:bold">try</span> {
        <span style="color:#228b22">// 輸出到回應流讓用戶下載
</span><span style="color:#228b22"></span>        EasyExcel.<span style="color:#658b00">write</span>(response.<span style="color:#658b00">getOutputStream</span>(), DictEeVo.<span style="color:#658b00">class</span>).<span style="color:#658b00">sheet</span>(<span style="color:#cd5555">&#34;dict&#34;</span>).<span style="color:#658b00">doWrite</span>(dictVoList);
    } <span style="color:#8b008b;font-weight:bold">catch</span> (IOException e) {
        e.<span style="color:#658b00">printStackTrace</span>();
    }
}

<span style="color:#707a7c">@ApiOperation</span>(<span style="color:#cd5555">&#34;導出字典檔&#34;</span>)
<span style="color:#707a7c">@GetMapping</span>(<span style="color:#cd5555">&#34;exportDict&#34;</span>)
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">exportDict</span>(HttpServletResponse response) {
    dictService.<span style="color:#658b00">exportData</span>(response);
}
</code></pre></div><ul>
<li>由於要的東西就在HTTP回應中(下載)，這個前端就不寫api了，直接a標籤訪問url
<ul>
<li><code>target=&quot;_blank&quot;</code>開新視窗，否則點一下就跳成空白頁</li>
</ul>
</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-html" data-lang="html">&lt;<span style="color:#8b008b;font-weight:bold">a</span>
<span style="color:#658b00">href</span>=<span style="color:#cd5555">&#34;http://localhost:8202/admin/cmn/dict/exportDict&#34;</span>
<span style="color:#658b00">target</span>=<span style="color:#cd5555">&#34;_blank&#34;</span>
&gt;
&lt;<span style="color:#8b008b;font-weight:bold">el-button</span> <span style="color:#658b00">type</span>=<span style="color:#cd5555">&#34;text&#34;</span>&gt;&lt;<span style="color:#8b008b;font-weight:bold">i</span> <span style="color:#658b00">class</span>=<span style="color:#cd5555">&#34;fa fa-plus&#34;</span> /&gt; 導出&lt;/<span style="color:#8b008b;font-weight:bold">el-button</span>&gt;
&lt;/<span style="color:#8b008b;font-weight:bold">a</span>&gt;
</code></pre></div><hr>
<ul>
<li>想在方法中開啟連接則用<code>window.location.href=&quot;URL&quot;</code></li>
</ul>
<h2 id="導入">導入</h2>
<blockquote>
<p>easyExcel讀取excel表內容，需要用到監聽器</p>
</blockquote>
<ul>
<li>在Controller接收前端來的MultipartFile</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">// DictController
</span><span style="color:#228b22"></span><span style="color:#707a7c">@ApiOperation</span>(<span style="color:#cd5555">&#34;導入字典表格檔&#34;</span>)
<span style="color:#707a7c">@PostMapping</span>(<span style="color:#cd5555">&#34;importDict&#34;</span>) <span style="color:#228b22">// 注意mapping開頭沒有/
</span><span style="color:#228b22"></span><span style="color:#8b008b;font-weight:bold">public</span> Result <span style="color:#008b45">importDict</span>(MultipartFile file) {
    dictService.<span style="color:#658b00">importDict</span>(file);
    <span style="color:#8b008b;font-weight:bold">return</span> Result.<span style="color:#658b00">ok</span>();
}


</code></pre></div><ul>
<li>在DictServiceImpl把流交給監聽器處理</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">importDict</span>(MultipartFile file) {
    <span style="color:#8b008b;font-weight:bold">try</span> {
        EasyExcel.<span style="color:#658b00">read</span>(file.<span style="color:#658b00">getInputStream</span>(), DictEeVo.<span style="color:#658b00">class</span>, <span style="color:#8b008b;font-weight:bold">new</span> DictListener(baseMapper)).<span style="color:#658b00">sheet</span>().<span style="color:#658b00">doRead</span>();
        <span style="color:#228b22">/*
</span><span style="color:#228b22">        DictServiceImpl繼承了ServiceImpl&lt;DictMapper, Dict&gt;
</span><span style="color:#228b22">        DictMapper又繼承了 BaseMapper&lt;Dict&gt;
</span><span style="color:#228b22">        所以在DictServiceImpl的方法中baseMapper其實就是DictMapper
</span><span style="color:#228b22">        */</span>
    } <span style="color:#8b008b;font-weight:bold">catch</span> (IOException e) {
        e.<span style="color:#658b00">printStackTrace</span>();
    }
}
</code></pre></div><ul>
<li>監聽器DictListener需要繼承<code>AnalysisEventListener</code>，這個監聽器會一行一行讀取excel表格中的資料為Vo實體類</li>
<li>直接在此轉為bean並調用mapper存到SQL中</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">DictListener</span> <span style="color:#8b008b;font-weight:bold">extends</span> AnalysisEventListener&lt;DictEeVo&gt; {

    <span style="color:#228b22">// 構造器注入，因為easyExcel官方文檔不建議將listener交給spring管理
</span><span style="color:#228b22"></span>    <span style="color:#8b008b;font-weight:bold">private</span> DictMapper dictMapper;

    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#008b45">DictListener</span>(DictMapper dictMapper) {
        <span style="color:#8b008b;font-weight:bold">this</span>.<span style="color:#658b00">dictMapper</span> = dictMapper;
    }

    <span style="color:#228b22">// 一行一行讀取
</span><span style="color:#228b22"></span>    <span style="color:#707a7c">@Override</span>
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">invoke</span>(DictEeVo dictEeVo, AnalysisContext analysisContext) {
        <span style="color:#228b22">// 讀取表格內容，轉成dict物件
</span><span style="color:#228b22"></span>        Dict dict = <span style="color:#8b008b;font-weight:bold">new</span> Dict();
        BeanUtils.<span style="color:#658b00">copyProperties</span>(dictEeVo, dict);
        <span style="color:#228b22">// 寫到資料庫
</span><span style="color:#228b22"></span>        dictMapper.<span style="color:#658b00">insert</span>(dict);
    }

    <span style="color:#707a7c">@Override</span>
    <span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">doAfterAllAnalysed</span>(AnalysisContext analysisContext) {

    }
}
</code></pre></div><h3 id="前端-1">前端</h3>
<ul>
<li>設2個物件，按鈕與彈出的上傳表格模板</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-html" data-lang="html">&lt;<span style="color:#8b008b;font-weight:bold">el-button</span> <span style="color:#658b00">type</span>=<span style="color:#cd5555">&#34;text&#34;</span> <span style="color:#a61717;background-color:#e3d2d2">@</span><span style="color:#658b00">click</span>=<span style="color:#cd5555">&#34;importDict&#34;</span>
           &gt;&lt;<span style="color:#8b008b;font-weight:bold">i</span> <span style="color:#658b00">class</span>=<span style="color:#cd5555">&#34;fa fa-plus&#34;</span> /&gt; 導入&lt;/<span style="color:#8b008b;font-weight:bold">el-button</span>
    &gt;


&lt;<span style="color:#8b008b;font-weight:bold">el-dialog</span> <span style="color:#658b00">title</span>=<span style="color:#cd5555">&#34;導入&#34;</span> <span style="color:#658b00">:visible</span><span style="color:#a61717;background-color:#e3d2d2">.</span><span style="color:#658b00">sync</span>=<span style="color:#cd5555">&#34;dialogImportVisible&#34;</span> <span style="color:#658b00">width</span>=<span style="color:#cd5555">&#34;480px&#34;</span>&gt;
      &lt;<span style="color:#8b008b;font-weight:bold">el-form</span> <span style="color:#658b00">label-position</span>=<span style="color:#cd5555">&#34;right&#34;</span> <span style="color:#658b00">label-width</span>=<span style="color:#cd5555">&#34;170px&#34;</span>&gt;
        &lt;<span style="color:#8b008b;font-weight:bold">el-form-item</span> <span style="color:#658b00">label</span>=<span style="color:#cd5555">&#34;文件&#34;</span>&gt;
          &lt;<span style="color:#8b008b;font-weight:bold">el-upload</span>
            <span style="color:#658b00">:multiple</span>=<span style="color:#cd5555">&#34;false&#34;</span>
            <span style="color:#658b00">:on-success</span>=<span style="color:#cd5555">&#34;onUploadSuccess&#34;</span>
            <span style="color:#658b00">:action</span>=<span style="color:#cd5555">&#34;&#39;http://localhost:8202/admin/cmn/dict/importDict&#39;&#34;</span>
            <span style="color:#658b00">class</span>=<span style="color:#cd5555">&#34;upload-demo&#34;</span>
          &gt;
            &lt;<span style="color:#8b008b;font-weight:bold">el-button</span> <span style="color:#658b00">size</span>=<span style="color:#cd5555">&#34;small&#34;</span> <span style="color:#658b00">type</span>=<span style="color:#cd5555">&#34;primary&#34;</span>&gt;點擊上傳&lt;/<span style="color:#8b008b;font-weight:bold">el-button</span>&gt;
            &lt;<span style="color:#8b008b;font-weight:bold">div</span> <span style="color:#658b00">slot</span>=<span style="color:#cd5555">&#34;tip&#34;</span> <span style="color:#658b00">class</span>=<span style="color:#cd5555">&#34;el-upload__tip&#34;</span>&gt;
              只能上傳excel文件，且不超過500kb
            &lt;/<span style="color:#8b008b;font-weight:bold">div</span>&gt;
          &lt;/<span style="color:#8b008b;font-weight:bold">el-upload</span>&gt;
        &lt;/<span style="color:#8b008b;font-weight:bold">el-form-item</span>&gt;
      &lt;/<span style="color:#8b008b;font-weight:bold">el-form</span>&gt;
      &lt;<span style="color:#8b008b;font-weight:bold">div</span> <span style="color:#658b00">slot</span>=<span style="color:#cd5555">&#34;footer&#34;</span> <span style="color:#658b00">class</span>=<span style="color:#cd5555">&#34;dialog-footer&#34;</span>&gt;
        &lt;<span style="color:#8b008b;font-weight:bold">el-button</span> <span style="color:#a61717;background-color:#e3d2d2">@</span><span style="color:#658b00">click</span>=<span style="color:#cd5555">&#34;dialogImportVisible = false&#34;</span>&gt; 取消 &lt;/<span style="color:#8b008b;font-weight:bold">el-button</span>&gt;
      &lt;/<span style="color:#8b008b;font-weight:bold">div</span>&gt;
    &lt;/<span style="color:#8b008b;font-weight:bold">el-dialog</span>&gt;
</code></pre></div><ul>
<li>下面新增兩個方法</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-js" data-lang="js"><span style="color:#228b22">// 初始變量處
</span><span style="color:#228b22"></span>dialogImportVisible: <span style="color:#8b008b;font-weight:bold">false</span>, <span style="color:#228b22">// 讓彈框預設不跳出
</span><span style="color:#228b22"></span>
<span style="color:#228b22">// 方法區
</span><span style="color:#228b22"></span>    importDict() {
      <span style="color:#228b22">// 讓彈框跳出
</span><span style="color:#228b22"></span>      <span style="color:#8b008b;font-weight:bold">this</span>.dialogImportVisible = <span style="color:#8b008b;font-weight:bold">true</span>;
    },
    onUploadSuccess(response, file) {
      <span style="color:#8b008b;font-weight:bold">this</span>.$message.info(<span style="color:#cd5555">&#34;上傳成功&#34;</span>);
      <span style="color:#8b008b;font-weight:bold">this</span>.dialogImportVisible = <span style="color:#8b008b;font-weight:bold">false</span>; <span style="color:#228b22">// 讓彈框再滾回去
</span><span style="color:#228b22"></span>      <span style="color:#8b008b;font-weight:bold">this</span>.getList(<span style="color:#b452cd">1</span>); <span style="color:#228b22">// 刷新頁面
</span><span style="color:#228b22"></span>    },
</code></pre></div><hr>
<h2 id="spring-cache">Spring Cache</h2>
<ul>
<li>常讀取、不常修改的資料就很適合放到快取
<ul>
<li>例如:購物網首頁商品、熱門文章等等</li>
</ul>
</li>
</ul>
<h3 id="事前準備">事前準備</h3>
<ul>
<li>由於可以共用，回到common下的service-util子模組，首先導入依賴</li>
</ul>
<pre tabindex="0"><code>&lt;!-- redis --&gt;
&lt;dependency&gt;
    &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;
    &lt;artifactId&gt;spring-boot-starter-data-redis&lt;/artifactId&gt;
&lt;/dependency&gt;

&lt;!-- spring2.X集成redis所需common-pool2--&gt;
&lt;dependency&gt;
    &lt;groupId&gt;org.apache.commons&lt;/groupId&gt;
    &lt;artifactId&gt;commons-pool2&lt;/artifactId&gt;
    &lt;version&gt;2.6.0&lt;/version&gt;
&lt;/dependency&gt;
</code></pre><ul>
<li>新增設定類</li>
</ul>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#707a7c">@Configuration</span>
<span style="color:#707a7c">@EnableCaching</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#8b008b;font-weight:bold">class</span> <span style="color:#008b45;font-weight:bold">RedisConfig</span> {
    <span style="color:#707a7c">@Bean</span>
    <span style="color:#8b008b;font-weight:bold">public</span> KeyGenerator <span style="color:#008b45">keyGenerator</span>() {
        <span style="color:#8b008b;font-weight:bold">return</span> <span style="color:#8b008b;font-weight:bold">new</span> KeyGenerator() {
            <span style="color:#707a7c">@Override</span>
            <span style="color:#8b008b;font-weight:bold">public</span> Object <span style="color:#008b45">generate</span>(Object target, Method method, Object... params) {
                StringBuilder sb = <span style="color:#8b008b;font-weight:bold">new</span> StringBuilder();
                sb.<span style="color:#658b00">append</span>(target.<span style="color:#658b00">getClass</span>().<span style="color:#658b00">getName</span>());
                sb.<span style="color:#658b00">append</span>(method.<span style="color:#658b00">getName</span>());
                <span style="color:#8b008b;font-weight:bold">for</span> (Object obj : params) {
                    sb.<span style="color:#658b00">append</span>(obj.<span style="color:#658b00">toString</span>());
                }
                <span style="color:#8b008b;font-weight:bold">return</span> sb.<span style="color:#658b00">toString</span>();
            }
        };
    }

    <span style="color:#707a7c">@Bean</span>
    <span style="color:#8b008b;font-weight:bold">public</span> RedisTemplate&lt;Object, Object&gt; <span style="color:#008b45">redisTemplate</span>(RedisConnectionFactory redisConnectionFactory) {
        RedisTemplate&lt;Object, Object&gt; redisTemplate = <span style="color:#8b008b;font-weight:bold">new</span> RedisTemplate&lt;&gt;();
        redisTemplate.<span style="color:#658b00">setConnectionFactory</span>(redisConnectionFactory);
        Jackson2JsonRedisSerializer jackson2JsonRedisSerializer = <span style="color:#8b008b;font-weight:bold">new</span> Jackson2JsonRedisSerializer(Object.<span style="color:#658b00">class</span>);

        <span style="color:#228b22">//解決查詢緩存轉換異常的問題
</span><span style="color:#228b22"></span>        ObjectMapper om = <span style="color:#8b008b;font-weight:bold">new</span> ObjectMapper();
        <span style="color:#228b22">// 指定要序列化的域，field,get和set,以及修飾符範圍，ANY是都有包括private和public
</span><span style="color:#228b22"></span>        om.<span style="color:#658b00">setVisibility</span>(PropertyAccessor.<span style="color:#658b00">ALL</span>, JsonAutoDetect.<span style="color:#658b00">Visibility</span>.<span style="color:#658b00">ANY</span>);
        <span style="color:#228b22">// 指定序列化輸入的類型，類必須是非final修飾的，final修飾的類，比如String,Integer等會跑出異常
</span><span style="color:#228b22"></span>        om.<span style="color:#658b00">enableDefaultTyping</span>(ObjectMapper.<span style="color:#658b00">DefaultTyping</span>.<span style="color:#658b00">NON_FINAL</span>);
        jackson2JsonRedisSerializer.<span style="color:#658b00">setObjectMapper</span>(om);

        <span style="color:#228b22">//序列號key value
</span><span style="color:#228b22"></span>        redisTemplate.<span style="color:#658b00">setKeySerializer</span>(<span style="color:#8b008b;font-weight:bold">new</span> StringRedisSerializer());
        redisTemplate.<span style="color:#658b00">setValueSerializer</span>(jackson2JsonRedisSerializer);
        redisTemplate.<span style="color:#658b00">setHashKeySerializer</span>(<span style="color:#8b008b;font-weight:bold">new</span> StringRedisSerializer());
        redisTemplate.<span style="color:#658b00">setHashValueSerializer</span>(jackson2JsonRedisSerializer);

        redisTemplate.<span style="color:#658b00">afterPropertiesSet</span>();
        <span style="color:#8b008b;font-weight:bold">return</span> redisTemplate;
    }

    <span style="color:#707a7c">@Bean</span>
    <span style="color:#8b008b;font-weight:bold">public</span> CacheManager <span style="color:#008b45">cacheManager</span>(RedisConnectionFactory factory) {
        RedisSerializer&lt;String&gt; redisSerializer = <span style="color:#8b008b;font-weight:bold">new</span> StringRedisSerializer();
        Jackson2JsonRedisSerializer jackson2JsonRedisSerializer = <span style="color:#8b008b;font-weight:bold">new</span> Jackson2JsonRedisSerializer(Object.<span style="color:#658b00">class</span>);

        <span style="color:#228b22">//解決查詢緩存轉換異常的問題
</span><span style="color:#228b22"></span>        ObjectMapper om = <span style="color:#8b008b;font-weight:bold">new</span> ObjectMapper();
        om.<span style="color:#658b00">setVisibility</span>(PropertyAccessor.<span style="color:#658b00">ALL</span>, JsonAutoDetect.<span style="color:#658b00">Visibility</span>.<span style="color:#658b00">ANY</span>);
        om.<span style="color:#658b00">enableDefaultTyping</span>(ObjectMapper.<span style="color:#658b00">DefaultTyping</span>.<span style="color:#658b00">NON_FINAL</span>);
        jackson2JsonRedisSerializer.<span style="color:#658b00">setObjectMapper</span>(om);

        <span style="color:#228b22">// 配置序列化（解決亂碼的問題）,過期時間600秒
</span><span style="color:#228b22"></span>        RedisCacheConfiguration config = RedisCacheConfiguration.<span style="color:#658b00">defaultCacheConfig</span>()
                .<span style="color:#658b00">entryTtl</span>(Duration.<span style="color:#658b00">ofSeconds</span>(600))
                .<span style="color:#658b00">serializeKeysWith</span>(RedisSerializationContext.<span style="color:#658b00">SerializationPair</span>.<span style="color:#658b00">fromSerializer</span>(redisSerializer))
                .<span style="color:#658b00">serializeValuesWith</span>(RedisSerializationContext.<span style="color:#658b00">SerializationPair</span>.<span style="color:#658b00">fromSerializer</span>(jackson2JsonRedisSerializer))
                .<span style="color:#658b00">disableCachingNullValues</span>();

        RedisCacheManager cacheManager = RedisCacheManager.<span style="color:#658b00">builder</span>(factory)
                .<span style="color:#658b00">cacheDefaults</span>(config)
                .<span style="color:#658b00">build</span>();
        <span style="color:#8b008b;font-weight:bold">return</span> cacheManager;
    }

}

</code></pre></div><ul>
<li>回到service-cmn設定application.properties</li>
</ul>
<pre tabindex="0"><code class="language-properties" data-lang="properties"># spring redis
spring.redis.host=localhost
spring.redis.port=6379
spring.redis.database=0
spring.redis.timeout=1800000
spring.redis.lettuce.pool.max-active=20
spring.redis.lettuce.pool.max-wait=-1
#最大阻塞等待時間(負數表示沒限制)
spring.redis.lettuce.pool.max-idle=5
spring.redis.lettuce.pool.min-idle=0
</code></pre><h3 id="註解">註解</h3>
<blockquote>
<p>Spring Cache通常在方法上註解</p>
</blockquote>
<ul>
<li><code>@Cacheable</code>:緩存方法的結果，如果請求時已經有快取，就略過方法直接調用快取給結果
<ul>
<li>value:緩存名</li>
<li>cacheNames:同上，二選一即可</li>
<li>key:可選，自訂快取的key</li>
</ul>
</li>
<li><code>@CachePut</code>:無論如何都會執行方法並更新到快取庫
<ul>
<li>結合使用，可以用@CachePut執行方法並更新快取庫</li>
</ul>
</li>
<li><code>@CacheEvict</code>:清空指定快取，通常用於更新或刪除
<ul>
<li>allEntries:清空所有快取，預設為false</li>
<li>beforeInvocation:在方法執行前就清空，預設為false</li>
</ul>
</li>
</ul>
<h3 id="應用">應用</h3>
<div class="highlight"><pre tabindex="0" style="background-color:#eed;-moz-tab-size:4;-o-tab-size:4;tab-size:4"><code class="language-java" data-lang="java"><span style="color:#228b22">// 根據id查詢子數據列表
</span><span style="color:#228b22"></span><span style="color:#707a7c">@Cacheable</span>(value = <span style="color:#cd5555">&#34;dict&#34;</span>, keyGenerator = <span style="color:#cd5555">&#34;keyGenerator&#34;</span>)
<span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> List&lt;Dict&gt; <span style="color:#008b45">getAllChildDictById</span>(Long id) {

<span style="color:#228b22">// 導入數據
</span><span style="color:#228b22"></span><span style="color:#707a7c">@CacheEvict</span>(value = <span style="color:#cd5555">&#34;dict&#34;</span>, allEntries = <span style="color:#8b008b;font-weight:bold">true</span>)
<span style="color:#707a7c">@Override</span>
<span style="color:#8b008b;font-weight:bold">public</span> <span style="color:#00688b;font-weight:bold">void</span> <span style="color:#008b45">importDict</span>(MultipartFile file) {
</code></pre></div><ul>
