				&lt;td&gt;&lt;a class=&quot;deleteClass&quot; href=&quot;BookServlet?action=delete&amp;id=${book.id}&quot;&gt;刪除&lt;/a&gt;&lt;/td&gt;
			&lt;/tr&gt;
		&lt;/c:forEach&gt;
		&lt;tr&gt;
			&lt;td&gt;&lt;/td&gt;
			&lt;td&gt;&lt;/td&gt;
			&lt;td&gt;&lt;/td&gt;
			&lt;td&gt;&lt;/td&gt;
			&lt;td&gt;&lt;/td&gt;
			&lt;td&gt;&lt;/td&gt;
			&lt;td&gt;&lt;a href=&quot;pages/manager/book_edit.jsp&quot;&gt;添加圖書&lt;/a&gt;&lt;/td&gt;
		&lt;/tr&gt;
