<li>book_edit.jsp</li>
</ul>
<pre tabindex="0"><code class="language-jsp" data-lang="jsp">&lt;div id=&quot;main&quot;&gt;
    &lt;form action=&quot;BookServlet&quot; method=&quot;post&quot;&gt;
        &lt;input type=&quot;hidden&quot; name=&quot;action&quot; value=&quot;${empty param.id?&quot;add&quot;:&quot;update&quot;}&quot;/&gt;
